async function restorePersistedMatchCoreProfileBinding() {
  const matchSession = state.match_session;
  if (matchSession?.status !== "active") return { restored: false, reason: "no_active_match" };
  const snapshot = matchSession.season_version_snapshot;
  if (!snapshot) throw new Error("Active match is missing its immutable season_version_snapshot");
  const pinnedPaths = resolveMatchCoreProfileRuntimePaths({
    repoRoot,
    baseRuntimePaths: runtimePaths,
    seasonVersionSnapshot: snapshot,
    expectedCoreProfileId: snapshot.core_profile_id,
  });
  applyRuntimeServicePaths(pinnedPaths);
  refreshActiveRuleState();
  contextPackCache.clear();
  decisionMathServiceCache.clear();
  await writeGameKnowledgeGenerationLeases([
    {
      core_profile_id: pinnedPaths.activeCoreProfileId,
      ranking_overlay_id: snapshot.ranking_overlay_id || null,
      recipe_generation_id: snapshot.recipe_catalog_generation_id || null,
      match_session_id: matchSession.match_session_id,
      status: "active",
      owner: "runtime-service-bootstrap-recovery",
      route_keys: [state.host_sessions?.match?.route_key].filter(Boolean),
      reason: "persisted_match_core_profile_rebound",
    },
  ], {
    release_starting_snapshot_keys: [generationLeaseSnapshotKey(snapshot)],
  });
  recordRuntimeEvent("match_core_profile_rebound", {
    match_session_id: matchSession.match_session_id,
    core_profile_id: pinnedPaths.activeCoreProfileId,
    active_pointer_core_profile_id: createRuntimePaths(repoRoot, { dataRoot: runtimePaths.runtimeDataRoot }).activeCoreProfileId,
  });
  return { restored: true, core_profile_id: pinnedPaths.activeCoreProfileId };
}

