async function readUserStrategyMemory() {
  const canonical = state.user_strategy_memory;
  if (canonical && typeof canonical === "object" && !Array.isArray(canonical)) {
    return structuredClone(canonical);
  }
  return {
    schema: "jcc-runtime-user-memory-v1",
    strategy_rows: [],
    strategy_conflict_notices: [],
  };
}

async function saveStrategyMemory(payload) {
  const text = String(payload.text || "").replace(/\s+/g, " ").trim();
  if (!text) throw new Error("Strategy text is empty");
  const row = {
    text,
    source: "user_confirmed_runtime_ui",
    weight: payload.weight || 1,
    approved: true,
  };
  const applied = applyConfirmedStrategyMemory(await readUserStrategyMemory(), row);
  const result = applied.result;
  state.user_strategy_memory = applied.updated_memory;
  invalidateHostStaticContextSource("user_strategy_memory_changed");
  await persistStateAndCanonicalResponseTask();
  scheduleLegacyJsonMirror(userMemoryFile, state.user_strategy_memory);
  return { ok: true, state, result, user_strategy_memory: state.user_strategy_memory };
}

async function buildWikiCurationRequest(payload = {}) {
  const args = [];
  if (payload.season_id) args.push("--season-id", String(payload.season_id));
  if (payload.patch_id) args.push("--patch-id", String(payload.patch_id));
  if (payload.trigger) args.push("--trigger", String(payload.trigger));
  if (payload.limit) args.push("--limit", String(payload.limit));
  const taskId = randomUUID();
  activeResponseTaskId = taskId;
  state.response_task = {
    status: "running",
    response_task_id: taskId,
    mode: "strategy_wiki",
    origin: "user",
    started_at: new Date().toISOString(),
  };
  await persistStateAndCanonicalResponseTask();
  const result = await runNodeTool("tools/build-jcc-wiki-curation-request.mjs", args, { timeoutMs: 30000 });
  if (process.env.JCC_UI_DISABLE_CODEX_EXEC === "1") {
    state.response_task = {
      status: "awaiting_host_cli_agent_response",
      response_task_id: taskId,
      mode: "strategy_wiki",
      origin: "user",
      host_request: result.host_request,
    };
    await persistStateAndCanonicalResponseTask();
    return {
      ok: true,
      state,
      status: "awaiting_host_cli_agent_response",
      wiki_curation_request: result.host_request,
      result,
    };
  }
  const hostResult = await runAuxiliaryHostRequestInSession({
    mode: "strategy_wiki",
    scope: "startup",
    reason: "strategy_wiki_curation",
    prompt: buildWikiCurationHostPrompt(result.host_request),
    parseJson: true,
    jsonResponseKind: "wiki",
    outputSchema: buildWikiCurationNativeOutputSchema({ runId: result.run_id }),
    responseIdentity: { run_id: result.run_id },
    taskId,
  });
  if (activeResponseTaskId !== taskId) {
    return { ok: false, state, status: "cancelled", message: "Strategy wiki curation was stopped." };
  }
  if (!hostResult.ok) {
    state.response_task = {
      status: "failed",
      response_task_id: taskId,
      mode: "strategy_wiki",
      origin: "user",
      error: hostResult.error,
    };
    await persistStateAndCanonicalResponseTask();
    return { ok: false, state, status: "failed", error: hostResult.error, wiki_curation_request: result.host_request, result };
  }
  if (String(hostResult.response?.schema || "") !== "jcc-wiki-curation-host-response-v1"
      || String(hostResult.response?.generated_by || "") !== HOST_COACH_RESPONSE_GENERATOR
      || String(hostResult.response?.run_id || "") !== String(result.run_id || "")) {
    state.response_task = {
      status: "failed",
      response_task_id: taskId,
      mode: "strategy_wiki",
      origin: "user",
      error: "Strategy wiki Host response identity did not match the sealed run.",
    };
    await persistStateAndCanonicalResponseTask();
    return { ok: false, state, status: "failed", error: state.response_task.error, wiki_curation_request: result.host_request, result };
  }
  const responseFile = path.join(uiRuntimeDir, `wiki-curation-response-${taskId}.json`);
  await writeJsonAtomic(responseFile, hostResult.response);
  const applyResult = await runNodeTool("tools/apply-jcc-wiki-curation-response.mjs", [
    "--response",
    responseFile,
  ], { timeoutMs: 30000 });
  invalidateHostStaticContextSource("strategy_wiki_curation_applied");
  state.response_task = {
    status: "completed",
    response_task_id: null,
    mode: "strategy_wiki",
    origin: "user",
    completed_at: new Date().toISOString(),
  };
  await persistStateAndCanonicalResponseTask();
  return {
    ok: true,
    state,
    status: "completed",
    wiki_curation_request: result.host_request,
    apply_result: applyResult,
    host_response: hostResult.response,
    result,
  };
}

function readStrategyWikiStatus() {
  const store = openRuntimeSqliteStore();
  try {
    const draft_pages = store.listWikiPages({ namespace: "personal_strategy", status: "draft", limit: 20 });
    const published_pages = store.listWikiPages({ namespace: "personal_strategy", status: "published", limit: 20 });
    const stale_pages = store.listWikiPages({ namespace: "personal_strategy", status: "stale", limit: 20 });
    const runs = store.db.prepare(`
      SELECT run_id, trigger_type, status, input_json, output_json, created_at, completed_at
      FROM wiki_curation_runs
      ORDER BY COALESCE(completed_at, created_at) DESC
      LIMIT 5
    `).all().map((row) => {
      let output = {};
      try {
        output = row.output_json ? JSON.parse(row.output_json) : {};
      } catch {
        output = {};
      }
      return {
        run_id: row.run_id,
        trigger_type: row.trigger_type,
        status: row.status,
        created_at: row.created_at,
        completed_at: row.completed_at,
        page_ids: Array.isArray(output.page_ids) ? output.page_ids : [],
        stale_page_ids: Array.isArray(output.stale_page_ids) ? output.stale_page_ids : [],
        user_questions: Array.isArray(output.user_questions) ? output.user_questions.map(String).filter(Boolean) : [],
      };
    });
    const latest_completed_run = runs.find((run) => run.status === "completed") || null;
    return {
      ok: true,
      state,
      status: "completed",
      wiki_status: {
        schema: "jcc-strategy-wiki-status-v1",
        draft_pages,
        published_pages,
        stale_pages,
        recent_runs: runs,
        latest_completed_run,
        pending_questions: latest_completed_run?.user_questions || [],
      },
    };
  } finally {
    store.close();
  }
}

const strategyWikiCategories = [
  "patch_meta_strategy",
  "season_mechanic_strategy",
  "universal_gameplay_strategy",
];

function compactStrategyWikiPageForHost(page) {
  if (!page) return null;
  return {
    page_id: page.page_id || null,
    category: page.category || null,
    scope: page.scope || "unclassified",
    season_id: page.season_id || null,
    patch_id: page.patch_id || null,
    title: clampString(page.title || "", 120),
    summary: clampString(page.summary || "", 360),
    body_md: clampString(page.body_md || "", 700),
    tags: Array.isArray(page.tags) ? page.tags.slice(0, 8) : [],
    source_event_ids: Array.isArray(page.source_event_ids) ? page.source_event_ids.slice(0, 8) : [],
    confidence: page.confidence || "medium",
    updated_at: page.updated_at || null,
  };
}

function strategyWikiPageMatchesActiveScope(page, {
  seasonId = activeSeasonId,
  patchId = activePatchId,
} = {}) {
  const category = String(page?.category || "").trim();
  const pageSeasonId = String(page?.season_id || "").trim();
  const pagePatchId = String(page?.patch_id || "").trim();
  const expectedSeasonId = String(seasonId || "").trim();
  const expectedPatchId = String(patchId || "").trim();
  if (!["cross_season", "current_season"].includes(page?.scope)) return false;
  if (page.scope === "cross_season" && category !== "universal_gameplay_strategy") return false;
  if (page.scope === "current_season" && pageSeasonId !== expectedSeasonId) return false;
  if (category === "universal_gameplay_strategy") {
    return !pageSeasonId && !pagePatchId;
  }
  if (category === "season_mechanic_strategy") {
    return Boolean(expectedSeasonId) && pageSeasonId === expectedSeasonId;
  }
  if (category === "patch_meta_strategy") {
    return Boolean(expectedSeasonId && expectedPatchId)
      && pageSeasonId === expectedSeasonId
      && pagePatchId === expectedPatchId;
  }
  return false;
}

export function captureMatchWikiSnapshot() {
  const store = openRuntimeSqliteStore();
  try {
    const wiki = readStrategyWikiContextForHost({ include_strategy_wiki: true }, { complete: true, captureCurrent: true });
    return store.captureWikiSnapshot(wiki.pages);
  } finally { store.close(); }
}

function readStrategyWikiContextForHost(policy, { complete = false, captureCurrent = false } = {}) {
  if (!policy?.include_strategy_wiki) return null;
  const store = openRuntimeSqliteStore();
  try {
    if (!captureCurrent && state.match_session?.status === "active") {
      const ref = state.match_session.season_version_snapshot?.wiki_snapshot;
      const pages = ref?.snapshot_id ? store.readWikiSnapshot(ref.snapshot_id) : [];
      return { schema: "jcc-strategy-wiki-host-context-v1", available: pages.length > 0,
        snapshot_id: ref?.snapshot_id || null, status: ref ? "pinned" : "legacy_match_wiki_snapshot_unavailable",
        pages: complete ? pages : pages.slice(0, 12).map(compactStrategyWikiPageForHost) };
    }
    const pages = strategyWikiCategories
      .flatMap((category) => store.listWikiPages({
        namespace: "personal_strategy",
        category,
        status: "published",
        limit: complete ? -1 : 24,
      })
        .filter((page) => strategyWikiPageMatchesActiveScope(page))
        .slice(0, complete ? undefined : 4))
      .map(page => complete ? page : compactStrategyWikiPageForHost(page))
      .filter(Boolean)
      .slice(0, complete ? undefined : 12);
    return {
      schema: "jcc-strategy-wiki-host-context-v1",
      available: pages.length > 0,
      status_policy: "published_pages_only",
      scope_policy: "universal_global__season_mechanic_active_major__patch_meta_active_minor",
      active_season_id: activeSeasonId || null,
      active_patch_id: activePatchId || null,
      evidence_priority: "soft_prior_below_live_state_rules_hard_data_big_data",
      categories: strategyWikiCategories,
      pages,
    };
  } finally {
    store.close();
  }
}

function readRecentMatchDecisionSummariesForHost(limit = 20) {
  const store = openRuntimeSqliteStore();
  try {
    return store.listRecentMatchSummaries(limit).map((summary) => ({
      match_session_id: summary.match_session_id || null,
      ended_at: summary.ended_at || null,
      result_rank: summary.result_rank ?? null,
      target_plan_history: Array.isArray(summary.target_plan_history) ? summary.target_plan_history.slice(-8) : [],
      augment_choices: Array.isArray(summary.augment_choices) ? summary.augment_choices.slice(-8) : [],
      item_choice_decisions: Array.isArray(summary.item_choice_decisions) ? summary.item_choice_decisions.slice(-8) : [],
      economy_milestones: summary.economy_milestones || {},
      level_or_roll_decisions: Array.isArray(summary.level_or_roll_decisions) ? summary.level_or_roll_decisions.slice(-8) : [],
      pivot_decisions: Array.isArray(summary.pivot_decisions) ? summary.pivot_decisions.slice(-8) : [],
      advice_task_count: Array.isArray(summary.advice_tasks) ? summary.advice_tasks.length : 0,
      missed_information: Array.isArray(summary.missed_information) ? summary.missed_information.slice(-8) : [],
      review_tags: Array.isArray(summary.review_tags) ? summary.review_tags.slice(0, 12) : [],
    }));
  } finally {
    store.close();
  }
}

function compactUserStrategyMemoryForHost(memory) {
  if (!memory || typeof memory !== "object") return null;
  return {
    schema: memory.schema || "jcc-runtime-user-memory-v1",
    strategy_rows: firstArray(memory.strategy_rows)
      .filter((row) => row?.approved !== false && String(row?.text || "").trim())
      .slice(-24)
      .map((row) => ({
        text: clampString(row.text, 500),
        weight: Number(row.weight || 1),
        source: row.source || null,
      })),
    strategy_conflict_notices: firstArray(memory.strategy_conflict_notices)
      .slice(-8)
      .map((notice) => typeof notice === "string" ? clampString(notice, 400) : notice),
  };
}

function invalidateHostStaticContextSource(_reason = null) {
  hostStaticContextSourceGeneration += 1;
  hostStaticContextSourceCache = null;
  hostStaticContextSourcePending = null;
  proactiveRankingSelectionCache = null;
  proactiveRankingSummaryCache = null;
  liveRankingStrategyDetailCache = {
    stat_date: null, tiers: {}, recipe_storage_by_tier: {}, materialized_candidates_by_tier: {},
    overlay: null, traits_by_id: null, hero_profiles_by_tier: {},
  };
}

function semanticDocumentFromKnowledgeSource(source, sourceId, routeKinds = []) {
  if (!source || typeof source !== "object") return null;
  return {
    id: source.logical_id || sourceId,
    title: source.logical_id || sourceId,
    route_kinds: routeKinds,
    entities: firstArray(source.entity_references || source.season_entity_terms),
    content: JSON.stringify(firstArray(source.entries).map((entry) => ({
      id: entry?.id || null,
      definition: entry?.definition || entry?.description || entry?.policy || null,
      aliases: firstArray(entry?.aliases),
      values: firstArray(entry?.values),
    }))),
  };
}

function coreKnowledgeSemanticDocuments(bundle) {
  if (!bundle || typeof bundle !== "object") return { common: [], season: [], patch: [] };
  const allowedCommonKinds = new Set(["concepts", "glossary", "doctrine", "complete_game_doctrine", "routes", "semantic_features", "cruise_decision_framework", "retrieval_policy"]);
  const common = Object.entries(bundle.common || {})
    .filter(([key]) => allowedCommonKinds.has(key))
    .map(([key, source]) => semanticDocumentFromKnowledgeSource(source, `common.${key}`))
    .filter(Boolean);
  const season = [semanticDocumentFromKnowledgeSource(bundle.season, bundle.season?.logical_id || "active-season")]
    .filter(Boolean);
  const patch = [semanticDocumentFromKnowledgeSource(bundle.patch, bundle.patch?.logical_id || "active-patch")]
    .filter(Boolean);
  return { common, season, patch };
}

function compactCoreKnowledgeForStaticCapsule(bundle) {
  if (!bundle || typeof bundle !== "object") return null;
  return {
    schema: bundle.schema || null,
    core_profile_id: bundle.combined_fingerprint || null,
    profile: bundle.profile || null,
    effective_standard_mechanics: bundle.effective_standard_mechanics || [],
    season: bundle.season || null,
    patch: bundle.patch || null,
    policy: "Common doctrine explains how to reason; typed current-patch indexes and Master+ ranking evidence decide current facts.",
  };
}

function commonHostKnowledgeForStaticCapsule(bundle) {
  if (!bundle?.common || typeof bundle.common !== "object") return null;
  const seen = new Set();
  const sections = [];
  for (const [sourceKey, document] of Object.entries(bundle.common).sort(([left], [right]) => left.localeCompare(right))) {
    const entries = firstArray(document?.entries);
    const renderedEntries = [];
    for (const entry of entries) {
      if (!entry || typeof entry !== "object") continue;
      const body = Object.fromEntries(Object.entries(entry).filter(([key]) => !["schema", "logical_id", "scope", "kind", "season_neutral", "entity_references"].includes(key)));
      const identity = JSON.stringify(body);
      if (seen.has(identity)) continue;
      seen.add(identity);
      renderedEntries.push(body);
    }
    if (!renderedEntries.length) continue;
    sections.push({
      section_id: document.logical_id || `common.${sourceKey}`,
      title: document.title || document.logical_id || sourceKey,
      entries: renderedEntries,
    });
  }
  return {
    schema: "jcc-common-host-knowledge-v1",
    logical_id: "COMMON_HOST_KNOWLEDGE",
    source_kind: "deterministic_view_of_canonical_common",
    completeness: "all_unique_decision_relevant_common_entries",
    usage: "Use this for general game mechanics and strategy doctrine. Current Core, Ranking, Match facts and explicit user intent retain their own authority.",
    sections,
  };
}

function queryCommonHostKnowledge(bundle, args = {}) {
  const common = commonHostKnowledgeForStaticCapsule(bundle);
  if (!common) return { schema: "jcc-common-host-knowledge-result-v1", status: "unavailable", sections: [] };
  const selectors = uniqueStrings([
    ...firstArray(args.entity_names),
    ...firstArray(args.facets),
  ]).map((value) => String(value).normalize("NFKC").toLocaleLowerCase("zh-CN"));
  const normalizedQuestion = String(args.question || "")
    .normalize("NFKC")
    .toLocaleLowerCase("zh-CN");
  const questionTerms = normalizedQuestion
    .split(/[\s，。！？、；：,!?;:]+/u)
    .map((value) => value.trim())
    .filter((value) => value.length >= 2);
  for (const run of normalizedQuestion.match(/[\p{Script=Han}]{2,}/gu) || []) {
    for (const width of [2, 3, 4]) {
      for (let index = 0; index + width <= run.length; index += 1) {
        questionTerms.push(run.slice(index, index + width));
      }
    }
  }
  const terms = selectors.length ? selectors : uniqueStrings(questionTerms);
  const sections = terms.length
    ? common.sections.filter((section) => {
        const searchable = JSON.stringify(section).normalize("NFKC").toLocaleLowerCase("zh-CN");
        return terms.some((term) => searchable.includes(term));
      })
    : common.sections;
  return {
    schema: "jcc-common-host-knowledge-result-v1",
    status: sections.length ? "ok" : "not_found",
    logical_id: common.logical_id,
    completeness: terms.length ? "matching_complete_sections" : common.completeness,
    requested_terms: terms,
    sections,
  };
}

async function getHostStaticContextSource() {
  if (hostStaticContextSourceCache) return hostStaticContextSourceCache;
  if (hostStaticContextSourcePending) return hostStaticContextSourcePending;
  const generation = hostStaticContextSourceGeneration;
  const pending = Promise.all([
    readUserPreferences(),
    readUserStrategyMemory(),
    readLiveRankingsSummary(),
    readSeasonCatalogSummary(),
    readItemBrowseTaxonomySummary(),
    readJson(path.join(path.dirname(runtimePaths.activeHardDataManifest), "indexes/entity_alias_gateway.json"), null),
  ]).then(([userPreferences, userStrategyMemory, dailyBigData, seasonCatalog, itemBrowseTaxonomy, hardDataEntityAliasGateway]) => ({
    schema: "jcc-host-static-context-source-v1",
    core_profile_id: runtimePaths.activeCoreProfileId || null,
    core_profile_ref: structuredClone(runtimePaths.activeCoreProfile || null),
    ranking_overlay_id: dailyBigData?.ranking_overlay_id || `unavailable:${runtimePaths.activeCoreProfileId || "unknown-core"}`,
    ranking_stat_date: dailyBigData?.stat_date || null,
    knowledge_profile: runtimePaths.activeCoreProfile || null,
    core_knowledge: runtimePaths.activeCoreKnowledgeBundle || null,
    semantic_documents: coreKnowledgeSemanticDocuments(runtimePaths.activeCoreKnowledgeBundle),
    version_identity: activeRulesBundle?.version_identity || null,
    promotion_tuple: runtimePaths?.activePromotionTuple || null,
    rules_source_fingerprint: activeRulesBundle?.source_fingerprint || null,
    user_preferences: userPreferences,
    user_strategy_memory: compactUserStrategyMemoryForHost(userStrategyMemory),
    daily_big_data: dailyBigData,
    season_catalog: seasonCatalog,
    ranking_query_catalog: buildRankingQueryEntityCatalog(
      seasonCatalog,
      runtimePaths.activeCoreKnowledgeBundle?.entity_alias_gateway || hardDataEntityAliasGateway,
    ),
    item_browse_taxonomy: itemBrowseTaxonomy,
    strategy_wiki_context: readStrategyWikiContextForHost({ include_strategy_wiki: true }),
    active_rules_bundle: activeRulesBundle,
  }));
  hostStaticContextSourcePending = pending;
  try {
    const source = await pending;
    if (generation !== hostStaticContextSourceGeneration) return getHostStaticContextSource();
    hostStaticContextSourceCache = source;
    return source;
  } finally {
    if (hostStaticContextSourcePending === pending) hostStaticContextSourcePending = null;
  }
}

function traitLookupFromOverlay(overlay, strategyIndex = null) {
  const lookup = { ...(overlay?.traits_by_id || {}) };
  for (const tier of Object.values(strategyIndex?.tiers || {})) {
    for (const candidate of firstArray(tier?.lineup_candidates)) {
      for (const row of firstArray(candidate?.main_trait_list)) {
        const canonicalId = currentCoreTraitIdentity(row?.canonical_trait_id || row?.trait_id);
        if (!canonicalId || lookup[canonicalId]) continue;
        lookup[canonicalId] = {
          id: canonicalId,
          code_id: canonicalId,
          normalized_name: row?.trait_name || null,
          name: row?.trait_name || null,
          source: "ranking_candidate_current_core_semantic_identity",
        };
      }
    }
  }
  return lookup;
}

function isRawRankingSourceTraitIdentity(value) {
  return /^\d{6,8}$/u.test(String(value || "").trim());
}

function currentCoreTraitIdentity(value, traitsById = null) {
  const identity = String(value || "").trim();
  if (!identity) return "";
  if (traitsById && Object.prototype.hasOwnProperty.call(traitsById, identity)) return identity;
  return !isRawRankingSourceTraitIdentity(identity) ? identity : "";
}

function decodedLineupIdMainTraits(lineupId, traitsById) {
  const encoded = String(lineupId || "").replace(/^winlineup_/, "").trim();
  if (!encoded) return [];
  try {
    const decoded = Buffer.from(encoded, "base64").toString("utf8");
    return [...decoded.matchAll(/(\d{8}),(\d+)/g)].map((match) => readableTrait({
      source_trait_id: match[1],
      hero_num: match[2],
    }, traitsById));
  } catch {
    return [];
  }
}

function readableTrait(trait, traitsById) {
  const rawTraitId = String(trait?.trait_id || "").trim();
  const sourceTraitId = String(trait?.source_trait_id || (isRawRankingSourceTraitIdentity(rawTraitId) ? rawTraitId : "")).trim();
  const traitId = currentCoreTraitIdentity(
    trait?.canonical_trait_id
      || trait?.check_id
      || rawTraitId,
    traitsById,
  );
  const count = trait?.hero_num || trait?.chess_num || null;
  const match = traitsById[traitId];
  const name = match?.normalized_name
    || match?.name
    || trait?.source_trait_text
    || trait?.trait_name
    || null;
  const {
    source_trait_id: _sourceTraitId,
    source_family_id: _sourceFamilyId,
    raw_family_id: _rawFamilyId,
    family_id: _familyId,
    ...semanticTrait
  } = trait || {};
  return {
    ...semanticTrait,
    trait_id: traitId || null,
    canonical_trait_id: traitId || null,
    trait_name: name,
    display_name: name && count ? `${name}${count}` : name || (count ? `未知羁绊${count}` : "未知羁绊"),
    semantic_identity_status: traitId ? "canonical" : sourceTraitId ? "unresolved_source_identity" : "unresolved",
  };
}

function readableTraitKey(key, traitsById) {
  return String(key || "")
    .split(";")
    .map((part) => {
      const [traitId, count] = part.split("_");
      return readableTrait({ trait_id: traitId, hero_num: count }, traitsById).display_name;
    })
    .filter(Boolean)
    .join(" + ");
}

function readableRankingEntry(entry, traitsById) {
  const mainTraits = Array.isArray(entry?.main_traits)
    ? entry.main_traits.map((trait) => readableTrait(trait, traitsById))
    : null;
  const mainTraitList = Array.isArray(entry?.main_trait_list)
    ? entry.main_trait_list.map((trait) => readableTrait(trait, traitsById))
    : null;
  const decodedMainTraits = decodedLineupIdMainTraits(entry?.id, traitsById)
    .filter((trait) => trait.canonical_trait_id && trait.trait_name);
  const effectiveMainTraits = decodedMainTraits.length ? decodedMainTraits : (mainTraits || mainTraitList || []);
  const displayParts = effectiveMainTraits.filter((trait) => trait.trait_name).map((trait) => trait.display_name);
  const unresolvedTraits = effectiveMainTraits.filter((trait) => !trait.trait_name).map((trait) => ({
    hero_num: trait.hero_num || trait.chess_num || null,
    semantic_identity_status: trait.semantic_identity_status || "unresolved",
  }));
  const displayName = displayParts.length ? displayParts.join(" + ") : null;
  return {
    ...entry,
    ...(mainTraits ? { main_traits: mainTraits } : {}),
    ...(mainTraitList ? { main_trait_list: mainTraitList } : {}),
    ...(decodedMainTraits.length ? { main_traits: decodedMainTraits } : {}),
    display_name: displayName,
    unresolved_traits: unresolvedTraits,
  };
}

function compactRankingEntries(entries, traitsById, count = 5, rankingMeta = {}) {
  return Array.isArray(entries)
    ? entries.slice(0, count).map((entry) => {
        const readable = readableRankingEntry(entry, traitsById);
        const qualityPacket = buildRankingQualityPacket(readable, rankingMeta);
        return {
          ...readable,
          quality_packet: qualityPacket,
          ranking_quality: rankingCandidateQuality({
            ...readable,
            quality_packet: qualityPacket,
          }),
        };
      })
    : [];
}

function readableHeroItemSignal(entry, championsByRankingId, itemsById) {
  const champion = championsByRankingId[String(entry?.hero_id || "")] || null;
  return {
    hero_id: entry?.hero_id || null,
    hero_name: champion?.normalized_name || champion?.name || null,
    interpretation: entry?.interpretation || "rank_prior_not_perfect_item_combo",
    source: entry?.source || "equip_rank.top_3_hero",
    items: (Array.isArray(entry?.items) ? entry.items : []).slice(0, 4).map((item) => {
      const equip = itemsById[String(item?.equip_id || "")] || null;
      return {
        equip_id: item?.equip_id || null,
        equip_name: equip?.normalized_name || equip?.name || null,
        top1_rate: numericMetric(item?.top1_rate),
        top4_rate: numericMetric(item?.top4_rate),
        avg_rank: numericMetric(item?.avg_rank),
        use_rate: numericMetric(item?.use_rate),
        use_count: numericMetric(item?.use_count),
        signal_score: numericMetric(item?.signal_score),
      };
    }),
  };
}

function compactHeroItemSignals(entries, overlay, count = 5) {
  const championsByRankingId = {};
  for (const champion of Object.values(overlay?.champions_by_id || {})) {
    for (const id of uniqueStrings([
      String(champion?.id || ""),
      String(champion?.id || "").replace(/^\d(?=\d{4}$)/, ""),
    ].filter(Boolean))) {
      championsByRankingId[id] = champion;
    }
  }
  const itemsById = overlay?.items_by_id || {};
  return Array.isArray(entries)
    ? entries.slice(0, count).map((entry) => readableHeroItemSignal(entry, championsByRankingId, itemsById))
    : [];
}

function readableAugmentLineupSignal(entry, overlay, traitsById) {
  const augment = overlay?.augments_by_id?.[String(entry?.augment_id || "")] || null;
  return {
    augment_id: entry?.augment_id || null,
    augment_name: augment?.normalized_name || augment?.name || null,
    source: entry?.source || "lineup_group.info.list.rune_id_group",
    interpretation: entry?.interpretation || "lineup_association_prior_not_independent_augment_winrate",
    not_independent_winrate: entry?.not_independent_winrate === true,
    lineup_count: numericMetric(entry?.lineup_count),
    associated_lineups: (Array.isArray(entry?.associated_lineups) ? entry.associated_lineups : []).slice(0, 3).map((lineup) => ({
      lineup_group_id: lineup?.lineup_group_id || null,
      population: lineup?.population || null,
      main_traits: traitDisplayList(lineup?.main_trait_group || lineup?.main_trait_list, traitsById),
      lineup_ids: Array.isArray(lineup?.lineup_ids) ? lineup.lineup_ids.slice(0, 10).map(String) : [],
      core_chess_ids: Array.isArray(lineup?.core_chess_ids) ? lineup.core_chess_ids.slice(0, 10).map(String) : [],
      evidence_role: "winning_lineup_gameplay_template_association_only",
    })),
  };
}

function compactAugmentLineupSignals(entries, overlay, traitsById, count = 8) {
  return Array.isArray(entries)
    ? entries.slice(0, count).map((entry) => readableAugmentLineupSignal(entry, overlay, traitsById))
    : [];
}

function traitDisplayList(traits, traitsById) {
  return (Array.isArray(traits) ? traits : [])
    .map((trait) => readableTrait({
      trait_id: trait?.canonical_trait_id || trait?.trait_id,
      hero_num: trait?.hero_num ?? trait?.chess_num ?? trait?.count ?? trait?.breakpoint ?? null,
    }, traitsById))
    .filter((trait) => trait?.trait_name)
    .map((trait) => trait.display_name || trait.trait_name);
}

function numericMetric(value) {
  if (value === null || value === undefined || String(value).trim() === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function clampMetric(value, min = 0, max = 1) {
  const parsed = numericMetric(value);
  if (parsed === null) return null;
  return Math.max(min, Math.min(max, parsed));
}

function rankingSampleBand(sampleSize) {
  if (!Number.isFinite(sampleSize) || sampleSize <= 0) return "unknown";
  if (sampleSize >= 250) return "large";
  if (sampleSize >= 100) return "medium";
  if (sampleSize >= 30) return "small";
  return "tiny";
}

function rankingUsageBand(useRate) {
  if (!Number.isFinite(useRate) || useRate <= 0) return "unknown";
  if (useRate >= 0.09) return "mainstream";
  if (useRate >= 0.04) return "visible";
  if (useRate >= 0.015) return "niche";
  return "rare";
}

function buildRankingQualityPacket(entry, { tier = null, version = null, label = null } = {}) {
  if (!entry || typeof entry !== "object") return null;
  const sampleSize = numericMetric(entry?.summary?.use_num ?? entry?.use_num ?? entry?.sample_size);
  const useRate = normalizeRateMetric(entry?.summary?.use_rate ?? entry?.use_rate);
  const top1Rate = normalizeRateMetric(entry?.summary?.top1_rate ?? entry?.top1_rate);
  const top4Rate = normalizeRateMetric(entry?.summary?.top4_rate ?? entry?.top4_rate);
  const avgRank = numericMetric(entry?.summary?.avg_rank ?? entry?.avg_rank);
  const sampleBand = rankingSampleBand(sampleSize);
  const usageBand = rankingUsageBand(useRate);
  const supportScore = clampMetric(
    (sampleSize === null ? 0 : Math.min(1, Math.log10(sampleSize + 1) / 2.3)) * 0.7
    + (useRate === null ? 0 : Math.min(1, useRate / 0.08)) * 0.3,
  );
  const consistencyScore = clampMetric(
    (top4Rate === null ? 0 : top4Rate) * 0.72
    + (avgRank === null ? 0 : Math.max(0, Math.min(1, 1 - (avgRank - 1) / 7))) * 0.28,
  );
  const stabilityScore = clampMetric(
    (supportScore === null ? 0 : supportScore) * 0.58
    + (consistencyScore === null ? 0 : consistencyScore) * 0.42,
  );
  const ceilingScore = clampMetric(top1Rate);
  const mainlineCandidate = Boolean(
    Number.isFinite(sampleSize) && sampleBand === "large"
    && Number.isFinite(useRate) && useRate >= 0.02
    && Number.isFinite(top4Rate) && top4Rate >= 0.55
    && Number.isFinite(avgRank) && avgRank <= 4.8
    && (stabilityScore ?? 0) >= 0.55
  );
  const highCeiling = Boolean(Number.isFinite(top1Rate) && top1Rate >= 0.22 && (ceilingScore ?? 0) >= 0.22);
  return {
    schema: "jcc-ranking-quality-packet-v1",
    tier: tier || null,
    label: label || null,
    version: version || null,
    sample_size: Number.isFinite(sampleSize) ? sampleSize : null,
    use_rate: useRate,
    top1_rate: top1Rate,
    top4_rate: top4Rate,
    avg_rank: avgRank,
    sample_band: sampleBand,
    usage_band: usageBand,
    stability: {
      score: stabilityScore,
      label: stabilityScore === null
        ? "unknown"
        : stabilityScore >= 0.72
          ? "stable_mainstream"
          : stabilityScore >= 0.5
            ? "moderate"
            : stabilityScore >= 0.28
              ? "fragile"
              : "volatile",
      mainline_candidate: mainlineCandidate,
    },
    ceiling: {
      score: ceilingScore,
      label: ceilingScore === null
        ? "unknown"
        : ceilingScore >= 0.28
          ? "high_ceiling"
          : ceilingScore >= 0.18
            ? "moderate_ceiling"
            : "low_ceiling",
      high_ceiling: highCeiling,
    },
    caveats: [
      sampleBand === "tiny" || sampleBand === "small" ? "low_sample_can_overstate_top1" : null,
      !mainlineCandidate ? "not_stable_mainstream" : null,
      highCeiling && !mainlineCandidate ? "high_ceiling_separate_from_stability" : null,
    ].filter(Boolean),
  };
}

function rankingQualityScoreFromPacket(packet) {
  if (!packet || typeof packet !== "object") return 0.5;
  const stability = clampMetric(packet?.stability?.score) ?? 0;
  const ceiling = clampMetric(packet?.ceiling?.score) ?? 0;
  const useRate = clampMetric(packet?.use_rate) ?? 0;
  const supportBonus = packet?.sample_band === "large"
    ? 0.08
    : packet?.sample_band === "medium"
      ? 0.05
      : packet?.sample_band === "small"
        ? 0.01
        : -0.12;
  const mainstreamBonus = packet?.stability?.mainline_candidate ? 0.1 : 0;
  const ceilingBonus = packet?.ceiling?.high_ceiling && !packet?.stability?.mainline_candidate ? 0.02 : 0;
  return Math.max(0, Math.min(1, stability * 0.56 + ceiling * 0.16 + useRate * 0.12 + supportBonus + mainstreamBonus + ceilingBonus));
}

function rankingChampionLookup(overlay) {
  const lookup = {};
  for (const champion of Object.values(overlay?.champions_by_id || {})) {
    for (const id of uniqueStrings([
      champion?.id,
      String(champion?.id || "").replace(/^\d(?=\d{4}$)/, ""),
    ])) lookup[id] = champion;
  }
  return lookup;
}

function catalogEntityName(lookup, id) {
  const entity = lookup?.[String(id || "")] || null;
  return entity?.normalized_name || entity?.name || null;
}

function compactHeroItemPackage(itemPackage) {
  if (!itemPackage || typeof itemPackage !== "object") return null;
  return {
    item_ids: firstArray(itemPackage.item_ids).slice(0, 3),
    item_names: firstArray(itemPackage.item_names).slice(0, 3),
    item_tags: itemPackage.item_tags || {},
    metrics: itemPackage.metrics || null,
    evidence_boundary: "observed_hero_item_package_not_unconditional_best_in_current_match",
  };
}

function compactHeroCoreItems(coreItems) {
  return firstArray(coreItems).map((item) => ({
    item_id: item?.item_id || null,
    item_name: item?.item_name || null,
    item_tags: firstArray(item?.item_tags),
    metrics: item?.metrics || null,
    source_interpretation: item?.source_interpretation || "hero_ranking_published_core_item_evidence",
  })).filter((item) => item.item_id || item.item_name);
}

function compactRankingHeroProfiles(heroProfiles, overlay, count = 100) {
  const champions = rankingChampionLookup(overlay);
  return firstArray(heroProfiles).slice(0, count).map((profile) => ({
    champion_id: profile?.champion_id || null,
    champion_name: profile?.champion_name || catalogEntityName(champions, profile?.champion_id),
    market_prior: profile?.market_prior || null,
    core_items: compactHeroCoreItems(profile?.core_items),
    highest_top1_package: compactHeroItemPackage(profile?.selected_item_packages?.highest_top1),
    most_popular_package: compactHeroItemPackage(profile?.selected_item_packages?.most_popular),
    interpretation: profile?.interpretation || "hero_ranking_is_popularity_contest_pressure_and_item_preference_not_lineup_strength",
  })).filter((profile) => profile.champion_id);
}

function compactRankingReverseIndexes(reverseIndexes, overlay, traitsById) {
  const lookups = {
    augment: overlay?.augments_by_id || {},
    champion: rankingChampionLookup(overlay),
    item: overlay?.items_by_id || {},
    trait: traitsById || {},
  };
  return Object.fromEntries(Object.entries(lookups).map(([kind, lookup]) => {
    const lineupsByEntityId = Object.fromEntries(Object.entries(reverseIndexes?.[kind] || {})
      .map(([entityId, lineupIds]) => [entityId, uniqueStrings(lineupIds)])
      .filter(([, lineupIds]) => lineupIds.length));
    return [kind, {
      lineups_by_entity_id: lineupsByEntityId,
      names_by_entity_id: Object.fromEntries(Object.keys(lineupsByEntityId)
        .map((entityId) => [entityId, catalogEntityName(lookup, entityId)])
        .filter(([, name]) => name)),
    }];
  }));
}

let liveRankingReverseIndexCache = { stat_date: null, tiers: {} };
const rankingQueryRouteState = new Map();

function clearRankingQueryRoutesForMatch(matchSessionId) {
  const normalizedId = String(matchSessionId || "").trim();
  if (!normalizedId) return 0;
  const prefix = `match:${normalizedId}:`;
  let removed = 0;
  for (const routeKey of [...rankingQueryRouteState.keys()]) {
    if (routeKey === `match:${normalizedId}` || routeKey.startsWith(prefix)) {
      rankingQueryRouteState.delete(routeKey);
      removed += 1;
    }
  }
  return removed;
}

function compactLineupPositioningTemplate(template) {
  if (!template || typeof template !== "object") return null;
  return {
    self_board_only: template.self_board_only === true,
    source_interpretation: template.source_interpretation || null,
    coordinates: firstArray(template.coordinates).map((coordinate) => ({
      chess_id: coordinate?.chess_id || null,
      x: coordinate?.x ?? null,
      y: coordinate?.y ?? null,
    })).filter((coordinate) => coordinate.chess_id && coordinate.x !== null && coordinate.y !== null),
  };
}

function compactLineupPlaybook(playbook) {
  if (typeof playbook === "string") return playbook.slice(0, 8000);
  if (!playbook || typeof playbook !== "object") return null;
  const allowedKeys = ["summary", "augment_notes", "early_game", "operation", "equipment", "matchup", "positioning", "replacement"];
  const compact = {};
  for (const key of allowedKeys) {
    const value = playbook[key];
    if (typeof value === "string") compact[key] = value.slice(0, 2400);
    else if (Array.isArray(value)) compact[key] = value.slice(0, 12);
    else if (value && typeof value === "object") compact[key] = value;
  }
  return Object.keys(compact).length ? compact : null;
}

function compactRecipeEvidence(evidence) {
  if (!evidence || typeof evidence !== "object" || !evidence.use_as || !evidence.classification) return null;
  return {
    source_role: evidence.source_role || null,
    recipe_id: evidence.recipe_id || null,
    display_name: evidence.display_name || null,
    source_id: evidence.source_id || null,
    author: evidence.author || null,
    classification: evidence.classification,
    freshness: evidence.freshness || null,
    use_as: evidence.use_as,
    allowed_fields: firstArray(evidence.allowed_fields),
    may_replace_roster: evidence.may_replace_roster === false ? false : null,
    may_merge_variants: evidence.may_merge_variants === false ? false : null,
    may_inherit_strength: evidence.may_inherit_strength === false ? false : null,
    evidence_boundary: evidence.evidence_boundary || null,
  };
}

function compactLineupRoleEntity(entity, champions, items) {
  if (!entity || typeof entity !== "object") return null;
  const itemIds = firstArray(entity.item_ids);
  return {
    champion_id: entity.champion_id || null,
    champion_name: entity.champion_name || catalogEntityName(champions, entity.champion_id),
    item_ids: itemIds,
    item_names: firstArray(entity.item_names).length
      ? firstArray(entity.item_names)
      : itemIds.map((id) => catalogEntityName(items, id)).filter(Boolean),
    ...(entity.confidence ? { confidence: entity.confidence } : {}),
    source_interpretation: entity.source_interpretation || null,
    ...(entity.evidence_boundary ? { evidence_boundary: entity.evidence_boundary } : {}),
  };
}

function compactLineupTransitionForProfile(transition, champions, items) {
  const legacyMainCarryId = transition?.main_carry_id || null;
  const legacyMainCarryItemIds = firstArray(transition?.main_carry_item_ids);
  const legacySupportId = transition?.support_id || null;
  const legacySupportItemIds = firstArray(transition?.support_item_ids);
  const mainCarry = transition?.main_carry || (legacyMainCarryId ? {
    champion_id: legacyMainCarryId,
    item_ids: legacyMainCarryItemIds,
  } : null);
  const supportCandidates = firstArray(transition?.support_candidates).length
    ? firstArray(transition.support_candidates)
    : legacySupportId ? [{ champion_id: legacySupportId, item_ids: legacySupportItemIds }] : [];
  return {
    semantic_role: transition?.semantic_role || "published_transition",
    semantic_role_source: transition?.semantic_role_source || "winning_lineup_variant.excessive_content_data",
    node_status: transition?.node_status || null,
    effective_full_node: transition?.effective_full_node === true,
    population: transition?.population ?? null,
    lineup_ids: firstArray(transition?.lineup_ids),
    lineup_names: firstArray(transition?.lineup_names).length
      ? firstArray(transition.lineup_names)
      : firstArray(transition?.lineup_ids).map((id) => catalogEntityName(champions, id)).filter(Boolean),
    main_carry: compactLineupRoleEntity(mainCarry, champions, items),
    primary_tank: compactLineupRoleEntity(transition?.primary_tank, champions, items),
    support_candidates: supportCandidates
      .map((support) => compactLineupRoleEntity(support, champions, items))
      .filter(Boolean),
    equipment_priority: transition?.equipment_priority || null,
    transfer_recommendations: firstArray(transition?.transfer_recommendations),
    positioning_template: compactLineupPositioningTemplate(transition?.positioning_template),
    item_continuity: transition?.item_continuity || null,
    provenance: transition?.provenance || null,
    evidence_boundary: transition?.evidence_boundary || "published_transition_gameplay_template_without_recipe_metrics",
  };
}

function compactLineupPopulationSemantics(variant) {
  const inferredRosterUnitCount = Math.max(
    firstArray(variant?.atomic_roster_members).length,
    firstArray(variant?.lineup_ids).length,
    firstArray(variant?.lineup_names).length,
  );
  return {
    roster_unit_count: variant?.roster_unit_count ?? inferredRosterUnitCount,
    occupied_population: variant?.occupied_population ?? variant?.population ?? null,
    base_team_size: variant?.base_team_size ?? variant?.population ?? null,
    team_size_bonus: variant?.team_size_bonus ?? 0,
    effective_team_size: variant?.effective_team_size ?? variant?.population ?? null,
    population_legal: variant?.population_legal ?? null,
    team_size_modifiers: firstArray(variant?.team_size_modifiers),
  };
}

function compactAtomicRosterMember(unit) {
  return {
    source_unit_id: unit?.source_unit_id || null,
    entity_kind: unit?.entity_kind || null,
    champion_id: unit?.champion_id || null,
    champion_name: unit?.champion_name || null,
    population_cost: unit?.population_cost ?? (unit?.occupies_population === true ? 1 : 0),
    special_trait_contributions: firstArray(unit?.special_trait_contributions),
    additional_trait_ids: firstArray(unit?.additional_trait_ids),
    occupies_population: unit?.occupies_population === true,
    catalog_resolution: unit?.catalog_resolution || null,
  };
}

function compactLineupVariantForProfile(variant, champions, items, augments, traitsById) {
  const lineupIds = firstArray(variant?.lineup_ids);
  const flexibleUnitIds = firstArray(variant?.flexible_unit_ids);
  const transferItemIds = firstArray(variant?.transfer_item_ids);
  const mainCarry = compactLineupRoleEntity(variant?.main_carry, champions, items);
  const mainCarryItems = firstArray(variant?.main_carry?.item_ids).map((id, index) => ({
    item_id: id,
    item_name: firstArray(variant?.main_carry?.item_names)[index] || catalogEntityName(items, id),
  }));
  const primaryTank = compactLineupRoleEntity(variant?.primary_tank, champions, items);
  const provenAtomicRoster = variant?.roster_is_atomic === true || Boolean(
    variant?.atomic_roster_id
      && variant?.semantic_role === "national_master_plus_atomic_roster"
      && firstArray(variant?.atomic_roster_members).length > 0,
  );
  return {
    variant_id: variant?.variant_id || null,
    atomic_roster_id: variant?.atomic_roster_id || null,
    candidate_evidence_id: variant?.candidate_evidence_id || null,
    roster_is_atomic: provenAtomicRoster,
    semantic_role: variant?.semantic_role || "published_final_lineup_variant",
    semantic_role_source: variant?.semantic_role_source || "winning_lineup_group.info.list",
    lineup_rank: variant?.lineup_rank ?? null,
    population: variant?.population ?? null,
    ...compactLineupPopulationSemantics(variant),
    lineup_ids: lineupIds,
    lineup_names: firstArray(variant?.lineup_names).length
      ? firstArray(variant.lineup_names)
      : lineupIds.map((id) => catalogEntityName(champions, id)).filter(Boolean),
    atomic_roster_members: firstArray(variant?.atomic_roster_members).map(compactAtomicRosterMember),
    unresolved_source_unit_ids: firstArray(variant?.unresolved_source_unit_ids),
    atomic_roster_statistics: variant?.atomic_roster_statistics || null,
    atomic_variant_difference: variant?.atomic_variant_difference || null,
    source_declared_trait_state: variant?.source_declared_trait_state || null,
    trait_state_reconciliation: variant?.trait_state_reconciliation || null,
    canonical_lineup_identity: variant?.canonical_lineup_identity || null,
    core_unit_ids: firstArray(variant?.core_unit_ids),
    core_units: firstArray(variant?.core_units).length
      ? firstArray(variant.core_units)
      : firstArray(variant?.core_unit_ids).map((id) => ({
          champion_id: id,
          champion_name: catalogEntityName(champions, id),
        })),
    flexible_unit_ids: flexibleUnitIds,
    flexible_unit_names: flexibleUnitIds.map((id) => catalogEntityName(champions, id)).filter(Boolean),
    trait_signature: variant?.trait_signature ? {
      key: variant.trait_signature.key || null,
      traits: firstArray(variant.trait_signature.traits).map((trait) => {
        const traitId = currentCoreTraitIdentity(trait?.canonical_trait_id || trait?.trait_id, traitsById) || null;
        return {
          canonical_trait_id: traitId,
          trait_id: traitId,
          trait_name: trait?.trait_name || null,
          breakpoint: trait?.breakpoint ?? null,
          count: trait?.count ?? trait?.breakpoint ?? null,
        };
      }),
    } : null,
    main_carry: mainCarry,
    main_carry_items: mainCarryItems,
    primary_tank: primaryTank,
    support_candidates: firstArray(variant?.support_candidates)
      .map((support) => compactLineupRoleEntity(support, champions, items))
      .filter(Boolean),
    equipment_priority: variant?.equipment_priority || null,
    associated_augments: firstArray(variant?.associated_augments).length
      ? firstArray(variant.associated_augments).map((augment) => ({
          augment_id: augment?.augment_id || null,
          augment_name: augment?.augment_name || catalogEntityName(augments, augment?.augment_id),
        }))
      : firstArray(variant?.associated_augment_ids).map((id) => ({
          augment_id: id,
          augment_name: catalogEntityName(augments, id),
        })),
    transfer_item_ids: transferItemIds,
    transfer_item_names: transferItemIds.map((id) => catalogEntityName(items, id)).filter(Boolean),
    transition_chain: firstArray(variant?.transitions)
      .map((transition) => compactLineupTransitionForProfile(transition, champions, items)),
    positioning_template: compactLineupPositioningTemplate(variant?.positioning_template),
    playbook: compactLineupPlaybook(variant?.playbook),
    lineup_code: variant?.lineup_code || null,
    ...(compactRecipeEvidence(variant?.recipe_evidence)
      ? { recipe_evidence: compactRecipeEvidence(variant.recipe_evidence) }
      : {}),
    ...compactMatureRecipeVariantPacket({
      variants: variant?.mature_recipe_variants,
      receipt: variant?.mature_recipe_variant_receipt || null,
      limit: 6,
    }),
    lifecycle_prior: variant?.lifecycle_prior || null,
    formation_profile: variant?.formation_profile || null,
    season_extensions: variant?.season_extensions || null,
  };
}

function compactLineupVariantForSearch(variant, champions, items, augments, traitsById) {
  const lineupIds = firstArray(variant?.lineup_ids);
  const compactRole = (role) => role ? {
    champion_id: role?.champion_id || null,
    champion_name: role?.champion_name || catalogEntityName(champions, role?.champion_id),
  } : null;
  return {
    variant_id: variant?.variant_id || null,
    population: variant?.population ?? null,
    ...compactLineupPopulationSemantics(variant),
    lineup_ids: lineupIds,
    lineup_names: firstArray(variant?.lineup_names).length
      ? firstArray(variant.lineup_names)
      : lineupIds.map((id) => catalogEntityName(champions, id)).filter(Boolean),
    unresolved_source_unit_ids: firstArray(variant?.unresolved_source_unit_ids),
    source_declared_trait_state: variant?.source_declared_trait_state || null,
    trait_state_reconciliation: variant?.trait_state_reconciliation || null,
    trait_signature: variant?.trait_signature ? {
      traits: firstArray(variant.trait_signature.traits).map((trait) => {
        const traitId = currentCoreTraitIdentity(trait?.canonical_trait_id || trait?.trait_id, traitsById) || null;
        return {
          canonical_trait_id: traitId,
          trait_id: traitId,
          trait_name: trait?.trait_name || null,
          breakpoint: trait?.breakpoint ?? null,
          count: trait?.count ?? trait?.breakpoint ?? null,
        };
      }),
    } : null,
    main_carry: compactRole(variant?.main_carry),
    primary_tank: compactRole(variant?.primary_tank),
  };
}

function lineupVariantTransitions(variant) {
  return firstArray(variant?.transition_chain).length
    ? firstArray(variant.transition_chain)
    : firstArray(variant?.transitions);
}

function compactLineupStrategyProfile(candidate, overlay, traitsById, heroProfilesById = new Map(), { completeVariants = true } = {}) {
  if (!candidate || typeof candidate !== "object") return null;
  const champions = rankingChampionLookup(overlay);
  const items = overlay?.items_by_id || {};
  const augments = overlay?.augments_by_id || {};
  const variants = firstArray(candidate.variants).map((variant) => (
    completeVariants
      ? compactLineupVariantForProfile(variant, champions, items, augments, traitsById)
      : compactLineupVariantForSearch(variant, champions, items, augments, traitsById)
  ));
  const heroProfile = heroProfilesById.get(String(candidate?.main_carry?.champion_id || "")) || null;
  const primaryTankItemEvidence = completeVariants ? Object.fromEntries(uniqueStrings(variants
    .map((variant) => variant?.primary_tank?.champion_id))
    .map((championId) => {
      const role = variants.find((variant) => String(variant?.primary_tank?.champion_id || "") === championId)?.primary_tank || null;
      const profile = heroProfilesById.get(championId) || null;
      return [championId, {
        champion_id: championId,
        champion_name: role?.champion_name || profile?.champion_name || null,
        published_recipe_packages: uniqueStrings(variants
          .filter((variant) => String(variant?.primary_tank?.champion_id || "") === championId)
          .map((variant) => firstArray(variant?.primary_tank?.item_names).join("|")))
          .map((key) => key.split("|").filter(Boolean)),
        hero_ranking_core_items: compactHeroCoreItems(profile?.core_items),
        hero_ranking_highest_top1_package: compactHeroItemPackage(profile?.selected_item_packages?.highest_top1),
        hero_ranking_most_popular_package: compactHeroItemPackage(profile?.selected_item_packages?.most_popular),
        precedence: "published_role_identity_then_hero_ranking_highest_top1_then_most_popular; reconcile_current_match",
      }];
    })) : {};
  return {
    schema: "jcc-compact-lineup-strategy-profile-v3",
    candidate_evidence_id: candidate?.candidate_evidence_id || candidate?.canonical_variant?.candidate_evidence_id || null,
    strength_anchor: candidate?.strength_anchor ? {
      anchor_id: candidate.strength_anchor.anchor_id || null,
      traits: traitDisplayList(candidate.strength_anchor.traits, traitsById),
      metrics: candidate.strength_anchor.metrics || null,
      quality: candidate.strength_anchor.quality || null,
      trend_evidence: candidate.strength_anchor.trend_evidence || null,
      source_interpretation: candidate.strength_anchor.source_interpretation || null,
    } : null,
    recipe_match: candidate?.recipe_match ? {
      classification: candidate.recipe_match.classification || null,
      matched_anchor_id: candidate.recipe_match.matched_anchor_id || null,
      analogous_anchor_id: candidate.recipe_match.analogous_anchor_id || null,
      anchor_family_coverage: candidate.recipe_match.anchor_family_coverage ?? null,
      anchor_breakpoint_coverage: candidate.recipe_match.anchor_breakpoint_coverage ?? null,
      identity_family_coverage: candidate.recipe_match.identity_family_coverage ?? null,
    } : null,
    ...(compactRecipeEvidence(candidate?.recipe_evidence)
      ? { recipe_evidence: compactRecipeEvidence(candidate.recipe_evidence) }
      : {}),
    main_carry: {
      champion_id: candidate?.main_carry?.champion_id || null,
      champion_name: candidate?.main_carry?.champion_name || catalogEntityName(champions, candidate?.main_carry?.champion_id),
      cost: candidate?.main_carry?.cost ?? null,
      source_interpretation: candidate?.main_carry?.source_interpretation || null,
    },
    core_units: firstArray(candidate?.core_units).length
      ? firstArray(candidate.core_units)
      : firstArray(candidate?.core_unit_ids).map((id) => ({
          champion_id: id,
          champion_name: catalogEntityName(champions, id),
        })),
    associated_augments: firstArray(candidate?.associated_augments)
      .slice(0, completeVariants ? firstArray(candidate?.associated_augments).length : 8)
      .map((entry) => ({
      augment_id: entry?.id || null,
      augment_name: entry?.name || catalogEntityName(augments, entry?.id),
      ...(completeVariants ? {
        variant_count: entry?.variant_count ?? null,
        interpretation: "lineup_association_prior_not_independent_augment_winrate",
      } : {}),
    })),
    hero_market_and_item_profile: completeVariants && heroProfile ? {
      champion_id: heroProfile.champion_id || null,
      champion_name: heroProfile.champion_name || null,
      market_prior: heroProfile.market_prior || null,
      core_items: compactHeroCoreItems(heroProfile?.core_items),
      highest_top1_package: compactHeroItemPackage(heroProfile?.selected_item_packages?.highest_top1),
      most_popular_package: compactHeroItemPackage(heroProfile?.selected_item_packages?.most_popular),
      interpretation: heroProfile.interpretation || null,
    } : null,
    primary_tank_item_evidence_by_champion: completeVariants ? primaryTankItemEvidence : {},
    equipment_requirements: completeVariants ? candidate?.equipment_requirements || null : null,
    lifecycle_prior: candidate?.lifecycle_prior || null,
    formation_profile: candidate?.formation_profile || null,
    canonical_lineup_identity: candidate?.canonical_lineup_identity || null,
    semantic_signature: candidate?.semantic_signature || null,
    atomic_variant_comparison: completeVariants ? candidate?.atomic_variant_comparison || null : null,
    ...(completeVariants
      ? compactMatureRecipeVariantPacket({
          variants: candidate?.mature_recipe_variants,
          receipt: candidate?.mature_recipe_variant_receipt || null,
          limit: 6,
        })
      : { mature_recipe_variants: [], mature_recipe_variant_receipt: null }),
    condition_priors: completeVariants ? candidate?.condition_priors || null : null,
    semantic_annotation: completeVariants ? candidate?.semantic_annotation || null : null,
    semantic_features: candidate?.semantic_features || null,
    variants,
    complete_variant_count: variants.length,
    ...(completeVariants ? { complete_variant_detail_ref: candidate?.lineup_group_id || null } : {}),
    ...(completeVariants ? { variant_semantics: {
      final_variant_source: "winning_lineup_group.info.list",
      transition_source: "winning_lineup_variant.excessive_content_data",
      population_does_not_classify_variant_role: true,
    } } : {}),
    provenance: completeVariants ? candidate?.provenance || null : null,
    evidence_boundary: completeVariants ? {
      national_trait_rank_is_strength_anchor: true,
      winning_lineup_is_gameplay_recipe_not_strength_authority: true,
      associated_augments_are_not_independent_win_rates: true,
      hero_popularity_is_not_live_contest_fact: true,
      item_packages_are_not_unconditional_best_items: true,
      positioning_is_self_board_template_only: true,
      runtime_must_reconcile_live_state: true,
    } : null,
  };
}

function compactLineupGroups(strategyCandidates, traitsById, count = null, rankingMeta = {}, overlay = null, heroProfiles = [], { completeStrategyProfiles = true } = {}) {
  const heroProfilesById = new Map(firstArray(heroProfiles)
    .filter((profile) => profile?.champion_id)
    .map((profile) => [String(profile.champion_id), profile]));
  const candidates = firstArray(strategyCandidates);
  const selectedCandidates = Number.isInteger(count) && count >= 0 ? candidates.slice(0, count) : candidates;
  return selectedCandidates.map((candidate) => {
    const variants = firstArray(candidate?.variants);
    const compactVariants = variants.slice(0, 2).map((variant) => ({
      display_name: traitDisplayList(variant?.main_traits, traitsById).join(" + ") || null,
      lineup_rank: variant?.lineup_rank ?? null,
      population: variant?.population ?? null,
      main_traits: traitDisplayList(variant?.main_traits, traitsById),
      sub_traits: traitDisplayList(variant?.sub_traits, traitsById),
      lineup_ids: firstArray(variant?.lineup_ids).slice(0, 16),
      unresolved_source_unit_ids: firstArray(variant?.unresolved_source_unit_ids).slice(0, 4),
      core_chess_ids: firstArray(variant?.core_unit_ids).slice(0, 16),
    }));
    const anchorMainTraits = traitDisplayList(candidate?.strength_anchor?.traits, traitsById);
    const groupMainTraits = traitDisplayList(candidate?.main_trait_list, traitsById);
    const variantMainTraits = firstArray(compactVariants[0]?.main_traits);
    const promotedMainTraits = anchorMainTraits.length
      ? anchorMainTraits
      : variantMainTraits.length ? variantMainTraits : groupMainTraits;
    const strengthMetrics = candidate?.strength_anchor?.metrics || {};
    const presentedMetrics = { ...strengthMetrics };
    const qualityPacket = candidate?.strength_anchor?.quality || buildRankingQualityPacket({
      summary: {
        avg_rank: presentedMetrics.avg_rank,
        top1_rate: presentedMetrics.top1_rate,
        top4_rate: presentedMetrics.top4_rate,
        use_rate: presentedMetrics.use_rate,
        use_num: presentedMetrics.use_num,
      },
    }, rankingMeta);
    return {
      id: candidate?.lineup_group_id || null,
      strength_anchor_id: candidate?.strength_anchor?.anchor_id || null,
      display_name: promotedMainTraits.join(" + ") || null,
      main_traits: promotedMainTraits,
      summary: {
        avg_rank: numericMetric(presentedMetrics.avg_rank),
        top1_rate: numericMetric(presentedMetrics.top1_rate),
        top4_rate: numericMetric(presentedMetrics.top4_rate),
        use_rate: numericMetric(presentedMetrics.use_rate),
        use_num: numericMetric(presentedMetrics.use_num),
        source_interpretation: "national_trait_ranking_primary_strength_evidence",
        sample_size_source_interpretation: numericMetric(strengthMetrics.use_num) !== null
          ? "national_trait_ranking_sample_size"
          : "sample_size_missing",
        quality_packet: qualityPacket,
      },
      quality_packet: qualityPacket,
      strategy_profile: compactLineupStrategyProfile(candidate, overlay, traitsById, heroProfilesById, {
        completeVariants: completeStrategyProfiles,
      }),
      ...(completeStrategyProfiles ? { variants: compactVariants } : {}),
      ...(completeStrategyProfiles ? { variant_search_index: variants.map((variant) => ({
        lineup_rank: variant?.lineup_rank ?? null,
        main_traits: traitDisplayList(variant?.main_traits, traitsById),
        sub_traits: traitDisplayList(variant?.sub_traits, traitsById).slice(0, 6),
        lineup_ids: firstArray(variant?.lineup_ids).slice(0, 16),
        lineup_names: firstArray(variant?.lineup_names).slice(0, 16),
        unresolved_source_unit_ids: firstArray(variant?.unresolved_source_unit_ids).slice(0, 4),
        core_chess_ids: firstArray(variant?.core_unit_ids).slice(0, 16),
        core_chess_names: firstArray(variant?.core_units).map((unit) => unit?.champion_name).filter(Boolean).slice(0, 16),
      })) } : {}),
    };
  });
}

function traitNameByCodeFromOverlay(overlay) {
  const out = {};
  for (const trait of Object.values(overlay?.traits_by_id || {})) {
    const code = String(trait?.code_id || "").trim();
    const name = trait?.normalized_name || trait?.name || null;
    if (code && name && !out[code]) out[code] = name;
  }
  return out;
}

function uniqueChampionEntries(overlay, aliasesByName = new Map()) {
  const traitByCode = traitNameByCodeFromOverlay(overlay);
  const byName = new Map();
  for (const champion of Object.values(overlay?.champions_by_id || {})) {
    const name = champion?.normalized_name || champion?.name || null;
    const cost = Number(champion?.cost);
    if (!name || !Number.isFinite(cost) || cost <= 0) continue;
    const traitCodes = uniqueStrings([champion?.class_or_trait_codes, champion?.shop_or_pool_code]
      .filter((value) => value !== null && value !== undefined)
      .flatMap((value) => String(value).split("|"))
      .map((code) => code.trim())
      .filter((code) => code && code !== "-1"));
    const traits = traitCodes.map((code) => traitByCode[code] || code).filter(Boolean);
    const existing = byName.get(name);
    const entry = {
      name,
      cost,
      traits,
      ids: [String(champion.id)].filter(Boolean),
      ranking_ids: uniqueStrings([
        String(champion.id || ""),
        String(champion.id || "").replace(/^\d(?=\d{4}$)/, ""),
      ].filter(Boolean)),
      aliases: uniqueStrings(aliasesByName.get(name) || []),
    };
    if (!existing) {
      byName.set(name, entry);
      continue;
    }
    existing.cost = Math.min(existing.cost, cost);
    existing.traits = uniqueStrings([...existing.traits, ...traits]);
    existing.ids = uniqueStrings([...existing.ids, ...entry.ids]);
    existing.ranking_ids = uniqueStrings([...(existing.ranking_ids || []), ...entry.ranking_ids]);
    existing.aliases = uniqueStrings([...(existing.aliases || []), ...entry.aliases]);
  }
  return [...byName.values()].sort((a, b) => a.cost - b.cost || a.name.localeCompare(b.name, "zh-Hans-CN"));
}

async function readSeasonCatalogSummary() {
  const [overlay, decisionCatalog] = await Promise.all([
    readJson(mumuCatalogOverlayFile, null),
    readJson(runtimePaths.activeDecisionInputCatalogFile, null),
  ]);
  const championNameByAddress = new Map(firstArray(decisionCatalog?.entities)
    .filter((entity) => entity?.kind === "champion")
    .map((entity) => [String(entity.address), String(entity.name)]));
  const aliasesByName = new Map();
  for (const alias of firstArray(decisionCatalog?.aliases)) {
    if (alias?.ref?.kind !== "champion" || alias?.evidence_kind !== "player_alias") continue;
    const name = championNameByAddress.get(String(alias?.ref?.address || ""));
    if (!name) continue;
    aliasesByName.set(name, uniqueStrings([...(aliasesByName.get(name) || []), alias.alias]));
  }
  const champions = uniqueChampionEntries(overlay, aliasesByName);
  const traitsByName = new Map();
  for (const trait of Object.values(overlay?.traits_by_id || {})) {
    const name = trait?.normalized_name || trait?.name || null;
    if (!name) continue;
    const id = String(trait?.id || "").trim();
    const rankingFamilyId = /^\d{8}$/.test(id) ? id.slice(0, 6) : null;
    const existing = traitsByName.get(name) || {
      name,
      code_id: trait?.code_id || null,
      ranking_ids: [],
      breakpoints: trait?.breakpoints || null,
    };
    if (rankingFamilyId && !existing.ranking_ids.includes(rankingFamilyId)) existing.ranking_ids.push(rankingFamilyId);
    traitsByName.set(name, existing);
  }
  const traits = [...traitsByName.values()].sort((a, b) => a.name.localeCompare(b.name, "zh-Hans-CN"));
  const championsByCost = {};
  for (const champion of champions) {
    const key = String(champion.cost);
    if (!championsByCost[key]) championsByCost[key] = [];
    championsByCost[key].push(champion);
  }
  return {
    schema: "jcc-season-catalog-host-context-summary-v1",
    source: "active_core_profile.runtime_catalog_overlay_path",
    active_season: activeSeasonId || "unknown",
    active_patch_id: activePatchId || null,
    champion_count: champions.length,
    trait_count: traits.length,
    champions_by_cost: championsByCost,
    champion_names: champions.map((champion) => champion.name),
    traits,
    policy: {
      current_season_only: true,
      do_not_invent_champions: true,
      if_name_missing: "Say it is not in the current season catalog or ask for clarification.",
    },
  };
}

function buildRankingQueryEntityCatalog(seasonCatalog, entityAliasGateway) {
  const entities = [];
  const byKindAndName = new Map();
  const addEntity = (kind, raw) => {
    const name = String(raw?.name || "").normalize("NFKC").trim();
    const rankingIds = firstArray(raw?.ranking_ids, raw?.ids).map((value) => String(value || "").trim()).filter(Boolean);
    const id = String((kind === "trait" ? rankingIds[0] : raw?.code_id) || raw?.code_id || rankingIds[0] || name).trim();
    if (!name || !id) return;
    const entity = { kind, id, name, aliases: [], ids: uniqueStrings([id, raw?.code_id, ...rankingIds]) };
    entities.push(entity);
    byKindAndName.set(`${kind}:${normalizeSearchText(name)}`, entity);
  };
  for (const trait of firstArray(seasonCatalog?.traits)) addEntity("trait", trait);
  for (const champion of Object.values(seasonCatalog?.champions_by_cost || {}).flat()) addEntity("champion", champion);

  for (const [alias, gatewayEntry] of Object.entries(entityAliasGateway?.lookup || {})) {
    const refs = firstArray(gatewayEntry?.r || gatewayEntry?.results);
    if (refs.length !== 1) continue;
    const ref = refs[0];
    const kind = String(ref?.entity_kind || "");
    if (!new Set(["trait", "champion"]).has(kind)) continue;
    const normalizedAlias = String(gatewayEntry?.n || alias || "").normalize("NFKC").trim();
    if (normalizedAlias.length < 2 || normalizedAlias.length > 24 || !/[\p{Script=Han}A-Za-z]/u.test(normalizedAlias)) continue;
    const entity = byKindAndName.get(`${kind}:${normalizeSearchText(ref?.entity_name)}`);
    if (entity) entity.aliases.push(normalizedAlias);
  }

  const traits = entities.filter((entity) => entity.kind === "trait");
  const prefixOwners = new Map();
  for (const trait of traits) {
    const name = String(trait.name);
    for (let length = 2; length < name.length; length += 1) {
      const prefix = name.slice(0, length);
      const owners = prefixOwners.get(prefix) || [];
      owners.push(trait);
      prefixOwners.set(prefix, owners);
    }
  }
  for (const [prefix, owners] of prefixOwners) {
    if (owners.length === 1) owners[0].aliases.push(prefix);
  }
  for (const entity of entities) entity.aliases = uniqueStrings(entity.aliases).filter((alias) => alias !== entity.name);
  return {
    schema: "jcc-ranking-query-entity-catalog-v1",
    source: "active_hard_data_entity_alias_gateway_plus_unique_trait_prefixes",
    entities,
    policy: "Current-season exact aliases plus unambiguous trait-name prefixes; ambiguous aliases remain unresolved.",
  };
}

async function readItemBrowseTaxonomySummary(catalogFile = runtimePaths.activeDecisionInputCatalogFile) {
  const decisionCatalog = await readJson(catalogFile, null);
  const normalizedItems = firstArray(decisionCatalog?.entities).filter((entity) => entity?.kind === "item");
  const itemNamesByBrowseFacet = {};
  const itemNamesByPrimaryRole = {};
  let classifiedItemCount = 0;
  for (const item of firstArray(normalizedItems)) {
    const name = String(item?.name || "").trim();
    const facets = uniqueStrings(item?.browse_facets);
    const primaryRole = String(item?.primary_role || "").trim();
    if (!name || !facets.length || !primaryRole || primaryRole === "unclassified") continue;
    classifiedItemCount += 1;
    for (const facet of facets) {
      if (!itemNamesByBrowseFacet[facet]) itemNamesByBrowseFacet[facet] = [];
      itemNamesByBrowseFacet[facet].push(name);
    }
    if (!itemNamesByPrimaryRole[primaryRole]) itemNamesByPrimaryRole[primaryRole] = [];
    itemNamesByPrimaryRole[primaryRole].push(name);
  }
  for (const rows of [...Object.values(itemNamesByBrowseFacet), ...Object.values(itemNamesByPrimaryRole)]) {
    rows.sort((left, right) => left.localeCompare(right, "zh-Hans-CN"));
  }
  return {
    schema: "jcc-season-item-browse-taxonomy-v1",
    source: "active_core_profile.decision-input-catalog.json",
    taxonomy_status: "version_compiled_explicit_item_usage",
    classified_item_count: classifiedItemCount,
    items_by_browse_facet: itemNamesByBrowseFacet,
    items_by_primary_role: itemNamesByPrimaryRole,
    policy: "Curated retrieval and role semantics, not an automatic itemization verdict. Exact effects, holder fit, live HP, economy, components, traits, augments, and target plan decide the action.",
  };
}

function expectedRankingCoreIdentity() {
  const pinned = state.match_session?.status === "active"
    ? state.match_session?.season_version_snapshot
    : null;
  const sourceIdentity = pinned?.core_source_identity
    || runtimePaths.activeDecisionInputCatalogSourceIdentity
    || {};
  return {
    core_profile_id: pinned?.core_profile_id || runtimePaths.activeCoreProfileId || null,
    hard_data_manifest_fingerprint: sourceIdentity.hard_data_manifest_fingerprint || null,
    catalog_source_fingerprint: sourceIdentity.catalog_source_fingerprint || null,
  };
}

