  "source_fingerprint",
  "provenance",
  "audit",
  "diagnostics",
  "source_diagnostics",
  "item_source_diagnostics",
  "parse_rejection_counts",
  "unknown_command_counts",
  "equipment_like_unknown_command_counts",
  "payload_shape_counts_by_command",
  "adb_target",
  "last_watcher_stdout",
  "last_watcher_error",
  "debug_evidence_dir",
  "image_reference",
