function hostSessionWarmupRequest(mode, contextPack, route) {
  const requestId = `host-session-bootstrap:${route.key}:${Date.now()}`;
  return {
    schema: "jcc-host-session-bootstrap-request-v1",
    request_id: requestId,
    request_hash: requestId,
    mode,
    task: {
      type: "session_bootstrap_only",
      route_key: route.key,
      answer_owner: "none",
    },
    user_message: null,
    context_pack: contextPack || null,
    response_style: "bootstrap_ack_only",
  };
}

async function warmHostSession({ scope, mode, contextPack = null, reason = "runtime_start" } = {}) {
  if (!state.host_cli?.available || !state.host_cli?.command) {
    return { ok: false, status: "host_cli_unavailable" };
  }
  const route = currentHostSessionRoute(mode);
  const providerIdentity = currentHostProviderIdentity();
  const hostCli = structuredClone(state.host_cli);
  const warmupKey = hostSessionWarmupKey(route, providerIdentity);
  const existing = hostSessionWarmups.get(warmupKey);
  if (existing) return existing;
  const warmup = (async () => {
    const pack = contextPack || await getOrBuildContextPack(scope || (route.kind === "match" ? "match" : "startup"), mode);
    if (!hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity())) {
      return { ok: false, status: "warmup_provider_expired", route_key: route.key };
    }
    const request = hostSessionWarmupRequest(mode, pack, route);
    const enriched = await enrichHostRequestWithRuntimeContext(request, mode, pack);
    if (!hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity())) {
      return { ok: false, status: "warmup_provider_expired", route_key: route.key };
    }
    let invocation = prepareHostSessionInvocation(enriched);
    if (!invocation.context_sync_required && !invocation.transport_recovery_required) {
      if (hostSessionReadyForTurn(route)) {
        return {
          ok: true,
          status: "already_warm",
          route_key: route.key,
          capsule_id: invocation.capsule.capsule_id,
          readonly_tool_mode: state.host_sessions?.[route.kind]?.readonly_tool_mode || "prefetch_complete",
        };
      }
      await closeHostAgentSession(route.key).catch(() => {});
      resetHostSessionDescriptor(route, "host_session_not_ready_for_turn");
      invocation = prepareHostSessionInvocation(enriched);
    }
    state.host_sessions[route.kind] = {
      ...(state.host_sessions[route.kind] || {}),
      status: "warming",
      route_key: route.key,
      warming_started_at: new Date().toISOString(),
      warming_reason: reason,
    };
    await persistHostSessionState(route.kind, "warmup_started");
    const warmupPrompt = () => invocation.bootstrap_required
        ? buildHostSessionWarmupPrompt(enriched, invocation.capsule)
        : invocation.static_context_update_required
          ? buildHostStaticContextUpdatePrompt(enriched, invocation.capsule, { acknowledgementOnly: true })
          : buildHostSessionRecoveryProbePrompt(invocation.capsule);
    // Bootstrap only acknowledges the static capsule. It does not need the
    // current gameplay delta, and spending xhigh reasoning on an ack delays
    // the first real user turn without improving later answer quality.
    const warmupHostCli = hostCli.provider === "codex"
      && ![null, undefined, "default", "low"].includes(hostCli.reasoning_effort)
      ? { ...hostCli, reasoning_effort: "low" }
      : hostCli;
    const runWarmup = () => runHostAgentRequest(
      warmupHostCli,
      warmupPrompt(),
      {
        parseJson: true,
        jsonResponseKind: "session_warmup",
        outputSchema: HOST_SESSION_WARMUP_NATIVE_OUTPUT_SCHEMA,
        repoRoot,
        taskId: `host-session-warmup:${warmupKey}`,
        timeoutMs: Number(process.env.JCC_UI_HOST_SESSION_WARMUP_TIMEOUT_MS || 300000),
        hostSessionKey: route.key,
        hostSessionId: invocation.host_session_id,
        providerSessionBootstrap: invocation.bootstrap_required,
        bootstrapCapsuleId: invocation.capsule.capsule_id,
      },
    );
    let result = await runWarmup();
    if (result.requires_bootstrap && result.thread_id
      && hostInvocationOwnsCurrentRoute(invocation, mode)) {
      invocation = {
        ...invocation,
        bootstrap_required: true,
        static_context_update_required: false,
        context_sync_required: true,
        transport_recovery_required: false,
        host_session_id: result.thread_id,
      };
      state.host_sessions[route.kind] = {
        ...(state.host_sessions[route.kind] || {}),
        status: "warming",
        provider_session_id: result.thread_id,
        capability_receipt: null,
        bootstrap_status: "required",
        context_fingerprint: null,
        route_key: route.key,
        warming_reason: `${reason}_replacement_full_bootstrap`,
      };
      await persistHostSessionState(route.kind, "warmup_replacement_bootstrap_started");
      result = await runWarmup();
    }
    if (!hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity())) {
      return { ok: false, status: "warmup_provider_expired", route_key: route.key };
    }
    if (!result.ok && invocation.host_session_id && hostSessionResumeFailure(result.error)) {
      recordRuntimeEvent("host_provider_session_warmup_resume_failed_rebootstrap", {
        route_key: route.key,
        provider_session_id: invocation.host_session_id,
        error: sanitizedHostDiagnosticTail(result.error, 600),
      });
      await closeHostAgentSession(route.key).catch(() => {});
      resetHostSessionDescriptor(route, "warmup_provider_session_resume_failed");
      invocation = prepareHostSessionInvocation(enriched);
      state.host_sessions[route.kind] = {
        ...(state.host_sessions[route.kind] || {}),
        status: "warming",
        route_key: route.key,
        warming_started_at: new Date().toISOString(),
        warming_reason: `${reason}_session_rebootstrap`,
      };
      await persistHostSessionState(route.kind, "warmup_rebootstrap_started");
      result = await runWarmup();
    }
    const accepted = result.ok
      && result.response?.schema === "jcc-host-session-bootstrap-ack-v1"
      && result.response?.capsule_id === invocation.capsule.capsule_id
      && result.response?.accepted === true;
    if (currentHostSessionRoute(mode).key !== route.key) {
      await closeHostAgentSession(route.key).catch(() => {});
      return { ok: false, status: "warmup_route_expired", route_key: route.key };
    }
    if (!hostProviderIdentityMatches(invocation.provider_identity, currentHostProviderIdentity())) {
      return { ok: false, status: "warmup_provider_expired", route_key: route.key };
    }
    if (!accepted) {
      await closeHostAgentSession(route.key).catch(() => {});
      resetHostSessionDescriptor(route, "warmup_failed_session_closed");
      state.host_sessions[route.kind] = {
        ...(state.host_sessions[route.kind] || {}),
        status: "warmup_failed",
        last_failed_capability_receipt: result.capability_receipt || null,
        last_error: sanitizedHostDiagnosticTail(result.error || "invalid bootstrap acknowledgement", 600),
        last_error_at: new Date().toISOString(),
      };
      await persistHostSessionState(route.kind, "warmup_failed");
      return { ok: false, status: "warmup_failed", route_key: route.key, error: result.error || "invalid bootstrap acknowledgement" };
    }
    commitHostSessionInvocation(invocation, result);
    state.host_sessions[route.kind] = {
      ...state.host_sessions[route.kind],
      warmup_completed_at: new Date().toISOString(),
      warming_reason: reason,
    };
    await persistHostSessionState(route.kind, "warmup_completed");
    return {
      ok: true,
      status: "warmed",
      route_key: route.key,
      capsule_id: invocation.capsule.capsule_id,
      provider_session_id: result.thread_id || result.session_id || null,
      readonly_tool_mode: result.readonly_tool_mode || "prefetch_complete",
      capability_receipt: result.capability_receipt || null,
    };
  })().finally(() => {
    if (hostSessionWarmups.get(warmupKey) === warmup) hostSessionWarmups.delete(warmupKey);
  });
  hostSessionWarmups.set(warmupKey, warmup);
  return warmup;
}

function scheduleHostSessionWarmup(options) {
  void warmHostSession(options)
    .then((result) => {
      recordRuntimeEvent("host_provider_session_warmup_finished", {
        reason: options?.reason || null,
        mode: options?.mode || null,
        ...result,
      });
    })
    .catch((error) => {
      recordRuntimeEvent("host_provider_session_warmup_failed", {
        reason: options?.reason || null,
        mode: options?.mode || null,
        error: sanitizedHostDiagnosticTail(error?.message || error, 600),
      });
    });
}

async function ensureHostSessionReadyForTurn({ mode, contextPack = null, reason = "host_turn" } = {}) {
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const route = currentHostSessionRoute(mode);
    const providerIdentity = currentHostProviderIdentity();
    const inFlight = hostSessionWarmups.get(hostSessionWarmupKey(route, providerIdentity));
    if (inFlight) {
      const result = await inFlight.catch((error) => ({
        ok: false,
        status: "warmup_failed",
        error: error?.message || String(error),
      }));
      const identityChanged = currentHostSessionRoute(mode).key !== route.key
        || !hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity());
      if (identityChanged || result?.status === "warmup_provider_expired" || result?.status === "warmup_route_expired") continue;
      if (!result?.ok) return result;
    }
    if (hostSessionReadyForTurn(route)) {
      return {
        ok: true,
        status: "ready",
        route_key: route.key,
        provider_session_id: state.host_sessions?.[route.kind]?.provider_session_id || null,
        readonly_tool_mode: state.host_sessions?.[route.kind]?.readonly_tool_mode || "prefetch_complete",
      };
    }
    const result = await warmHostSession({
      scope: route.kind === "match" ? "match" : "startup",
      mode,
      contextPack,
      reason,
    });
    const identityChanged = currentHostSessionRoute(mode).key !== route.key
      || !hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity());
    if (identityChanged || result?.status === "warmup_provider_expired" || result?.status === "warmup_route_expired") continue;
    if (!result?.ok) return result;
    const currentRoute = currentHostSessionRoute(mode);
    if (hostSessionReadyForTurn(currentRoute)) return result;
  }
  const route = currentHostSessionRoute(mode);
  return {
    ok: false,
    status: "host_session_not_ready",
    error: "Host session initialization completed without a writable current provider route.",
    route_key: route.key,
  };
}

async function runAuxiliaryHostRequestInSession({
  mode,
  scope,
  reason,
  prompt,
  taskId,
  parseJson = true,
  jsonResponseKind = null,
  outputSchema = null,
  responseIdentity = null,
  timeoutMs = Number(process.env.JCC_UI_HOST_AGENT_TIMEOUT_MS || 300000),
} = {}) {
  await ensureHostCliReady();
  let route = currentHostSessionRoute(mode);
  const warmup = await warmHostSession({ scope, mode, reason });
  if (!warmup.ok) throw new Error(warmup.error || `Host session warmup failed for ${route.key}`);
  let descriptor = state.host_sessions?.[route.kind] || {};
  let providerIdentity = currentHostProviderIdentity();
  let hostCli = structuredClone(state.host_cli);
  const ownsCurrentRoute = () => currentHostSessionRoute(mode).key === route.key
    && hostProviderIdentityMatches(providerIdentity, currentHostProviderIdentity());
  const invoke = () => runHostAgentRequest(hostCli, prompt, {
    parseJson,
    ...(jsonResponseKind ? { jsonResponseKind } : {}),
    ...(outputSchema ? { outputSchema } : {}),
    repoRoot,
    taskId,
    timeoutMs,
    hostSessionKey: route.key,
    hostSessionId: descriptor.provider_session_id || null,
  });
  let result = await invoke();
  if (!ownsCurrentRoute()) {
    return {
      ok: false,
      status: "host_session_route_expired",
      error: "Host session route or provider changed before this auxiliary turn completed.",
    };
  }
  if (!result.ok && descriptor.provider_session_id && hostSessionResumeFailure(result.error)) {
    await closeHostAgentSession(route.key).catch(() => {});
    resetHostSessionDescriptor(route, "auxiliary_provider_session_resume_failed");
    const rebuilt = await warmHostSession({ scope, mode, reason: `${reason || "auxiliary"}_rebootstrap` });
    if (!rebuilt.ok) return result;
    route = currentHostSessionRoute(mode);
    descriptor = state.host_sessions?.[route.kind] || {};
    providerIdentity = currentHostProviderIdentity();
    hostCli = structuredClone(state.host_cli);
    result = await invoke();
  }
  if (!ownsCurrentRoute()) {
    return {
      ok: false,
      status: "host_session_route_expired",
      error: "Host session route or provider changed before this auxiliary turn completed.",
    };
  }
  if (result.ok) {
    state.host_sessions[route.kind] = {
      ...state.host_sessions[route.kind],
      status: "ready",
      provider_session_id: result.thread_id || result.session_id || descriptor.provider_session_id || null,
      last_used_at: new Date().toISOString(),
    };
    await persistHostSessionState(route.kind, "auxiliary_turn_completed");
  }
  return result;
}

function buildVisualHostPrompt(visionRequest) {
  const choiceContract = runtimeChoiceModeContract(visionRequest?.mode);
  return [
    "You are the host CLI multimodal model for JCC Runtime visual sensing.",
    "Inspect the attached image using your native visual capability. INPUT_JSON.frame.image_reference.path is metadata only; do not try to open it as a text-only path.",
    "Return exactly one JSON object. No Markdown. No code fence.",
    "Use only facts visible in the current frame plus the provided candidate database and MuMu anchors.",
    "Do not guess hidden augments, equipped items, or choices. Use confidence below 0.75 or needs_confirmation=true when unclear.",
    choiceContract?.vision_instruction
      ? `For ${choiceContract.mode}, write ${choiceContract.vision_observation_field || "the declared observation field"}. ${choiceContract.vision_instruction}`
      : "For a declared choice mode, follow its active runtime choice contract; do not invent an undeclared season mechanic.",
    "Do not include image bytes, base64, or screenshots.",
    "Required top-level keys: source, model, confidence, observations.",
    "",
    "INPUT_JSON:",
    JSON.stringify(visionRequest, null, 2),
  ].join("\n");
}

function resolveVisionImagePath(visionRequest, frameFile = null) {
  const candidates = [
    visionRequest?.frame?.image_reference?.path,
  ];
  if (frameFile) {
    try {
      const frame = JSON.parse(readFileSync(path.resolve(frameFile), "utf8").replace(/^\uFEFF/, ""));
      candidates.push(frame?.image?.path);
    } catch {
      // The caller will continue without an image attachment and the host model will report missing visual evidence.
    }
  }
  for (const candidate of candidates) {
    if (!candidate) continue;
    const absolute = path.resolve(repoRoot, String(candidate));
    if (existsSync(absolute)) return absolute;
  }
  return null;
}

function buildWikiCurationHostPrompt(hostRequest) {
  return [
    "You are the host CLI main model for JCC Runtime strategy wiki curation.",
    "Return exactly one JSON object. No Markdown. No code fence.",
    "The output schema must be jcc-wiki-curation-host-response-v1.",
    "generated_by must be current_cli_agent_main_model.",
    "run_id must exactly equal INPUT_JSON.run_id.",
    "Create only draft personal_strategy wiki pages. Do not publish.",
    "Every page must include source_event_ids from INPUT_JSON.source_events.",
    "Use the three categories exactly: patch_meta_strategy, season_mechanic_strategy, universal_gameplay_strategy.",
    "Patch meta pages are scoped to season_id + patch_id and must not pollute future patches.",
    "Season mechanic pages are scoped to the current large season.",
    "Universal gameplay pages must avoid champion/augment-specific strength claims.",
    "If evidence is thin, return user_questions instead of inventing strategy.",
    "INPUT_JSON:",
    JSON.stringify(hostRequest, null, 2),
  ].join("\n");
}

async function markHostProviderTurnStarted(taskId, providerInfo = {}, invocationTaskId = taskId) {
  const task = state.response_task;
  if (!task || task.response_task_id !== taskId) return false;
  if (![
    "preparing",
    "running",
    "response_pending",
    "awaiting_host_cli_agent_response",
    "awaiting_host_cli_agent_coach_response",
  ].includes(task.status || "")) return false;
  const startedAt = providerInfo.started_at || new Date().toISOString();
  state.response_task = withCurrentMatchSessionIdForResponseTask({
    ...task,
    status: "running",
    host_queue_since: task.host_queue_since || task.awaiting_since || task.started_at || task.requested_at || startedAt,
    provider_awaiting_since: startedAt,
    provider_turn_id: providerInfo.turn_id || null,
    provider_name: providerInfo.provider || state.host_cli?.provider || null,
    provider_session_id: providerInfo.provider_session_id || task.provider_session_id || null,
    provider_invocation_task_id: invocationTaskId || taskId,
  });
  recordRuntimeEvent("host_provider_turn_started", {
    response_task_id: taskId,
    invocation_task_id: invocationTaskId || taskId,
    provider: providerInfo.provider || state.host_cli?.provider || null,
    provider_turn_id: providerInfo.turn_id || null,
    provider_session_id: providerInfo.provider_session_id || null,
    host_queue_since: state.response_task.host_queue_since || null,
    provider_awaiting_since: startedAt,
  });
  await persistStateAndCanonicalResponseTask();
  return true;
}

function rankingToolCandidatePage(selected, args, matchFacts) {
  if (!selected) return null;
  const page = compactSelectedRankingCandidatesForTurn(selected, {
    includeLineupIds: true,
    maxCandidates: Math.min(10, Math.max(1, Number(args.candidate_working_set_hint ?? args.limit) || 6)),
    matchFacts,
  });
  return {
    ...page,
    query_status: selected.query_status,
    ranking_scope: selected.ranking_scope,
    ...(args.include_band_directory === true && selected.band_directory
      ? { band_directory: selected.band_directory } : {}),
    candidates: page.candidates.map((candidate) => {
      const canonical = candidate.strategy_profile?.canonical_variant;
      return projectRankingToolCandidate({
        ...candidate,
        candidate_id: candidate.candidate_id || candidate.id,
        selected_variant_id: canonical?.variant_id || null,
        candidate_evidence_id: canonical?.candidate_evidence_id || candidate.strategy_profile?.candidate_evidence_id || null,
      });
    }),
  };
}

async function resolveHostResponseCandidateReferences(request, response) {
  if (!runtimeUsesNativeKnowledgeTools(request)) return;
  const scope = knowledgeQueryScope(request);
  const refs = firstArray(response?.candidate_refs).length
    ? firstArray(response.candidate_refs).map((ref) => ({
        ...ref,
        selected_variant_id: ref?.selected_variant_id || ref?.variant_id || null,
      }))
    : firstArray(response?.strategy_selection?.selected_candidate_refs);
  const unresolved = refs.filter((ref) => ![...scope.candidates.values()].some((candidate) => (
    candidate.candidate_id === ref.candidate_id
    && (!ref.selected_variant_id || candidate.selected_variant_id === ref.selected_variant_id)
    && (!ref.candidate_evidence_id || candidate.candidate_evidence_id === ref.candidate_evidence_id)
  )));
  if (!unresolved.length) return;
  if (resolveRuntimeContextPolicy(request.mode, request)?.hard_data_only) return;
  const staticContext = await getHostStaticContextSource();
  const groups = firstArray(staticContext?.daily_big_data?.tiers?.["0"]?.lineup_groups);
  // A remembered reference is resolved locally against the pinned source. It is
  // not sent back to the model or used to broaden the next turn's working set.
  for (const ref of unresolved.slice(0, 10)) {
    const matching = groups.filter((candidate) => [candidate.id, candidate.candidate_id].includes(ref.candidate_id));
    const page = compactSelectedRankingCandidatesForTurn({ candidates: matching }, {
      includeLineupIds: true, maxCandidates: 1,
      preferredVariantIds: new Map(ref.selected_variant_id ? [[ref.candidate_id, ref.selected_variant_id]] : []),
    });
    for (const candidate of page?.candidates || []) {
      const canonical = candidate.strategy_profile?.canonical_variant;
      if (ref.selected_variant_id && canonical?.variant_id !== ref.selected_variant_id) continue;
      const evidenceId = canonical?.candidate_evidence_id || candidate.strategy_profile?.candidate_evidence_id;
      if (ref.candidate_evidence_id && evidenceId !== ref.candidate_evidence_id) continue;
      const resolved = { ...candidate, candidate_id: candidate.id, selected_variant_id: canonical?.variant_id, candidate_evidence_id: evidenceId };
      scope.candidates.set(candidateIdentityKey(resolved), resolved);
    }
  }
}

function createReadonlyBrokerForHostTurn(enrichedHostRequest, invocation) {
  const runtimeContext = enrichedHostRequest?.runtime_context
    || enrichedHostRequest?.context?.runtime_context
    || {};
  const evidencePacket = runtimeContext.strategy_evidence_snapshot
    ? {
        evidence_snapshot: runtimeContext.strategy_evidence_snapshot,
        plan: runtimeContext.strategy_evidence_plan,
        coverage: runtimeContext.strategy_evidence_coverage,
        prefetch: runtimeContext.strategy_evidence_prefetch,
      }
    : null;
  if (!evidencePacket?.evidence_snapshot?.evidence_snapshot_id) return null;
  if (evidencePacket.plan?.provider_capability !== "native_dynamic_tools") return null;
  const logicalTurnMaxBytes = hostTurnDeltaMaxBytesForRequest(enrichedHostRequest);
  const requestedCandidateCount = Math.min(10, Math.max(1, Number(
    runtimeContext?.strategy_evidence_plan?.candidate_working_set_hint
      || runtimeContext?.strategy_fit_packet?.candidate_working_set_count
      || runtimeContext?.coach_content_agenda?.candidate_limit
      || 5,
  )));
  const adaptiveToolReserveBytes = Math.min(
    Math.floor(logicalTurnMaxBytes / 2),
    Math.max(HOST_READONLY_TOOL_MIN_RESERVE_BYTES, requestedCandidateCount * 24 * 1024),
  );
  const turnPromptBytes = Number(invocation?.turn_prompt_bytes)
    || Buffer.byteLength(buildHostTurnDeltaPrompt(enrichedHostRequest, invocation.capsule, {
      maxBytes: logicalTurnMaxBytes - adaptiveToolReserveBytes,
    }), "utf8");
  const remainingLogicalTurnBytes = Math.max(0, logicalTurnMaxBytes - turnPromptBytes);
  const evidenceStore = buildStrategyEvidenceStore({
    evidencePacket,
    hostRequest: enrichedHostRequest,
    runtimeContext,
  });
  const decisionMathBinding = captureDecisionMathServiceBinding();
  const capturedLiveStateSummary = structuredClone(enrichedHostRequest?.context?.live_state_summary || {});
  const capturedMatchFacts = structuredClone(runtimeContext.match_facts || {});
  const capturedSemanticFeatureIndex = structuredClone(activeSemanticFeatureIndex || {});
  const snapshotIdentity = evidencePacket.evidence_snapshot.identity || {};
  const rankingPages = new Map();
  let rankingPageSequence = 0;
  const rankingPage = (selected, args) => {
    const count = Math.min(10, Math.max(1, Number(args.candidate_working_set_hint ?? args.limit) || 5));
    const all = firstArray(selected?.candidates);
    const generalBrowse = !firstArray(selected?.query_intent?.groups).length
      && !firstArray(args?.entity_names).length && !args?.search_constraints
      && !args?.role && !firstArray(args?.strength_bands).length
      && !firstArray(selected?.requested_strength_bands).length;
    const shown = generalBrowse
      ? selectRankingDirectionShowcase(all, {
          count,
          bands: enrichedHostRequest.mode === "daily_chat" ? ["s", "a"] : null,
        })
      : all.slice(0, count);
    const shownIds = new Set(shown.map((candidate) => String(candidate?.id || candidate?.candidate_id || "")));
    const remaining = generalBrowse
      ? remainingRankingDirectionCandidates(all, shown, {
          bands: enrichedHostRequest.mode === "daily_chat" ? ["s", "a"] : null,
        })
      : all.filter((candidate) => !shownIds.has(String(candidate?.id || candidate?.candidate_id || "")));
    const page = rankingToolCandidatePage({ ...selected, candidates: shown }, args, capturedMatchFacts);
    if (page) {
      page.total_matching_count = selected.total_matching_count ?? all.length;
      page.remaining_count = remaining.length;
      if (remaining.length) {
        const cursor = `ranking-page:${++rankingPageSequence}`;
        rankingPages.set(cursor, { selected: { ...selected, total_matching_count: page.total_matching_count, candidates: remaining }, operation: args.operation,
          selectors: JSON.stringify([args.search_constraints, args.question, args.entity_names, args.role, args.strength_bands]) });
        page.next_cursor = cursor;
      }
    }
    return page;
  };
  const capturedWiki = readStrategyWikiContextForHost(resolveRuntimeContextPolicy(enrichedHostRequest.mode, enrichedHostRequest), { complete: true });
  const coreOnlySourcePolicy = resolveRuntimeContextPolicy(enrichedHostRequest.mode, enrichedHostRequest).hard_data_only;
  const queryStaticSource = async () => {
    const source = await getHostStaticContextSource();
    if (source.core_profile_id !== snapshotIdentity.core_profile_id) {
      throw new Error("readonly_tool_core_snapshot_expired");
    }
    if (!coreOnlySourcePolicy && source.ranking_overlay_id !== snapshotIdentity.ranking_overlay_id) {
      throw new Error("readonly_tool_ranking_snapshot_expired");
    }
    return source;
  };
  let snapshotRelationIndex = null;
  const querySnapshotRelationIndex = async (args) => {
    const staticContext = await queryStaticSource();
    if (!snapshotRelationIndex) {
      const coreService = await capturedCoreQueryService(decisionMathBinding);
      snapshotRelationIndex = coreService.createRelationIndex({
        snapshotId: evidencePacket.evidence_snapshot.evidence_snapshot_id,
        coreProfileId: snapshotIdentity.core_profile_id,
        rankingGenerationId: snapshotIdentity.ranking_overlay_id,
        ranking: { candidates: firstArray(staticContext?.daily_big_data?.tiers?.["0"]?.lineup_groups) },
        wiki: capturedWiki || {},
        semanticFeatureIndex: capturedSemanticFeatureIndex,
        matchSessionId: enrichedHostRequest?.match_session_id || runtimeContext?.match_session?.match_session_id,
      });
    }
    return queryKnowledgeRelationIndex(snapshotRelationIndex, {
      operation: args.operation,
      entity_names: [...firstArray(args?.entity_names), ...firstArray(args?.facets)]
        .map((value) => String(value || "").trim())
        .filter(Boolean),
      limit: args.limit,
      cursor: args.cursor,
      expectedSnapshotId: evidencePacket.evidence_snapshot.evidence_snapshot_id,
      sourcePolicy: evidencePacket.plan?.evidence_policy_id || null,
    });
  };
  // Historical Match provenance is not the lifetime of a newly sealed review.
  // Legacy snapshots retain their original active-Match expiry behavior.
  const executionMatchSessionId = Object.hasOwn(snapshotIdentity, "execution_match_session_id")
    ? snapshotIdentity.execution_match_session_id
    : snapshotIdentity.match_session_id || null;
  const assertSnapshotStillCurrent = () => {
    const currentMatchSessionId = state.match_session?.status === "active"
      ? state.match_session?.match_session_id || null
      : null;
    const currentCoreProfileId = state.match_session?.status === "active"
      ? state.match_session?.season_version_snapshot?.core_profile_ref?.core_profile_id || null
      : expectedRankingCoreIdentity().core_profile_id || null;
    if (currentMatchSessionId !== executionMatchSessionId) {
      throw new Error("readonly_tool_match_snapshot_expired");
    }
    if (currentCoreProfileId !== (snapshotIdentity.core_profile_id || null)) {
      throw new Error("readonly_tool_core_snapshot_expired");
    }
    const capturedResponseTaskId = snapshotIdentity.response_task_id || null;
    if (capturedResponseTaskId) {
      const responseOwner = {
        response_task_id: capturedResponseTaskId,
        mode: snapshotIdentity.response_task_mode || runtimeContext.active_mode || enrichedHostRequest?.mode || null,
        match_session_id: Object.hasOwn(snapshotIdentity, "response_task_match_session_id")
          ? snapshotIdentity.response_task_match_session_id
          : executionMatchSessionId,
        origin: snapshotIdentity.response_task_origin || null,
        event_key: snapshotIdentity.response_task_event_key || null,
        revision: Number(snapshotIdentity.response_task_revision),
      };
      if (!responseTaskOwnerStillCurrent(state.response_task, responseOwner, currentMatchSessionId)) {
        throw new Error("readonly_tool_response_task_expired");
      }
    }
    if (snapshotIdentity.choice_kind || snapshotIdentity.choice_report_id || snapshotIdentity.choice_set_revision != null) {
      const currentChoiceSet = reportedChoiceSetForScope(state.match_context || {}, {
        mode: runtimeContext.active_mode || enrichedHostRequest?.mode || null,
        choiceKind: snapshotIdentity.choice_kind || null,
        stageRound: snapshotIdentity.choice_stage_round || null,
        matchSessionId: snapshotIdentity.match_session_id || null,
      });
      const currentChoiceReportId = currentChoiceSet?.report_id || currentChoiceSet?.key || null;
      const capturedChoiceRevision = Number(snapshotIdentity.choice_set_revision);
      const currentChoiceRevision = Number(currentChoiceSet?.revision);
      if (!currentChoiceSet
        || (snapshotIdentity.choice_report_id && currentChoiceReportId !== snapshotIdentity.choice_report_id)
        || (Number.isFinite(capturedChoiceRevision) && currentChoiceRevision !== capturedChoiceRevision)) {
        throw new Error("readonly_tool_choice_revision_expired");
      }
    }
    const capturedDecisionAction = snapshotIdentity.decision_action_fingerprint || null;
    if (capturedDecisionAction) {
      const currentDecisionAction = state.response_task?.runtime_event_context?.decision_action_fingerprint
        || state.response_task?.task?.runtime_event_context?.decision_action_fingerprint
        || null;
      if (currentDecisionAction !== capturedDecisionAction) {
        throw new Error("readonly_tool_decision_action_expired");
      }
    }
    if (decisionMathBinding.match_session_id !== executionMatchSessionId
      || decisionMathBinding.core_profile_id !== (snapshotIdentity.core_profile_id || null)) {
      throw new Error("readonly_tool_calculation_binding_mismatch");
    }
  };
  const calculateQuestion = async (question, args = {}) => {
    assertSnapshotStillCurrent();
    if (args.operation === "solve_trait_roster_role_coverage") {
      const service = await capturedCoreQueryService(decisionMathBinding);
      const result = await service.calculate(args);
      assertSnapshotStillCurrent();
      return result;
    }
    const calculationRequest = {
      ...enrichedHostRequest,
      user_message: question,
      task: question,
    };
    const policy = resolveRuntimeContextPolicy(enrichedHostRequest?.mode, calculationRequest);
    const result = await buildDecisionMathContextForHost(
      calculationRequest,
      policy,
      capturedLiveStateSummary,
      capturedMatchFacts,
      decisionMathBinding,
    );
    assertSnapshotStillCurrent();
    return result;
  };
  return createHostReadonlyToolBroker({
    evidencePacket,
    evidenceStore,
    assertFresh: async () => {
      assertSnapshotStillCurrent();
      if (!resolveRuntimeContextPolicy(enrichedHostRequest.mode, enrichedHostRequest)?.hard_data_only) await queryStaticSource();
    },
    cacheQueries: true,
    maxTotalCalls: 12,
    maxCallsPerTool: 10,
    maxResultBytes: Math.min(
      String(state.host_cli?.provider || "codex").toLowerCase() === "kimi" ? KIMI_MCP_MAX_RESULT_BYTES : 1024 * 1024,
      remainingLogicalTurnBytes,
    ),
    maxCumulativeResultBytes: remainingLogicalTurnBytes,
    onResult: (result, args, timing) => {
      recordKnowledgeToolResult(enrichedHostRequest, result, args);
      const page = result?.result?.selected_ranking_candidates
        || result?.result;
      recordRuntimeEvent("host_readonly_tool_result", {
        response_task_id: state.response_task?.response_task_id,
        operation: args.operation,
        elapsed_ms: timing?.elapsed_ms,
        cache_hit: timing?.cache_hit === true,
        reused_result: timing?.reused_result === true,
        query_identity: timing?.query_identity || result?.query_identity || null,
        cumulative_turn_bytes: timing?.cumulative_turn_bytes ?? null,
        repeated_candidate_count: result.delivery?.previously_delivered_count || 0,
        evidence_snapshot_id: evidencePacket.evidence_snapshot.evidence_snapshot_id,
        result_bytes: timing?.result_bytes ?? Buffer.byteLength(JSON.stringify(result), "utf8"),
        candidate_count: page?.candidates?.length || 0,
        candidate_ids: firstArray(page?.candidates).map((candidate) => candidate.candidate_id || candidate.id),
        status: result.status || result.result?.status || "ok",
        has_next_page: Boolean(result.next_cursor),
      });
    },
    onFailure: (receipt) => {
      recordRuntimeEvent("host_readonly_tool_failed", {
        tool: receipt.tool,
        evidence_snapshot_id: receipt.evidence_snapshot_id,
        failure_code: receipt.failure_code,
        argument_bytes: receipt.argument_bytes,
        elapsed_ms: receipt.elapsed_ms,
        result_bytes: 0,
        retention: "bounded_failure_metadata_7d_200_2MiB",
      });
    },
    queryKnowledge: async (args) => {
      if (args.cursor?.startsWith("ranking-page:")) {
        const saved = rankingPages.get(args.cursor);
        if (!saved || saved.operation !== args.operation
          || saved.selectors !== JSON.stringify([args.search_constraints, args.question, args.entity_names, args.role, args.strength_bands])) {
          throw new Error("readonly_tool_invalid_cursor");
        }
        return { schema: "jcc-ranking-search-result-v1", status: "ok", result: rankingPage(saved.selected, args) };
      }
      const typedOperations = new Set(["get_common_knowledge", "get_entity", "get_related_entities", "get_lineup", "get_lineup_variants", "get_ranking_trend", "get_strategy_wiki", "search_lineups"]);
      if (typedOperations.has(args?.operation)) {
        const hardDataOnly = resolveRuntimeContextPolicy(enrichedHostRequest?.mode, enrichedHostRequest)?.hard_data_only;
        if (hardDataOnly && ["get_ranking_trend", "get_strategy_wiki", "search_lineups", "get_lineup", "get_lineup_variants"].includes(args.operation)) {
          return { schema: "jcc-knowledge-query-error-v1", status: "forbidden", error_code: "source_forbidden", source_policy: "active_core_profile_only" };
        }
        if (args.operation === "get_common_knowledge") {
          const staticContext = await queryStaticSource();
          return queryCommonHostKnowledge(staticContext?.core_knowledge, args);
        }
        if (args.operation === "get_lineup_variants") {
          if (!args.candidate_id) return { status: "query_required", missing_fields: ["candidate_id"] };
          const staticContext = await queryStaticSource();
          const matching = firstArray(staticContext?.daily_big_data?.tiers?.["0"]?.lineup_groups)
            .filter(candidate => [candidate.id, candidate.candidate_id].includes(args.candidate_id));
          if (matching.length !== 1) return { status: matching.length ? "ambiguous" : "not_found", candidate_id: args.candidate_id };
          const selected = compactSelectedRankingCandidatesForTurn({ candidates: matching }, {
            includeLineupIds: true, maxCandidates: 1,
            preferredVariantIds: new Map(args.selected_variant_id ? [[args.candidate_id, args.selected_variant_id]] : []),
          });
          const baseline = queryAtomicLineupEvidence({ selected_ranking_candidates: selected }, args);
          if (baseline.status !== "ok") return baseline;
          const profile = selected.candidates[0].strategy_profile;
          return {
            schema: "jcc-lineup-variant-index-v1", status: "ok", candidate_id: args.candidate_id,
            baseline_variant_id: baseline.selected_variant_id,
            variants: [profile.canonical_variant, ...firstArray(profile.sibling_variants)].map(variant => ({
              candidate_id: args.candidate_id, selected_variant_id: variant.variant_id,
              candidate_evidence_id: variant.candidate_evidence_id, population: variant.population,
              ...compactLineupPopulationSemantics(variant),
              main_carry: variant.main_carry?.champion_name || null,
              primary_tank: variant.primary_tank?.champion_name || null,
              semantic_role: variant.semantic_role,
              difference: variant.atomic_variant_difference || null,
            })),
            recipe_alternatives: profile.canonical_variant?.mature_recipe_variants || [],
            source_boundary: "Published atomic variants belong only to this candidate. Recipe alternatives are separate evidence, not replacements for its standard roster.",
            next_operation: "get_lineup",
          };
        }
        if (args.operation === "get_lineup") {
          await queryStaticSource();
          const deliveredCandidates = [...knowledgeQueryScope(enrichedHostRequest).candidates.values()];
          const delivered = queryAtomicLineupEvidence({ selected_ranking_candidates: { candidates: deliveredCandidates } }, args);
          if (delivered.status === "ok") return delivered;
          const local = queryAtomicLineupEvidence(enrichedHostRequest, args);
          if (local.status === "ok") return local;
          const staticContext = await queryStaticSource();
          const candidates = firstArray(staticContext?.daily_big_data?.tiers?.["0"]?.lineup_groups);
          const matching = candidates.filter((candidate) => [candidate.id, candidate.candidate_id].includes(args.candidate_id));
          const selected = compactSelectedRankingCandidatesForTurn({ candidates: matching }, {
            includeLineupIds: true, maxCandidates: 1,
            preferredVariantIds: new Map(args.selected_variant_id ? [[args.candidate_id, args.selected_variant_id]] : []),
          });
          return queryAtomicLineupEvidence({ selected_ranking_candidates: selected }, args);
        }
        if (["get_entity", "get_related_entities"].includes(args.operation)) {
          const coreService = await capturedCoreQueryService(decisionMathBinding);
          const coreResult = await coreService.queryKnowledge({
            ...args,
            snapshot_id: decisionMathBinding.core_profile_id,
          });
          if (hardDataOnly || (args.operation === "get_entity" && coreResult?.status !== "not_found")) return coreResult;
          const related = await querySnapshotRelationIndex(args);
          return related?.status === "not_found" ? coreResult : related;
        }
        if (args.operation === "search_lineups") {
          const staticContext = await queryStaticSource();
          const rankingRequest = rankingToolQueryRequest(args, {
            requestId: enrichedHostRequest.request_id,
            mode: enrichedHostRequest.mode,
            catalog: staticContext?.ranking_query_catalog,
            facts: capturedMatchFacts,
            liveState: capturedLiveStateSummary,
          });
          rankingRequest.ranking_full_pool = true;
          const availableRanking = staticContext?.daily_big_data || null;
          let expanded = availableRanking
            ? selectRelevantRankingCandidates(availableRanking, rankingRequest)
            : null;
          if (expanded) expanded.candidates = expanded.candidates.filter(candidate => candidateMatchesRequestedRole(candidate, args));
          if (expanded) expanded = rankRankingCandidatesForCurrentSnapshot(availableRanking, expanded, {
            liveStateSummary: capturedLiveStateSummary,
            matchFacts: capturedMatchFacts,
            userPreferences: userPreferencesFromHostRequest(enrichedHostRequest),
            rulesBundle: activeRulesBundle,
          });
          return { schema: "jcc-ranking-search-result-v1", status: expanded ? "ok" : "unavailable", result: rankingPage(expanded, args) };
        }
        const requested = [...firstArray(args?.entity_names), ...firstArray(args?.facets)].map((value) => String(value || "").trim()).filter(Boolean);
        const evidence = evidenceStore && typeof evidenceStore === "object" ? evidenceStore : {};
        const snapshotIdentity = evidencePacket?.evidence_snapshot?.identity || {};
        const staticContext = args.operation === "get_ranking_trend" ? await queryStaticSource() : null;
        const rankingEvidence = staticContext ? { candidates: firstArray(staticContext.daily_big_data?.tiers?.["0"]?.lineup_groups) }
          : evidence.ranking_lineup_candidates || evidence.ranking_observations || evidence.selected_ranking_candidates || null;
        const coreEntities = firstArray(evidence.current_core_entity_details || evidence.champion_trait_map);
        const core = {
          champions: coreEntities.filter((entry) => entry?.champion_id || entry?.champion_name || entry?.name),
          items: firstArray(evidence.equipment_effects_and_fit?.items || evidence.equipment_effects_and_fit?.entities),
          augments: firstArray(evidence.augment_effects_and_fit?.augments),
          traits: firstArray(evidence.champion_trait_map?.traits),
        };
        const relationIndex = buildKnowledgeRelationIndex({
          snapshotId: evidencePacket?.evidence_snapshot?.evidence_snapshot_id,
          coreProfileId: snapshotIdentity.core_profile_id,
          rankingGenerationId: snapshotIdentity.ranking_overlay_id,
          core,
          ranking: rankingEvidence,
          wiki: capturedWiki || {},
          semanticFeatureIndex: activeSemanticFeatureIndex,
          matchSessionId: enrichedHostRequest?.match_session_id || enrichedHostRequest?.runtime_context?.match_session?.match_session_id,
        });
        return queryKnowledgeRelationIndex(relationIndex, {
          operation: args.operation,
          entity_names: requested,
          limit: args.limit,
          cursor: args.cursor,
          expectedSnapshotId: evidencePacket?.evidence_snapshot?.evidence_snapshot_id,
          sourcePolicy: evidencePacket?.plan?.evidence_policy_id || null,
        });
      }
      if (args?.operation === "expand_ranking_candidates") {
        if (resolveRuntimeContextPolicy(enrichedHostRequest?.mode, enrichedHostRequest)?.hard_data_only) {
          return {
            schema: "jcc-ranking-candidate-expansion-v1",
            status: "forbidden",
            reason: "ranking_forbidden_by_active_core_only_policy",
            source_policy: "active_core_profile_only",
          };
        }
        const staticContext = await queryStaticSource();
        const expansionRequest = rankingToolQueryRequest(args, {
          requestId: enrichedHostRequest.request_id,
          mode: enrichedHostRequest.mode,
          catalog: staticContext?.ranking_query_catalog,
          facts: capturedMatchFacts,
          liveState: capturedLiveStateSummary,
        });
        expansionRequest.ranking_full_pool = true;
        const availableRanking = staticContext?.daily_big_data || null;
        let expanded = availableRanking
          ? selectRelevantRankingCandidates(availableRanking, expansionRequest)
          : null;
        if (expanded) {
          const deliveredIds = new Set([...knowledgeQueryScope(enrichedHostRequest).candidates.values()]
            .map(candidate => candidate.candidate_id || candidate.id));
          expanded.candidates = firstArray(expanded.candidates)
            .filter(candidate => !deliveredIds.has(candidate.candidate_id || candidate.id)
              && candidateMatchesRequestedRole(candidate, args));
          expanded = rankRankingCandidatesForCurrentSnapshot(availableRanking, expanded, {
            liveStateSummary: capturedLiveStateSummary,
            matchFacts: capturedMatchFacts,
            userPreferences: userPreferencesFromHostRequest(enrichedHostRequest),
            rulesBundle: activeRulesBundle,
          });
          expanded.returned_count = expanded.candidates.length;
          expanded.candidate_working_set_count = expanded.candidates.length;
          expanded.expansion_scope = "new_candidate_ids_in_complete_matching_snapshot_pool";
        }
        return {
          schema: "jcc-ranking-candidate-expansion-v1",
          expansion_scope: expanded?.expansion_scope || null,
          status: expanded?.ranking_browse_available === false || !expanded
            ? "unavailable"
            : "expanded",
          source_policy: "current_master_plus_ranking_only",
          requested_display_count: expanded?.requested_display_count || null,
          candidate_working_set_count: expanded?.candidate_working_set_count || 0,
          candidate_working_set_limit: expanded?.candidate_working_set_limit || 0,
          returned_count: expanded?.returned_count || 0,
          selected_ranking_candidates: rankingPage(expanded, args),
        };
      }
      const query = String(args?.question || "").trim()
        || [...firstArray(args?.entity_names), ...firstArray(args?.facets), ...firstArray(args?.route_ids)].join(" ");
      if (!query) return null;
      return { typed_current_core_result: await calculateQuestion(query) };
    },
    calculate: calculateQuestion,
  });
}

async function runHostModel(hostRequest, taskId) {
  const responseOwner = captureResponseTaskOwner(taskId, hostRequest?.mode || null,
    state.match_session?.status === "active" ? state.match_session.match_session_id : null);
  await ensureHostCliReady();
  const sessionReady = await ensureHostSessionReadyForTurn({
    mode: hostRequest?.mode,
    contextPack: hostRequest?.context_pack || null,
    reason: "host_turn_session_gate",
  });
  if (!sessionReady?.ok) {
    return {
      ok: false,
      status: sessionReady?.status || "host_session_not_ready",
      error: sessionReady?.error || "Host session is not ready for the current turn.",
    };
  }
  const actualReadonlyToolMode = sessionReady.readonly_tool_mode
    || state.host_sessions?.[currentHostSessionKind(hostRequest?.mode)]?.readonly_tool_mode
    || "prefetch_complete";
  let enrichedHostRequest = isCanonicalHostRequest(hostRequest)
    ? hostRequest
    : await enrichHostRequestWithRuntimeContext({
        ...hostRequest,
        provider_readonly_tool_mode: actualReadonlyToolMode,
      }, hostRequest?.mode, hostRequest?.context_pack, responseOwner);
  const evidenceOwner = enrichedHostRequest.runtime_context?.strategy_evidence_snapshot?.identity;
  if (evidenceOwner && (!responseOwner || !responseTaskStillOwnedAtRevision(responseOwner)
    || evidenceOwner.response_task_id !== responseOwner.response_task_id)) {
    throw new Error("host_context_response_owner_mismatch");
  }
  if (enrichedHostRequest?.runtime_context?.strategy_evidence_plan?.provider_capability !== actualReadonlyToolMode) {
    if (isCanonicalHostRequest(enrichedHostRequest)) {
      enrichedHostRequest = withHostRequestProjectionMetadata({
        ...enrichedHostRequest,
        provider_readonly_tool_mode: actualReadonlyToolMode,
        runtime_context: {
          ...(enrichedHostRequest.runtime_context || {}),
          strategy_evidence_plan: {
            ...(enrichedHostRequest.runtime_context?.strategy_evidence_plan || {}),
            provider_capability: actualReadonlyToolMode,
          },
        },
      });
    } else {
      enrichedHostRequest = await enrichHostRequestWithRuntimeContext({
        ...hostRequest,
        provider_readonly_tool_mode: actualReadonlyToolMode,
      }, hostRequest?.mode, hostRequest?.context_pack, responseOwner);
    }
  }
  const timeoutMs = hostCoachResponseTimeoutMs(state.response_task);
  const initialInvocation = prepareHostSessionInvocation(enrichedHostRequest);
  const readonlyToolBroker = createReadonlyBrokerForHostTurn(enrichedHostRequest, initialInvocation);
  const runInHostSession = async (
    initialInvocation,
    requestTaskId,
    promptForInvocation,
    schemaHostRequest = enrichedHostRequest,
  ) => {
    let invocation = initialInvocation;
    let hostCli = structuredClone(state.host_cli);
    const dispatchTraced = async (adapter, selectedInvocation, attemptId, options, promptOverride = null) => {
      const prompt = promptOverride ?? promptForInvocation(selectedInvocation);
      let trace = createHostTurnTrace({
        request: schemaHostRequest,
        task: state.response_task?.response_task_id === taskId ? state.response_task : { response_task_id: taskId },
        invocation: selectedInvocation, taskId: attemptId, prompt,
      });
      recordRuntimeEvent("host_turn_trace", trace);
      const response = await runHostAgentRequest(adapter, prompt, {
        ...options,
        onProviderTurnDispatched: (info) => {
          trace = updateHostTurnTrace(trace, "dispatch", { now: info?.date || new Date().toISOString() });
          recordRuntimeEvent("host_turn_trace", trace);
        },
        onProviderTurnStarted: (info) => {
          if (typeof info?.accepted_at === "string" && Number.isFinite(Date.parse(info.accepted_at))) {
            trace = updateHostTurnTrace(trace, "accepted", {
              now: info.accepted_at,
              sessionId: info?.provider_session_id || info?.session_id || info?.thread_id,
            });
            recordRuntimeEvent("host_turn_trace", trace);
          }
          return options.onProviderTurnStarted?.(info);
        },
        onProviderFirstToken: (info) => {
          trace = updateHostTurnTrace(trace, "first_token", { now: info?.date || new Date().toISOString() });
        },
      });
      trace = updateHostTurnTrace(trace, response.ok ? "final" : "failed", {
        status: response.error === "host_cli_json_parse_failed" ? "decode_failed" : "failed",
        sessionId: response.thread_id || response.session_id,
      });
      recordRuntimeEvent("host_turn_trace", trace);
      return { ...response, host_turn_trace: trace };
    };
    const dispatchStartedAt = Date.now();
    const turnOptions = {
      parseJson: true,
      jsonResponseKind: "coach",
      outputSchema: hostCoachNativeOutputSchemaForRequest(schemaHostRequest),
      repoRoot,
      taskId: requestTaskId,
      timeoutMs,
      providerStartTimeoutMs: HOST_PROVIDER_START_TIMEOUT_MS,
      hostSessionKey: invocation.route.key,
      hostSessionId: invocation.host_session_id,
      readonlyToolContractVersion: JCC_HOST_READONLY_TOOL_CONTRACT_VERSION,
      onReadonlyToolCall: readonlyToolBroker
        ? (toolName, args, callContext) => readonlyToolBroker.call(toolName, args, callContext)
        : null,
      onProviderTurnStarted: (providerInfo) => markHostProviderTurnStarted(taskId, providerInfo, requestTaskId),
    };
    let result = await dispatchTraced(hostCli, invocation, requestTaskId, turnOptions);

    result = await recoverEmptyHostTurn(result, {
      isCurrent: () => responseTaskStillOwnedAtRevision(responseOwner)
        && hostInvocationOwnsCurrentRoute(invocation, enrichedHostRequest?.mode)
        && Date.now() - dispatchStartedAt < timeoutMs,
      invoke: () => {
        const remainingMs = Math.max(1, timeoutMs - (Date.now() - dispatchStartedAt));
        recordRuntimeEvent("host_empty_turn_recovery", {
          response_task_id: requestTaskId,
          route_key: invocation.route.key,
          provider_session_id: invocation.host_session_id,
          remaining_ms: remainingMs,
          attempt: 1,
        });
        return dispatchTraced(hostCli, invocation, `${requestTaskId}:empty-recovery`, {
          ...turnOptions,
          timeoutMs: remainingMs,
          providerStartTimeoutMs: Math.min(HOST_PROVIDER_START_TIMEOUT_MS, remainingMs),
        }, "The previous provider turn completed without any assistant output. Complete the latest JCC_RUNTIME_CURRENT_TURN_DELTA already present in this session. Its request identity, source policy, tools and output contract are unchanged. Query necessary evidence and return the final answer. Do not repeat bootstrap or initialization.");
      },
    });

    if (!hostInvocationOwnsCurrentRoute(invocation, enrichedHostRequest?.mode)) {
      return {
        invocation,
        result: {
          ok: false,
          status: "host_session_route_expired",
          error: "Host session route or provider changed before this turn completed.",
        },
      };
    }

    if (!result.ok && invocation.host_session_id
      && (result.requires_bootstrap || hostSessionResumeFailure(result.error))) {
      recordRuntimeEvent("host_provider_session_resume_failed_rebootstrap", {
        route_key: invocation.route.key,
        provider_session_id: invocation.host_session_id,
        response_task_id: requestTaskId,
        error: sanitizedHostDiagnosticTail(result.error, 600),
      });
      if (result.requires_bootstrap && result.thread_id) {
        state.host_sessions[invocation.route.kind] = {
          ...(state.host_sessions[invocation.route.kind] || {}),
          status: "recovering",
          provider_session_id: result.thread_id,
          bootstrap_status: "required",
          context_fingerprint: null,
        };
      } else {
        await closeHostAgentSession(invocation.route.key).catch(() => {});
        resetHostSessionDescriptor(invocation.route, "provider_session_resume_failed");
      }
      const recoveryReady = await ensureHostSessionReadyForTurn({
        mode: enrichedHostRequest?.mode,
        contextPack: enrichedHostRequest?.context_pack || null,
        reason: "provider_session_resume_failed_rebootstrap",
      });
      if (!recoveryReady?.ok) {
        result = {
          ok: false,
          status: recoveryReady?.status || "host_session_rebootstrap_failed",
          error: recoveryReady?.error || "Host session recovery bootstrap failed.",
        };
      } else {
        invocation = prepareHostSessionInvocation(enrichedHostRequest);
        hostCli = structuredClone(state.host_cli);
        result = await dispatchTraced(hostCli, invocation, `${requestTaskId}:session-rebootstrap`, {
          parseJson: true,
          jsonResponseKind: "coach",
          outputSchema: hostCoachNativeOutputSchemaForRequest(schemaHostRequest),
          repoRoot,
          taskId: `${requestTaskId}:session-rebootstrap`,
          timeoutMs,
          providerStartTimeoutMs: HOST_PROVIDER_START_TIMEOUT_MS,
          hostSessionKey: invocation.route.key,
          hostSessionId: invocation.host_session_id,
          readonlyToolContractVersion: JCC_HOST_READONLY_TOOL_CONTRACT_VERSION,
          onReadonlyToolCall: readonlyToolBroker
            ? (toolName, args, callContext) => readonlyToolBroker.call(toolName, args, callContext)
            : null,
          onProviderTurnStarted: (providerInfo) => markHostProviderTurnStarted(taskId, providerInfo, `${requestTaskId}:session-rebootstrap`),
        });
      }
    }

    if (!hostInvocationOwnsCurrentRoute(invocation, enrichedHostRequest?.mode)) {
      return {
        invocation,
        result: {
          ok: false,
          status: "host_session_route_expired",
          error: "Host session route or provider changed before this turn completed.",
        },
      };
    }

    if (result.ok) {
      commitHostSessionInvocation(invocation, result);
      await persistHostSessionState(invocation.route.kind, "host_turn_completed");
    } else {
      const descriptor = state.host_sessions?.[invocation.route.kind];
      if (descriptor?.route_key === invocation.route.key) {
        state.host_sessions[invocation.route.kind] = {
          ...descriptor,
          status: descriptor.provider_session_id ? "ready_with_last_error" : "bootstrap_failed",
          last_error: sanitizedHostDiagnosticTail(result.error, 600),
          last_error_at: new Date().toISOString(),
        };
        await persistHostSessionState(invocation.route.kind, "host_turn_failed");
      }
    }
    return { invocation, result };
  };

  const primaryRun = await runInHostSession(
    initialInvocation,
    taskId,
    (invocation) => invocation.prompt,
  );
  const { result } = primaryRun;
  if (!result.ok) return result;
  try {
    await resolveHostResponseCandidateReferences(enrichedHostRequest, result.response);
    const response = normalizeHostCoachResponse(result.response, enrichedHostRequest);
    markValidatedHostResponse(response, enrichedHostRequest);
    recordRuntimeEvent("host_turn_trace", updateHostTurnTrace(result.host_turn_trace, "validation", { status: "passed" }));
    acknowledgeRankingCandidatesForResponse(enrichedHostRequest, response);
    if (result.host_transport_diagnostics) {
      recordRuntimeEvent("host_transport_non_contract_text_quarantined", {
        response_task_id: taskId,
        category: result.host_transport_diagnostics.category || "host_transport_non_contract_text",
        prefix: sanitizedHostDiagnosticTail(result.host_transport_diagnostics.prefix, 500),
        trailing: sanitizedHostDiagnosticTail(result.host_transport_diagnostics.trailing, 500),
      });
    }
    return {
      ok: true,
      response,
      host_transport_diagnostics: result.host_transport_diagnostics || null,
      stdout: result.stdout,
      stderr: result.stderr,
      thread_id: result.thread_id || result.session_id || primaryRun.invocation.host_session_id || null,
      events: result.events,
    };
    } catch (error) {
      recordRuntimeEvent("host_turn_trace", updateHostTurnTrace(result.host_turn_trace, "validation", {
        status: "failed", validationError: sanitizedHostDiagnosticTail(error.message || String(error), 2000),
      }));
      const readableText = typeof result.text === "string" ? result.text.trim() : "";
      if (readableText) {
        try {
          const fallbackResponse = normalizeHostCoachResponse({
            schema: HOST_COACH_RESPONSE_SCHEMA_ID,
            generated_by: HOST_COACH_RESPONSE_GENERATOR,
            final_text: readableText,
            recommended_action: null,
            confidence: "low",
            followup_question: null,
          }, enrichedHostRequest);
          fallbackResponse.soft_quality_diagnostics = [
            ...new Set([
              ...firstArray(fallbackResponse.soft_quality_diagnostics),
              "host_response_normalized_from_readable_text",
              "host_response_validation_degraded",
            ]),
          ];
          markValidatedHostResponse(fallbackResponse, enrichedHostRequest);
          recordRuntimeEvent("host_turn_trace", updateHostTurnTrace(result.host_turn_trace, "validation", {
            status: "degraded_text_delivery",
            validationError: sanitizedHostDiagnosticTail(error.message || String(error), 2000),
          }));
          return {
            ok: true,
            response: fallbackResponse,
            degraded_delivery: true,
            host_transport_diagnostics: result.host_transport_diagnostics || null,
            stdout: result.stdout,
            stderr: result.stderr,
            thread_id: result.thread_id || result.session_id || primaryRun.invocation.host_session_id || null,
            events: result.events,
          };
        } catch (fallbackError) {
          recordRuntimeEvent("host_turn_trace", updateHostTurnTrace(result.host_turn_trace, "validation", {
            status: "degraded_text_delivery_failed",
            validationError: sanitizedHostDiagnosticTail(fallbackError.message || String(fallbackError), 2000),
          }));
        }
      }
      return {
      ok: false,
      error: error.message || String(error),
      stdout: result.stdout,
      stderr: result.stderr,
      thread_id: result.thread_id || result.session_id || primaryRun.invocation.host_session_id || null,
      events: result.events,
    };
  }
}

async function completePendingHostCoach(pending, agentResponse, taskId, pipelineFile, hostRequestOverride = null, options = {}) {
  if (!pending?.request) return null;
  const isCurrent = typeof options.isCurrent === "function" ? options.isCurrent : null;
  if (isCurrent && !isCurrent()) {
    return {
      ok: true,
      status: "host_coach_merge_skipped_not_current",
      latest_response_ref_skipped: true,
      latest_response_ref_skip_reason: "response_task_not_current_before_merge",
    };
  }
  const immutableRequestEvent = pending.request_event?.type === "advice_response_requested"
    ? pending.request_event
    : null;
  if (!immutableRequestEvent) {
    return {
      ok: false,
      status: "host_coach_request_identity_missing",
      error: "host coach completion is missing its immutable advice request event",
    };
  }
  const normalizedRequestEvent = normalizeAdviceResponseRequestEvent(immutableRequestEvent, {
    hostCliAgentRequest: hostRequestOverride || immutableRequestEvent.host_cli_agent_request || pending.request,
    matchSessionId: state.match_session?.match_session_id || immutableRequestEvent.match_session_id || hostRequestOverride?.match_session_id || null,
  });
  if (hostRequestOverride) {
    normalizedRequestEvent.response_id = hostRequestOverride.request_id;
    normalizedRequestEvent.mode = hostRequestOverride.mode;
  }
  const requestEvent = normalizedRequestEvent?.host_cli_agent_request ? normalizedRequestEvent : null;
  if (!requestEvent) {
    return {
      ok: false,
      status: "host_coach_request_identity_invalid",
      error: "host coach completion could not normalize its immutable advice request event",
    };
  }
  try {
    const normalizedResponse = isValidatedHostResponse(agentResponse, requestEvent.host_cli_agent_request)
      ? agentResponse
      : normalizeHostCoachResponse(agentResponse, requestEvent.host_cli_agent_request);
    const result = {
      ok: true,
      schema: "jcc-host-coach-response-run-result-v2",
      status: "completed",
      advice_response: {
        schema: "jcc-advice-response-completion-v2",
        type: "advice_response_completed",
        response_id: requestEvent.response_id,
        trigger_id: requestEvent.trigger_id || null,
        match_session_id: requestEvent.match_session_id || null,
        mode: requestEvent.mode || requestEvent.host_cli_agent_request?.mode || null,
        request_ref: {
          request_id: requestEvent.host_cli_agent_request?.request_id || requestEvent.response_id,
          request_hash: requestEvent.host_cli_agent_request?.request_hash || null,
          response_task_id: taskId,
          source_event_type: requestEvent.type,
        },
        ai_native_policy: {
          output_model: requestEvent.ai_native_policy?.output_model || "host_cli_main_model_required",
        },
        status: "completed",
        coach_response: normalizedResponse,
        user_visible_text: normalizedResponse.final_text,
        final_response_required: false,
      },
    };
    if (isCurrent && !isCurrent()) {
      recordRuntimeEvent("host_coach_latest_response_ref_skipped_not_current", {
        response_task_id: taskId,
        request_source: "enriched_runtime_context_request_event",
        status: result.status,
      });
      return {
        ...result,
        latest_response_ref_skipped: true,
        latest_response_ref_skip_reason: "response_task_not_current_after_merge",
      };
    }
    if (diagnosticEvidenceEnabled()) {
      const outDir = path.join(uiRuntimeDir, "host-coach");
      const taskFileToken = runtimeArtifactFileToken(taskId, "host-task");
      const responseRunFile = path.join(outDir, `host-coach-response-run-${taskFileToken}.json`);
      void Promise.resolve().then(async () => {
        await ensureDir(outDir);
        await writeJsonAtomic(responseRunFile, compactSuccessfulHostDiagnostic(result));
        await writeJsonAtomic(path.join(outDir, "latest-host-coach-response.json"), {
          schema: "jcc-latest-host-coach-response-ref-v1",
          generated_at: new Date().toISOString(),
          response_id: result.advice_response?.response_id || requestEvent.response_id,
          status: "completed",
          host_coach_response_file: path.resolve(responseRunFile),
          request_source: "enriched_runtime_context_request_event",
        });
        await pruneRuntimeSensingArtifactDirectory(outDir, {
          maxEntries: 128,
          maxAgeMs: DIAGNOSTIC_ARTIFACT_MAX_AGE_MS,
        });
      }).catch((error) => {
        recordRuntimeEvent("host_coach_diagnostic_write_failed", {
          response_task_id: taskId,
          error: error.message || String(error),
          delivery_impact: "none",
        });
      });
    }
    return result;
  } catch (error) {
    recordRuntimeEvent("host_coach_delivery_merge_failed", {
      response_task_id: taskId,
      request_id: requestEvent.host_cli_agent_request.request_id,
      response_request_id: agentResponse?.request_id,
      error: sanitizedHostDiagnosticTail(error.message || String(error), 500),
    });
    return {
      ok: false,
      status: "host_coach_merge_failed",
      error: error.message || String(error),
    };
  }
}

async function runHostCoachForPipeline(pipelineFile, taskId, options = {}) {
  const pending = await requestPendingHostCoach(pipelineFile, {
    preferredTriggerId: options.preferredTriggerId || null,
  });
  if (!pending?.request) {
    return {
      ok: true,
      status: "no_host_request",
      host_request: null,
      response: null,
    };
  }
  const enrichedRequest = await enrichHostRequestWithRuntimeContext(
    pending.request,
    pending.request?.mode,
    pending.request?.context_pack,
    captureResponseTaskOwner(taskId, pending.request?.mode || null,
      state.match_session?.status === "active" ? state.match_session.match_session_id : null),
  );
  if (process.env.JCC_UI_DISABLE_CODEX_EXEC === "1") {
    return {
      ok: true,
      status: "awaiting_host_cli_agent_response",
      host_request: enrichedRequest,
      response: null,
    };
  }
  const codexResult = await runHostModel(enrichedRequest, taskId);
  if (!codexResult.ok) {
    const hostDiagnostics = buildHostRunDiagnostics(codexResult, enrichedRequest);
    return {
      ok: false,
      status: "failed",
      error: codexResult.error,
      host_request: hostRequestPersistenceRef(enrichedRequest, taskId),
      host_diagnostics: hostDiagnostics,
    };
  }
  const completed = await completePendingHostCoach(pending, codexResult.response, taskId, pipelineFile, enrichedRequest, options);
  if (completed?.ok === false) {
    return {
      ok: false,
      status: completed.status || "host_coach_merge_failed",
      error: completed.error,
      host_request: hostRequestPersistenceRef(enrichedRequest, taskId),
    };
  }
  return {
    ok: true,
    status: "completed",
    host_request: hostRequestPersistenceRef(enrichedRequest, taskId),
    response: completed?.advice_response?.coach_response || {
      schema: "jcc-host-cli-coach-response-v1",
      ...codexResult.response,
    },
  };
}

async function maybeDelaySendMessagePreparingForTest(taskId, requestedMode, matchSessionId) {
  const delayMs = Number(process.env.JCC_TEST_SEND_MESSAGE_PREPARING_DELAY_MS || 0);
  if (!Number.isFinite(delayMs) || delayMs <= 0) return;
  recordRuntimeEvent("test_send_message_preparing_delay", {
    response_task_id: taskId,
    mode: requestedMode,
    match_session_id: matchSessionId,
    delay_ms: delayMs,
  });
  await new Promise((resolve) => setTimeout(resolve, delayMs));
}

function messageIsResponseStatusPing(text) {
  const compact = String(text || "").replace(/\s+/g, "");
  return compact.length > 0
    && compact.length <= 6
    && /^[?？!！.。…]+$/.test(compact);
}

function responseTaskOwnsUndeliveredStatusPing(task = state.response_task) {
  return Boolean(task?.response_task_id) && (
    task.status === "preparing"
    || task.status === "running"
    || task.status === "response_pending"
    || hostCoachResponseIsPending(task)
    || (["completed", "failed"].includes(task.status || "") && !task.delivered_at)
  );
}

async function sendMessage(payload) {
  const text = String(payload.text || "").trim();
  const internallyAuthorizedHardDataQuery = payload[HARD_DATA_INTERNAL_AUTHORITY] === true;
  const internallyAuthorizedDailyCoreTheoryQuery = payload[DAILY_CORE_THEORY_INTERNAL_AUTHORITY] === true;
  const internallyAuthorizedPopularRecipeQuery = payload[POPULAR_RECIPE_INTERNAL_AUTHORITY] === true;
  const externalTypedCapability = [HARD_DATA_QUERY_REQUEST_KIND, DAILY_CORE_THEORY_QUERY_REQUEST_KIND, POPULAR_RECIPE_QUERY_REQUEST_KIND].includes(payload.request_kind)
    || Object.hasOwn(payload, "origin_action_id")
    || Object.hasOwn(payload, "evidence_policy_id");
  if (externalTypedCapability && !internallyAuthorizedHardDataQuery && !internallyAuthorizedDailyCoreTheoryQuery && !internallyAuthorizedPopularRecipeQuery) {
    return {
      ok: false,
      state,
      status: "typed_query_external_capability_rejected",
      error: "该查询能力只能通过已注册的巡航动作发起。",
    };
  }
  const requestKind = payload.request_kind === MATCH_FACT_CAPTURE_REQUEST_KIND
    ? MATCH_FACT_CAPTURE_REQUEST_KIND
    : internallyAuthorizedHardDataQuery && payload.request_kind === HARD_DATA_QUERY_REQUEST_KIND
      ? HARD_DATA_QUERY_REQUEST_KIND
      : internallyAuthorizedDailyCoreTheoryQuery && payload.request_kind === DAILY_CORE_THEORY_QUERY_REQUEST_KIND
        ? DAILY_CORE_THEORY_QUERY_REQUEST_KIND
      : internallyAuthorizedPopularRecipeQuery && payload.request_kind === POPULAR_RECIPE_QUERY_REQUEST_KIND
        ? POPULAR_RECIPE_QUERY_REQUEST_KIND
      : "host_question";
  const selectedMode = uiToRuntimeMode[payload.mode] || state.active_mode || "daily_chat";
  const rankingRecommendationRequested = payload.ranking_recommendation === true;
  const hardDataCapabilityValid = requestKind !== HARD_DATA_QUERY_REQUEST_KIND || (
    payload.origin_action_id === HARD_DATA_ORIGIN_ACTION_ID
    && payload.evidence_policy_id === HARD_DATA_EVIDENCE_POLICY_ID
  );
  const dailyCoreTheoryCapabilityValid = requestKind !== DAILY_CORE_THEORY_QUERY_REQUEST_KIND || (
    payload.origin_action_id === DAILY_CORE_THEORY_ORIGIN_ACTION_ID
    && payload.evidence_policy_id === HARD_DATA_EVIDENCE_POLICY_ID
  );
  const popularRecipeCapabilityValid = requestKind !== POPULAR_RECIPE_QUERY_REQUEST_KIND || (
    payload.origin_action_id === POPULAR_RECIPE_ORIGIN_ACTION_ID
    && payload.evidence_policy_id === POPULAR_RECIPE_EVIDENCE_POLICY_ID
  );
  const requestedMode = [MATCH_FACT_CAPTURE_REQUEST_KIND, HARD_DATA_QUERY_REQUEST_KIND, POPULAR_RECIPE_QUERY_REQUEST_KIND].includes(requestKind)
    ? "cruise"
    : requestKind === DAILY_CORE_THEORY_QUERY_REQUEST_KIND
      ? "daily_chat"
    : state.match_session.status === "active" && (
        messageExplicitlyRequestsLineupCard(text)
        || payload.lineup_confirmation_requested === true
        || messageRequestsFinalLineupConfirmation(text)
      )
    ? "lineup_card"
    : selectedMode;
  const requestedItemChoiceKind = requestedMode === "item_choice"
    ? normalizeItemChoiceKind(payload.item_choice_kind)
    : null;
  const isMatchActive = state.match_session.status === "active";
  if (rankingRecommendationRequested && (isMatchActive || selectedMode !== "daily_chat")) {
    return { ok: false, state, status: "ranking_recommendation_requires_daily_chat", error: "大数据推荐只能从大厅日常聊天入口发起。" };
  }
  if (requestKind === MATCH_FACT_CAPTURE_REQUEST_KIND && !isMatchActive) {
    return { ok: false, state, status: "match_fact_capture_requires_active_match", error: "快速记录只在当前对局中可用。" };
  }
  if (requestKind === MATCH_FACT_CAPTURE_REQUEST_KIND && selectedMode !== "cruise") {
    return { ok: false, state, status: "match_fact_capture_requires_cruise", error: "快速记录只能从巡航入口发起。" };
  }
  if (requestKind === HARD_DATA_QUERY_REQUEST_KIND && (!isMatchActive || selectedMode !== "cruise")) {
    return { ok: false, state, status: "hard_data_query_requires_active_cruise", error: "别吃大数据只能从当前对局的巡航入口发起。" };
  }
  if (requestKind === DAILY_CORE_THEORY_QUERY_REQUEST_KIND && selectedMode !== "daily_chat") {
    return { ok: false, state, status: "daily_core_theory_query_requires_daily_chat", error: "大厅别吃大数据只能从日常聊天入口发起。" };
  }
  if (requestKind === POPULAR_RECIPE_QUERY_REQUEST_KIND && (!isMatchActive || selectedMode !== "cruise")) {
    return { ok: false, state, status: "popular_recipe_query_requires_active_cruise", error: "查热门阵容只能从当前对局的巡航入口发起。" };
  }
  if (!hardDataCapabilityValid) {
    return { ok: false, state, status: "hard_data_query_capability_invalid", error: "别吃大数据请求缺少有效的 UI 证据权限，已拒绝执行。" };
  }
  if (!dailyCoreTheoryCapabilityValid) {
    return { ok: false, state, status: "daily_core_theory_query_capability_invalid", error: "大厅别吃大数据请求缺少有效的 UI 证据权限，已拒绝执行。" };
  }
  if (!popularRecipeCapabilityValid) {
    return { ok: false, state, status: "popular_recipe_query_capability_invalid", error: "热门阵容查询缺少有效的 UI 证据权限，已拒绝执行。" };
  }
  if (requestKind === "host_question" && messageIsResponseStatusPing(text) && responseTaskOwnsUndeliveredStatusPing(state.response_task)) {
    const observedStatus = state.response_task?.status === "completed"
      ? "response_status_ready"
      : state.response_task?.status === "failed"
        ? "response_status_failed_ready"
        : "response_status_pending";
    recordRuntimeEvent("response_status_ping_observed", {
      response_task_id: state.response_task?.response_task_id || null,
      response_task_status: state.response_task?.status || null,
      requested_mode: requestedMode,
      active_mode: state.active_mode || null,
    });
    return {
      ok: true,
      state,
      status: observedStatus,
      message: observedStatus === "response_status_ready"
        ? "当前回答已经生成，正在等待界面交付；没有发起新的回答任务。"
        : observedStatus === "response_status_failed_ready"
          ? "当前回答已经失败，正在等待界面显示错误；没有发起新的回答任务。"
          : "当前回答仍在生成；没有取消或发起新的回答任务。",
      response_task: state.response_task,
    };
  }
  const taskId = randomUUID();
  const taskMatchSessionId = isMatchActive ? state.match_session?.match_session_id || null : null;
  const taskStartedAt = new Date().toISOString();
  const userMessageTaskIsCurrent = () => responseTaskStillCurrent(taskId, requestedMode, taskMatchSessionId);
  const userMessageCancelledResult = (checkpoint) => {
    recordRuntimeEvent("user_message_response_task_cancelled_before_host_work", {
      checkpoint,
      response_task_id: taskId,
      mode: requestedMode,
      match_session_id: taskMatchSessionId,
      current_response_task_id: state.response_task?.response_task_id || null,
      active_response_task_id: activeResponseTaskId || null,
      current_status: state.response_task?.status || null,
    });
    return {
      ok: false,
      state,
      status: "response_cancelled",
      error: "user_stop_response",
      message: "Current response was stopped before host work started.",
    };
  };
  if (isMatchActive) {
    preemptActiveRuntimeEventResponseTask("user_message_received", {
      requested_mode: requestedMode,
      user_message_kind: messageRequestsSelfStateRefresh(text)
        ? "refresh_self_state"
        : messageRequestsOwnedAugmentTextPanelOcr(text, requestedMode)
          ? "owned_augment_text_panel_ocr"
          : requestKind,
    });
  }
  activeResponseTaskId = taskId;
  state.response_task = withCurrentMatchSessionIdForResponseTask({
    status: "preparing",
    response_task_id: taskId,
    mode: requestedMode,
    ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
    origin: requestKind === MATCH_FACT_CAPTURE_REQUEST_KIND ? MATCH_FACT_CAPTURE_REQUEST_KIND : "user",
    started_at: taskStartedAt,
    preparing_since: taskStartedAt,
  }, taskMatchSessionId);
  await persistStateAndCanonicalResponseTask();
  await maybeDelaySendMessagePreparingForTest(taskId, requestedMode, taskMatchSessionId);
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_preparing_test_delay");
  if (isMatchActive && messageRequestsSelfStateRefresh(text)) {
    await recordMatchUserMessageContext(text, "refresh_self_state", null);
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("before_manual_self_state_refresh");
    return runManualSelfStateRefreshForUserMessage({ taskId });
  }
  if (isMatchActive && messageRequestsOwnedAugmentTextPanelOcr(text, requestedMode)) {
    state.response_task = withCurrentMatchSessionIdForResponseTask({
      status: "running",
      response_task_id: taskId,
      mode: requestedMode,
      origin: "user_owned_augment_text_panel_ocr",
      started_at: new Date().toISOString(),
    });
    await persistStateAndCanonicalResponseTask();
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("before_owned_augment_text_panel_ocr");
    return runOwnedAugmentTextPanelOcrForUserMessage({ taskId });
  }
  const preMessageLiveState = isMatchActive
    ? (await resolveActiveLiveStateForRuntime({ purpose: "user_message_context" })).live_state
    : null;
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_pre_message_live_state");
  if (requestKind === MATCH_FACT_CAPTURE_REQUEST_KIND) {
    const contextPack = await getOrBuildContextPack("mode", "cruise");
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_match_fact_capture_context_pack");
    const hostRequest = await enrichHostRequestWithRuntimeContext(
      await buildMatchFactCaptureHostRequest(text, contextPack, preMessageLiveState),
      "cruise",
      contextPack,
    );
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_match_fact_capture_host_request");
    state.response_task = withCurrentMatchSessionIdForResponseTask({
      ...(state.response_task || {}),
      status: "awaiting_host_cli_agent_response",
      response_task_id: taskId,
      mode: "cruise",
      origin: MATCH_FACT_CAPTURE_REQUEST_KIND,
      awaiting_since: new Date().toISOString(),
      host_request: hostRequestPersistenceRef(hostRequest, taskId),
      expiry_policy: "current_match_fact_capture",
    }, taskMatchSessionId);
    await persistStateAndCanonicalResponseTask();
    if (process.env.JCC_UI_DISABLE_CODEX_EXEC === "1") {
      return { ok: true, state, status: state.response_task.status, host_request: hostRequest };
    }
    runDirectHostModelForUserMessageInBackground({
      hostRequest,
      taskId,
      requestedMode: "cruise",
      origin: MATCH_FACT_CAPTURE_REQUEST_KIND,
    });
    return {
      ok: true,
      state,
      status: "awaiting_host_cli_agent_response",
      host_request_ref: hostRequestPersistenceRef(hostRequest, taskId),
      response_task: state.response_task,
    };
  }
  let recordedUserMessageContext = null;
  if (isMatchActive) {
    recordedUserMessageContext = await recordMatchUserMessageContext(text, requestedMode, preMessageLiveState, {
      itemChoiceKind: requestedItemChoiceKind,
    });
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_match_user_message_context");
    if (
      manualReportChoiceRuntimeModes.has(requestedMode)
      && messageRequiresCurrentChoiceCandidates(text)
      && choiceCheckpointForModeStage(requestedMode, latestKnownStageRound(preMessageLiveState))
      && !currentUserReportedChoiceSetForAdvice(requestedMode, preMessageLiveState, state.match_context)
    ) {
      const reportPrompt = userReportedChoicePrompt(requestedMode);
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "choice_candidate_report_required",
        response_task_id: null,
        previous_response_task_id: taskId,
        mode: requestedMode,
        origin: "local_choice_report_gate",
        completed_at: new Date().toISOString(),
        report_prompt: reportPrompt,
      }, taskMatchSessionId);
      activeResponseTaskId = null;
      recordRuntimeEvent("manual_choice_report_required_before_host_turn", {
        mode: requestedMode,
        match_session_id: taskMatchSessionId,
        stage_round: latestKnownStageRound(preMessageLiveState),
        response_task_id: taskId,
      });
      await persistStateAndCanonicalResponseTask();
      return {
        ok: true,
        state,
        status: "choice_candidate_report_required",
        message: reportPrompt,
      };
    }
  }
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("before_user_message_response_task_running");
  state.response_task = withCurrentMatchSessionIdForResponseTask({
    status: "running",
    response_task_id: taskId,
    mode: requestedMode,
    ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
    origin: "user",
    started_at: new Date().toISOString(),
  });
  await persistStateAndCanonicalResponseTask();

  if (
    isMatchActive
    && messageRequestsCurrentItemEvidence(text)
    && !recordedUserMessageContext?.user_confirmed_equipment_update
    && !visualRuntimeModes.has(requestedMode)
    && !manualReportChoiceRuntimeModes.has(requestedMode)
  ) {
    await refreshCurrentItemEvidenceForUserMessage({ text, requestedMode, taskId });
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_current_item_evidence_refresh");
  }

  if (isMatchActive && visualRuntimeModes.has(requestedMode)) {
    const preMessageStageRound = trustedChoiceStageRoundForMode(requestedMode, preMessageLiveState);
    const choiceOptions = requestedItemChoiceKind ? { itemChoiceKind: requestedItemChoiceKind } : {};
    const reusableFastChoice = latestReusableFastChoicePipelineForManualMode(requestedMode, preMessageStageRound, choiceOptions)
      || await waitForManualChoiceWarmupPipeline(requestedMode, preMessageStageRound, choiceOptions);
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_manual_choice_warmup_pipeline_wait");
    if (reusableFastChoice?.pipeline_file) {
      const stageRound = reusableFastChoice.target_stage_round || reusableFastChoice.stage_round || preMessageStageRound || null;
      const pipelineHint = reusableFastChoice.fast_choice_hint
        || (await buildPipelineFastChoiceHintFromFile(
          reusableFastChoice.pipeline_file,
          requestedMode,
          `user_message_reused_fast_choice_pipeline_hint:${requestedMode}`,
        ));
      const hint = pipelineHint || buildFastChoiceHint({
          mode: requestedMode,
          phase: reusableFastChoice.phase || requestedMode,
          stageRound,
          targetStageRound: stageRound,
          fastChoice: { result: reusableFastChoice.fast_choice_text || null },
          source: "user_message_reused_fast_choice_pipeline",
        });
      hideFastChoiceHintForAiNative(
        hint,
        "manual_choice_reused_existing_rapidocr_pipeline",
        hint?.answer_layer || "deterministic_scorer_evidence_not_user_visible",
      );
      await recordObservedChoiceOptions({
        mode: requestedMode,
        phase: reusableFastChoice.phase || requestedMode,
        stageRound,
        targetStageRound: stageRound,
        fastChoice: { result: reusableFastChoice.fast_choice_text || null },
        hint,
        source: "user_message_reused_fast_choice_pipeline",
      });
      if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_reusable_fast_choice_recorded");
      const responsePipelineFile = await runPipelineForMessage(text, requestedMode, {
        forceResponseReason: `manual_${requestedMode}_user_request`,
      }) || reusableFastChoice.pipeline_file;
      if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_reusable_fast_choice_response_pipeline");
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "awaiting_host_cli_agent_response",
        response_task_id: taskId,
        mode: requestedMode,
        ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
        origin: "user",
        started_at: state.response_task?.started_at || new Date().toISOString(),
        awaiting_since: new Date().toISOString(),
        pipeline_file: responsePipelineFile,
        evidence_pipeline_file: reusableFastChoice.pipeline_file,
        fast_choice_hint: hint,
        expiry_policy: "user_question_must_return_even_if_window_passed",
        reused_fast_choice_pipeline: true,
      });
      state.visual_request_status = {
        ...(state.visual_request_status || {}),
        status: "fast_choice_text_ready",
        mode: requestedMode,
        phase: reusableFastChoice.phase || requestedMode,
        ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
        stage_round: stageRound,
        match_session_id: state.match_session?.match_session_id || null,
        pipeline_file: reusableFastChoice.pipeline_file,
        fast_choice_hint: hint,
        completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        source: "user_message_reused_fast_choice_pipeline",
      };
      await supersedePendingChoiceVisualWithFastText(requestedMode, stageRound, "user_message_reused_fast_choice_pipeline", {
        pipeline_file: reusableFastChoice.pipeline_file,
        fast_choice_hint: hint,
      });
      recordRuntimeEvent("manual_choice_reused_fast_choice_pipeline", {
        mode: requestedMode,
        stage_round: stageRound,
        source: reusableFastChoice.source,
        pipeline_file: reusableFastChoice.pipeline_file,
        response_pipeline_file: responsePipelineFile,
        response_task_id: taskId,
      });
      await persistStateAndCanonicalResponseTask();
      runHostCoachForPipelineInBackground({
        pipelineFile: responsePipelineFile,
        taskId,
        requestedMode,
        origin: "user",
        fastChoiceHint: hint,
      });
      return {
        ok: true,
        state,
        status: "awaiting_host_cli_agent_response",
        reused_fast_choice_pipeline: true,
      };
    }
      await supersedePendingChoiceVisualWithFastText(requestedMode, preMessageStageRound, "user_message_choice_fast_path_takes_priority");
    const phase = runtimeChoiceModeContract(requestedMode)?.phase || null;
    const fastChoice = await tryFastChoiceTextObservation(requestedMode, `user_message_before_pipeline:${requestedMode}`, {
      phase,
      timeoutMs: manualChoiceOcrTimeoutMs(requestedMode),
      intervalMs: Number(process.env.JCC_MANUAL_CHOICE_OCR_INTERVAL_MS || 200),
      ...(requestedItemChoiceKind ? { itemChoiceKind: requestedItemChoiceKind } : {}),
      forceResponseReason: `manual_${requestedMode}_user_request`,
    });
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_manual_choice_fast_ocr");
    if (fastChoice?.ok && fastChoice.pipeline_file) {
      const stageRound = trustedChoiceStageRoundForMode(requestedMode, preMessageLiveState)
        || normalizeStageRound(fastChoice?.selected_report?.phase?.stage_round)
        || normalizeStageRound(fastChoice?.result?.selected?.phase?.stage_round)
        || null;
      const pipelineHint = await buildPipelineFastChoiceHintFromFile(
        fastChoice.pipeline_file,
        requestedMode,
        `user_message_fast_ocr_pipeline_hint:${requestedMode}`,
      );
      const hint = pipelineHint || buildFastChoiceHint({
        mode: requestedMode,
        phase: phase || fastChoice.phase || requestedMode,
        stageRound,
        targetStageRound: stageRound,
        fastChoice,
        source: "user_message_fast_ocr",
      });
      if (!pipelineHint) {
        hideFastChoiceHintForAiNative(
          hint,
          "manual_choice_has_ocr_candidates_but_no_pipeline_fast_coach_hint",
          "rapidocr_observation_not_user_visible",
        );
      }
      if (pipelineHint) {
        hideFastChoiceHintForAiNative(hint);
      }
      const visibleFastChoiceHint = null;
      await recordObservedChoiceOptions({
        mode: requestedMode,
        phase: phase || fastChoice.phase || requestedMode,
        stageRound,
        targetStageRound: stageRound,
        fastChoice,
        hint,
        source: "user_message_fast_ocr",
      });
      if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_fast_choice_recorded");
      const responsePipelineFile = await runPipelineForMessage(text, requestedMode, {
        forceResponseReason: `manual_${requestedMode}_user_request`,
      }) || fastChoice.pipeline_file;
      if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_fast_choice_response_pipeline");
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "awaiting_host_cli_agent_response",
        response_task_id: taskId,
        mode: requestedMode,
        ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
        origin: "user",
        started_at: state.response_task?.started_at || new Date().toISOString(),
        awaiting_since: new Date().toISOString(),
        pipeline_file: responsePipelineFile,
        evidence_pipeline_file: fastChoice.pipeline_file,
        fast_choice_hint: hint,
        expiry_policy: "user_question_must_return_even_if_window_passed",
      });
      state.visual_request_status = {
        ...(state.visual_request_status || {}),
        status: "fast_choice_text_ready",
        mode: requestedMode,
        phase: phase || fastChoice.phase || requestedMode,
        ...(requestedItemChoiceKind ? { item_choice_kind: requestedItemChoiceKind } : {}),
        stage_round: stageRound,
        match_session_id: state.match_session?.match_session_id || null,
        pipeline_file: fastChoice.pipeline_file,
        fast_choice_hint: hint,
        completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        source: "user_message_fast_choice_text",
      };
      await supersedePendingChoiceVisualWithFastText(requestedMode, stageRound, "user_message_fast_choice_ready", {
        pipeline_file: fastChoice.pipeline_file,
        fast_choice_hint: hint,
      });
      await persistStateAndCanonicalResponseTask();
      runHostCoachForPipelineInBackground({
        pipelineFile: responsePipelineFile,
        taskId,
        requestedMode,
        origin: "user",
        fastChoiceHint: hint,
      });
      return {
        ok: true,
        state,
        status: "awaiting_host_cli_agent_response",
        fast_choice_text: fastChoice.result,
      };
    }
    if (choiceVisualRuntimeModes.has(requestedMode)) {
      const failureStatus = fastChoice?.status || "fast_choice_text_no_choice";
      const isWorkerFailure = /worker_failed|resident_worker_failed/.test(failureStatus);
      const isCaptureFailure = isFastChoiceCaptureFailure(fastChoice);
      const isOcrTimeout = /timed out after/i.test(String(fastChoice?.error || ""))
        || /timed out after/i.test(JSON.stringify(fastChoice?.result || {}));
      const responseStatus = isCaptureFailure
        ? "fast_choice_text_capture_failed"
        : isWorkerFailure
          ? "fast_choice_text_worker_failed"
          : "fast_choice_text_no_choice";
      const userFailureMessage = isWorkerFailure
        ? "快速 OCR worker 没准备好；本次没有进入截图/裁剪识别。我已记录诊断，不会启动慢视觉兜底污染巡航。"
        : isOcrTimeout
          ? "快速 OCR 这次超时，没有读到稳定候选；请确认选择窗口还在画面里，再发一次当前模式预设。我没有启动慢视觉兜底，避免选择窗口过期后污染巡航。"
          : "快速 OCR 没读到稳定候选；请确认选择窗口还在画面里，再发一次当前模式预设。我没有启动慢视觉兜底，避免选择窗口过期后污染巡航。";
      const returnedFailureMessage = isCaptureFailure
        ? "快速 OCR 截图失败：当前 ADB 目标没有稳定绑定到 MuMu 设备。我没有启动慢视觉兜底，避免选择窗口过期后污染巡航；请重新一键连接 MuMu ADB 后再发当前模式预设。"
        : userFailureMessage;
      state.response_task = withCurrentMatchSessionIdForResponseTask(isCaptureFailure
        ? {
            status: responseStatus,
            response_task_id: taskId,
            mode: requestedMode,
            origin: "user",
            completed_at: new Date().toISOString(),
            error: fastChoice?.error || fastChoice?.result?.error || failureStatus,
            fast_choice_text: fastChoice?.result || null,
            last_fast_choice_text_failure: state.runtime_triggers?.last_fast_choice_text_failure || null,
          }
        : {
            status: "preparing_visual_fallback",
            response_task_id: taskId,
            mode: requestedMode,
            origin: "user",
            started_at: state.response_task?.started_at || new Date().toISOString(),
            visual_fallback_from: responseStatus,
            fast_choice_text: fastChoice?.result || null,
            last_fast_choice_text_failure: state.runtime_triggers?.last_fast_choice_text_failure || null,
          });
      state.visual_request_status = {
        ...(state.visual_request_status || {}),
        status: responseStatus,
        mode: requestedMode,
        phase: phase || requestedMode,
        match_session_id: state.match_session?.match_session_id || null,
        updated_at: new Date().toISOString(),
        source: "user_message_fast_choice_text",
        fast_choice_text: fastChoice?.result || null,
        error: isCaptureFailure || isWorkerFailure ? (fastChoice?.error || fastChoice?.result?.error || failureStatus) : null,
        capture_failed: isCaptureFailure,
        ocr_timeout: isOcrTimeout,
        last_fast_choice_text_failure: state.runtime_triggers?.last_fast_choice_text_failure || null,
      };
      recordRuntimeEvent(isCaptureFailure ? "manual_choice_fast_text_capture_failed" : isWorkerFailure ? "manual_choice_fast_text_worker_failed" : "manual_choice_fast_text_no_choice", {
        mode: requestedMode,
        phase: phase || requestedMode,
        source: "user_message_fast_choice_text",
        status: failureStatus,
        error: fastChoice?.error || fastChoice?.result?.error || null,
        device: selectedAdbTargetSerial(),
        capture_failed: isCaptureFailure,
        ocr_timeout: isOcrTimeout,
        result: fastChoice?.result || null,
        diagnostic: state.runtime_triggers?.last_fast_choice_text_failure || null,
      });
      await persistStateAndCanonicalResponseTask();
      if (isCaptureFailure) {
        return {
          ok: true,
          state,
          status: responseStatus,
          fast_choice_text: fastChoice?.result || null,
          error: fastChoice?.error || fastChoice?.result?.error || failureStatus,
          message: returnedFailureMessage,
        };
      }
      recordRuntimeEvent("manual_choice_multimodal_fallback_requested", {
        mode: requestedMode,
        phase: phase || requestedMode,
        source: "user_message_fast_choice_text",
        fallback_from: responseStatus,
        ocr_timeout: isOcrTimeout,
        worker_failed: isWorkerFailure,
      });
    }
    const visualRun = await ensureModeVisualObservation(requestedMode, `user_message_before_pipeline:${requestedMode}`);
    if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_mode_visual_observation");
    if (visualRun?.status === "awaiting_host_cli_agent_response") {
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "awaiting_host_cli_agent_visual_response",
        response_task_id: taskId,
        mode: requestedMode,
        origin: "user",
        awaiting_since: new Date().toISOString(),
        visual_request_status: state.visual_request_status,
      });
      await persistStateAndCanonicalResponseTask();
      return {
        ok: true,
        state,
        status: "awaiting_host_cli_agent_visual_response",
        vision_request: visualRun.visual_run?.vision_request || null,
        visual_run: visualRun.visual_run?.prepared_run || visualRun.visual_run || null,
      };
    }
    if (visualRun?.ok === false) {
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "failed",
        response_task_id: taskId,
        mode: requestedMode,
        origin: "user",
        error: visualRun.visual_run?.error || "visual_refresh_failed",
      });
      await persistStateAndCanonicalResponseTask();
      return {
        ok: false,
        state,
        status: "visual_refresh_failed",
        error: visualRun.visual_run?.error || "visual refresh failed before strategy response",
      };
    }
  }
  const contextPack = await getOrBuildContextPack("mode", requestedMode);
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_context_pack");
  const pipelineFile = isMatchActive && ![HARD_DATA_QUERY_REQUEST_KIND, DAILY_CORE_THEORY_QUERY_REQUEST_KIND, POPULAR_RECIPE_QUERY_REQUEST_KIND].includes(requestKind) ? await runPipelineForMessage(text, requestedMode, {
    forceResponseReason: registeredChoiceRuntimeModes.has(requestedMode)
      ? `manual_${requestedMode}_user_request`
      : null,
  }) : null;
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_runtime_pipeline");
  if (isMatchActive && choiceVisualRuntimeModes.has(requestedMode) && pipelineFile) {
    const pipelineFastHint = await buildPipelineFastChoiceHintFromFile(
      pipelineFile,
      requestedMode,
      `user_message_pipeline_fast_hint:${requestedMode}`,
    );
    if (pipelineFastHint) {
      hideFastChoiceHintForAiNative(pipelineFastHint);
      if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("before_pipeline_fast_hint_host_request");
      state.response_task = withCurrentMatchSessionIdForResponseTask({
        status: "awaiting_host_cli_agent_response",
        response_task_id: taskId,
        mode: requestedMode,
        origin: "user",
        started_at: state.response_task?.started_at || new Date().toISOString(),
        awaiting_since: new Date().toISOString(),
        pipeline_file: pipelineFile,
        fast_choice_hint: pipelineFastHint,
        expiry_policy: "user_question_must_return_even_if_window_passed",
      });
      await persistStateAndCanonicalResponseTask();
      runHostCoachForPipelineInBackground({
        pipelineFile,
        taskId,
        requestedMode,
        origin: "user",
        fastChoiceHint: pipelineFastHint,
      });
      return {
        ok: true,
        state,
        status: "awaiting_host_cli_agent_response",
      };
    }
  }
  const pending = pipelineFile ? await requestPendingHostCoach(pipelineFile, { preferredTriggerId: "user_message_response" }) : null;
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_pending_host_coach_request");
  const baseHostRequest = bindPendingHostRequestToDirectUserTask(
    pending?.request || null,
    text,
    requestedMode,
    contextPack,
    { lineupConfirmationRequested: payload.lineup_confirmation_requested === true || messageRequestsFinalLineupConfirmation(text) },
  );
  const rankingRequestFields = rankingRecommendationRequested
    ? {
        ranking_recommendation: true,
        ranking_requested_count: Math.max(1, Math.min(16, Number(payload.ranking_requested_count) || 5)),
        ranking_query_route_key: String(payload.ranking_query_route_key || (
          currentHostSessionKind(requestedMode) === "daily"
            ? `daily:${state.daily_session?.generation || 1}:ranking`
            : `match:${state.match_session?.match_session_id || "active"}:ranking`
        )),
      }
    : {};
  const typedBaseHostRequest = requestKind === HARD_DATA_QUERY_REQUEST_KIND
    ? {
        ...baseHostRequest,
        request_kind: HARD_DATA_QUERY_REQUEST_KIND,
        origin_action_id: HARD_DATA_ORIGIN_ACTION_ID,
        evidence_policy_id: HARD_DATA_EVIDENCE_POLICY_ID,
      }
    : requestKind === DAILY_CORE_THEORY_QUERY_REQUEST_KIND
      ? {
          ...baseHostRequest,
          request_kind: DAILY_CORE_THEORY_QUERY_REQUEST_KIND,
          origin_action_id: DAILY_CORE_THEORY_ORIGIN_ACTION_ID,
          evidence_policy_id: HARD_DATA_EVIDENCE_POLICY_ID,
        }
    : requestKind === POPULAR_RECIPE_QUERY_REQUEST_KIND
      ? {
          ...baseHostRequest,
          request_kind: POPULAR_RECIPE_QUERY_REQUEST_KIND,
          origin_action_id: POPULAR_RECIPE_ORIGIN_ACTION_ID,
          evidence_policy_id: POPULAR_RECIPE_EVIDENCE_POLICY_ID,
        }
      : { ...baseHostRequest, ...rankingRequestFields };
  const hostRequest = await enrichHostRequestWithRuntimeContext(
    typedBaseHostRequest,
    requestedMode,
    pending?.request?.context_pack || contextPack,
    captureResponseTaskOwner(taskId, requestedMode, taskMatchSessionId),
  );
  if (!userMessageTaskIsCurrent()) return userMessageCancelledResult("after_host_request_context_enrichment");

  if (process.env.JCC_UI_DISABLE_CODEX_EXEC === "1") {
    state.response_task = withCurrentMatchSessionIdForResponseTask({
      status: "awaiting_host_cli_agent_response",
      response_task_id: taskId,
      mode: requestedMode,
      origin: "user",
      awaiting_since: new Date().toISOString(),
      host_request: hostRequestPersistenceRef(hostRequest, taskId),
      expiry_policy: registeredChoiceRuntimeModes.has(requestedMode)
        ? "user_question_must_return_even_if_window_passed"
        : state.response_task?.expiry_policy || null,
      ...(pipelineFile ? { pipeline_file: pipelineFile } : {}),
    });
    await persistStateAndCanonicalResponseTask();
    return { ok: true, state, status: state.response_task.status, host_request: hostRequest };
  }

  state.response_task = withCurrentMatchSessionIdForResponseTask({
    ...(state.response_task || {}),
    status: "awaiting_host_cli_agent_response",
    response_task_id: taskId,
    mode: requestedMode,
    origin: "user",
    awaiting_since: new Date().toISOString(),
    host_request: hostRequestPersistenceRef(hostRequest, taskId),
    expiry_policy: registeredChoiceRuntimeModes.has(requestedMode)
      ? "user_question_must_return_even_if_window_passed"
      : state.response_task?.expiry_policy || null,
    ...(pipelineFile ? { pipeline_file: pipelineFile } : {}),
  });
  await persistStateAndCanonicalResponseTask();
  runDirectHostModelForUserMessageInBackground({
    hostRequest,
    pending,
    pipelineFile,
    taskId,
    requestedMode,
    origin: "user",
  });
  return {
    ok: true,
    state,
    status: "awaiting_host_cli_agent_response",
    host_request_ref: hostRequestPersistenceRef(hostRequest, taskId),
    response_task: state.response_task,
  };
}

function registeredCruiseHardDataCapability() {
  const capability = runtimeUiModeContractForProactiveDecision?.cruise_mode_policy?.renderer?.hard_data_action;
  if (
    capability?.request_kind !== HARD_DATA_QUERY_REQUEST_KIND
    || capability?.origin_action_id !== HARD_DATA_ORIGIN_ACTION_ID
    || capability?.evidence_policy_id !== HARD_DATA_EVIDENCE_POLICY_ID
  ) return null;
  return capability;
}

async function sendCruiseHardDataQuery(payload) {
  const text = String(payload.text || "").trim();
  if (!registeredCruiseHardDataCapability()) {
    return { ok: false, state, status: "hard_data_query_capability_unregistered", error: "别吃大数据能力未在当前运行契约中注册。" };
  }
  if (state.match_session?.status !== "active") {
    return { ok: false, state, status: "hard_data_query_requires_active_match", error: "别吃大数据只在当前对局中可用。" };
  }
  if (state.active_mode !== "cruise") {
    return { ok: false, state, status: "hard_data_query_requires_cruise", error: "别吃大数据只能从巡航模式发起。" };
  }
  return sendMessage(buildCruiseHardDataQueryPayload(text));
}

function registeredDailyCoreTheoryCapability() {
  const capability = runtimeUiModeContractForProactiveDecision?.modes?.daily_chat?.renderer?.core_theory_action;
  if (
    capability?.request_kind !== DAILY_CORE_THEORY_QUERY_REQUEST_KIND
    || capability?.origin_action_id !== DAILY_CORE_THEORY_ORIGIN_ACTION_ID
    || capability?.evidence_policy_id !== HARD_DATA_EVIDENCE_POLICY_ID
    || capability?.source_policy !== "active_core_profile_only"
  ) return null;
  return capability;
}

async function sendDailyCoreTheoryQuery(payload) {
  const text = String(payload.text || "").trim();
  if (!registeredDailyCoreTheoryCapability()) {
    return { ok: false, state, status: "daily_core_theory_query_capability_unregistered", error: "大厅别吃大数据能力未在当前运行契约中注册。" };
  }
  if (state.active_mode !== "daily_chat") {
    return { ok: false, state, status: "daily_core_theory_query_requires_daily_chat", error: "大厅别吃大数据只能从日常聊天模式发起。" };
  }
  return sendMessage({
    text,
    mode: "daily_chat",
    request_kind: DAILY_CORE_THEORY_QUERY_REQUEST_KIND,
    origin_action_id: DAILY_CORE_THEORY_ORIGIN_ACTION_ID,
    evidence_policy_id: HARD_DATA_EVIDENCE_POLICY_ID,
    [DAILY_CORE_THEORY_INTERNAL_AUTHORITY]: true,
  });
}

function buildCruiseHardDataQueryPayload(text) {
  return {
    text,
    mode: "cruise",
    request_kind: HARD_DATA_QUERY_REQUEST_KIND,
    origin_action_id: HARD_DATA_ORIGIN_ACTION_ID,
    evidence_policy_id: HARD_DATA_EVIDENCE_POLICY_ID,
    [HARD_DATA_INTERNAL_AUTHORITY]: true,
  };
}

function registeredCruisePopularRecipeCapability() {
  const capability = runtimeUiModeContractForProactiveDecision?.cruise_mode_policy?.renderer?.popular_recipe_action;
  if (
    capability?.request_kind !== POPULAR_RECIPE_QUERY_REQUEST_KIND
    || capability?.origin_action_id !== POPULAR_RECIPE_ORIGIN_ACTION_ID
    || capability?.evidence_policy_id !== POPULAR_RECIPE_EVIDENCE_POLICY_ID
    || capability?.source_policy !== "captured_popular_recipe_generation_only"
    || capability?.placement !== "cruise_actions_last"
  ) return null;
  return capability;
}

async function sendCruisePopularRecipeQuery(payload) {
  const text = String(payload.text || "").trim();
  if (!registeredCruisePopularRecipeCapability()) {
    return { ok: false, state, status: "popular_recipe_query_capability_unregistered", error: "热门阵容查询能力未在当前运行契约中注册。" };
  }
  if (state.match_session?.status !== "active") {
    return { ok: false, state, status: "popular_recipe_query_requires_active_match", error: "查热门阵容只在当前对局中可用。" };
  }
  if (state.active_mode !== "cruise") {
    return { ok: false, state, status: "popular_recipe_query_requires_cruise", error: "查热门阵容只能从巡航模式发起。" };
  }
  return sendMessage({
    text,
    mode: "cruise",
    request_kind: POPULAR_RECIPE_QUERY_REQUEST_KIND,
    origin_action_id: POPULAR_RECIPE_ORIGIN_ACTION_ID,
    evidence_policy_id: POPULAR_RECIPE_EVIDENCE_POLICY_ID,
    [POPULAR_RECIPE_INTERNAL_AUTHORITY]: true,
  });
}

async function pollCruiseAdvice() {
  if (state.match_session?.ui_ready === false) {
    return { ok: true, state, status: "match_not_ready" };
  }
  if (state.match_session.status !== "active") {
    return { ok: true, state, status: "inactive_match" };
  }
  await syncWatcherServiceState("poll_cruise_advice");
  await repairStaleWatcherProcess("poll_cruise_advice");
  await ensureActiveMatchWatcherRunning("poll_cruise_advice");
  const earlyChoiceReservation = await reserveUpcomingChoiceBeforeAutomaticAdvice("poll_cruise_advice");
  if (earlyChoiceReservation) {
    await persistStateAndCanonicalResponseTask({
      source: "poll_cruise_choice_window_reservation",
      event_type: "runtime_event_response_task_preempted",
      event_payload: {
        reason: "choice_window_reserved_for_user_report",
        target_stage_round: earlyChoiceReservation.quiet?.entry?.target_stage_round || null,
      },
    });
  }
  const preGateSelfStateRefresh = startBackgroundSelfStateRefresh("poll_cruise_pre_response_task_self_state_refresh");
  if (preGateSelfStateRefresh?.ok && state.self_state_refresh?.status !== "running") {
    state.self_state_refresh = {
      ...(state.self_state_refresh || {}),
      status: "queued",
      last_started_at: new Date().toISOString(),
      reason: preGateSelfStateRefresh.reason,
    };
    await persistState();
  }
  const staleRuntimeEvents = reconcileRuntimeEventAdviceRunningTasks({
    reason: "poll_cruise_timeout_reconcile",
    timeoutOnly: true,
  });
  if (staleRuntimeEvents.changed) await persistState();
  await reconcilePreparingHostCoachResponseTask("poll_cruise_advice");

  const staleChoiceTaskLiveState = state.response_task && choiceVisualRuntimeModes.has(state.response_task.mode || "")
    ? (await resolveActiveLiveStateForRuntime({ purpose: "poll_cruise_stale_choice_task_guard" })).live_state
    : null;
  if (staleChoiceTaskLiveState && suppressStaleChoiceResponseTaskForCurrentMode(staleChoiceTaskLiveState, "poll_cruise_before_response_task_delivery")) {
    await persistState();
  }

  if (state.response_task?.status === "completed" && state.response_task?.response && !state.response_task?.delivered_at) {
    const taskForDelivery = { ...state.response_task };
    const response = state.response_task.response;
    if (automaticHostResponseTask(state.response_task)) {
      const currentLiveState = await resolveActiveLiveStateForRuntime({ purpose: "poll_cruise_delivery_expiry_check" });
      const currentStageRound = latestKnownStageRound(currentLiveState.live_state)
        || stageRoundFromLiveState(currentLiveState.live_state);
      const deliveryExpiry = automaticHostResponseDeliveryExpiry(state.response_task, currentLiveState.live_state);
      if (deliveryExpiry?.disposition === "defer") {
        return {
          ok: true,
          state,
          status: "response_pending",
          pending_reason: deliveryExpiry.reason,
          response_task: taskForDelivery,
          match_connection: state.match_connection,
        };
      }
      if (deliveryExpiry) {
        requeueStrategicRuntimeTask(
          state.response_task,
          `strategic_runtime_event_retry_after_${deliveryExpiry.reason || "stale_delivery"}`,
        );
        state.response_task = withCurrentMatchSessionIdForResponseTask({
          ...state.response_task,
          status: "stale_logged_only",
          delivered_at: new Date().toISOString(),
          current_stage_round: currentStageRound || null,
          response_task_id: null,
          previous_response_task_id: state.response_task?.response_task_id || null,
          stale_reason: deliveryExpiry.reason,
        });
        activeResponseTaskId = null;
        recordRuntimeEvent("poll_cruise_completed_response_stale_logged_only", state.response_task);
        await persistStateAndCanonicalResponseTask();
        return {
          ok: true,
          state,
          status: "stale_logged_only",
          stale_reason: state.response_task.stale_reason,
          match_connection: state.match_connection,
        };
      }
    }
    return { ok: true, state, status: "completed", response, response_task: taskForDelivery, match_connection: state.match_connection };
  }

  if (state.response_task?.status === "failed" && !state.response_task?.delivered_at) {
    return undeliveredFailedResponseTaskPayload("poll_cruise_failed_response_ready");
  }

  if (
    choiceVisualRuntimeModes.has(state.active_mode || "")
    && state.visual_request_status
    && !visualRequestModeMatchesActiveChoice(state.visual_request_status)
  ) {
    supersedeVisualRequestForMode(state.active_mode, "poll_cruise_choice_mode_guard");
    await persistState();
  }

  const runningCoach = await reconcileRunningHostCoachResponseTask("poll_cruise_advice");
  if (runningCoach.completed) return { ok: true, state, status: "response_ready", response_task: state.response_task };
  if (responseTaskIsUndeliveredFailed()) {
    return undeliveredFailedResponseTaskPayload("poll_cruise_running_timeout_ready");
  }
  if (runningCoach.cleared && !responseTaskIsUndeliveredFailed()) {
    return automaticHostTimeoutAuditPayload(runningCoach);
  }
  if (state.response_task?.status === "running") {
    return { ok: true, state, status: "response_running" };
  }
  if (state.response_task?.status === "preparing") {
    return { ok: true, state, status: "response_running", response_task: state.response_task };
  }
  if (userManualChoiceResponseInFlight(state.response_task)) {
    recordRuntimeEvent("manual_choice_user_response_in_flight_cruise_blocked", {
      response_task_id: state.response_task.response_task_id || null,
      mode: state.response_task.mode || null,
      pipeline_file: state.response_task.pipeline_file || null,
      awaiting_since: state.response_task.awaiting_since || null,
      active_mode: state.active_mode || null,
    });
    return { ok: true, state, status: "manual_choice_user_response_in_flight", response_task: state.response_task };
  }

  const pendingCoach = hostCoachResponsePendingInfo(state.response_task);
  if (pendingCoach.pending) {
    const reconciled = await reconcilePendingHostCoachResponseTask("poll_cruise_advice");
    if (reconciled.completed) return { ok: true, state, status: "response_ready", response_task: state.response_task };
    if (responseTaskIsUndeliveredFailed()) {
      return undeliveredFailedResponseTaskPayload("poll_cruise_pending_timeout_ready");
    }
    if (reconciled.cleared && !responseTaskIsUndeliveredFailed()) {
      return automaticHostTimeoutAuditPayload(reconciled);
    }
    return { ok: true, state, status: "response_pending", response_task: state.response_task };
  }

  const liveState = path.join(currentWatchDir, "cruise-live-state.json");
  if (!existsSync(liveState)) {
    return {
      ok: true,
      state,
      status: "no_live_state",
      watcher: state.watcher || null,
      last_watcher_error: state.last_watcher_error || null,
      last_watcher_stdout: state.last_watcher_stdout || null,
      match_connection: state.match_connection,
    };
  }

  let activeLiveState = await resolveActiveLiveStateForRuntime({ purpose: "poll_cruise_advice_observe_only" });
  if (!activeLiveState.live_state) {
    return {
      ok: true,
      state,
      status: "waiting_for_current_match_live_state",
      match_connection: state.match_connection,
      rejected_base_match_session_id: activeLiveState.rejected_base_match_session_id || null,
    };
  }
  if (!activeLiveStateStageKey(activeLiveState.live_state)) {
    const selfStateRoiStage = await refreshStageFromSelfStateRoiOcr("poll_cruise_stage_self_state_roi_ocr");
    if (selfStateRoiStage?.ok) {
      activeLiveState = await resolveActiveLiveStateForRuntime({ purpose: "poll_cruise_after_stage_self_state_roi_ocr" });
    }
  }

  activeLiveState = await materializeResolvedLiveStateForRuntime(activeLiveState, "poll_cruise_observe_only");
  const rawLiveState = activeLiveState.live_state;
  const liveStateSummary = compactLiveStateForHost(rawLiveState);
  const matchConnectionChanged = updateMatchConnectionFromLiveState(liveStateSummary);
  if (matchConnectionChanged) await persistState();
  const initialGreeting = await runInitialCruiseGreeting(rawLiveState);
  if (initialGreeting) return initialGreeting;
  if (supersedeVisualRequestIfStageChanged(rawLiveState, "poll_cruise_stage_changed_before_visual_continuation")) await persistState();
  if (suppressStaleChoiceVisualForCurrentMode(rawLiveState, "poll_cruise_suppress_stale_choice_visual_before_continuation")) await persistState();
  const selfStateRefresh = startBackgroundSelfStateRefresh("poll_cruise_background_self_state_refresh");
  if (selfStateRefresh?.ok && state.self_state_refresh?.status !== "running") {
    state.self_state_refresh = {
      ...(state.self_state_refresh || {}),
      status: "queued",
      last_started_at: new Date().toISOString(),
      reason: selfStateRefresh.reason,
    };
    await persistState();
  }

  if (
    choiceVisualRuntimeModes.has(state.active_mode || "")
    && visualRequestModeMatchesActiveChoice(state.visual_request_status || {})
    && ["awaiting_host_cli_agent_response", "running_host_cli_visual", "completed", "awaiting_host_cli_agent_coach_response"].includes(state.visual_request_status?.status)
  ) {
    const continuedManualVisual = await continuePendingVisualToAdvice("poll_cruise_continue_manual_choice_visual");
    if (continuedManualVisual) return { ...continuedManualVisual, match_connection: state.match_connection };
  }
  const quietForChoice = shouldQuietCruiseForUpcomingChoice(rawLiveState);
  if (quietForChoice) {
    const cruiseFactObservation = recordCruiseStateFingerprintObservation(rawLiveState);
    recordRuntimeEvent("legacy_poll_cruise_advice_observe_only", {
      stage_round: stageRoundFromLiveState(rawLiveState),
      policy: "pollCruiseAdvice observed a quiet choice window; automatic advice must pass observeRuntimeTick semantic event gates.",
      quiet_for_upcoming_choice: true,
      cruise_state_fingerprint: cruiseFactObservation?.hash || null,
    });
    await persistState();
    return {
      ok: true,
      state,
      status: cruiseFactObservation?.unchanged ? "unchanged_cruise_state_skipped" : "runtime_observed",
      phase_trigger: {
        stage_round: quietForChoice.entry?.target_stage_round || quietForChoice.entry?.stage_round || null,
        mode: quietForChoice.entry?.mode || null,
        phase: quietForChoice.entry?.phase || null,
        source_stage_round: quietForChoice.entry?.stage_round || null,
      },
      cruise_state_fingerprint: state.cruise_state_fingerprint || null,
      match_connection: state.match_connection,
      observation_policy: {
        observe_only: true,
        host_model_invoked: false,
        reason: "background cruise is quiet near a choice window; manual choice mode remains prioritized",
        quiet_for_upcoming_choice: true,
        automatic_advice_must_use: "observeRuntimeTick_semantic_event_gate",
      },
    };
  }

  const cruiseFactObservation = recordCruiseStateFingerprintObservation(rawLiveState);
  const responseTaskInFlight = Boolean(activeResponseTaskId)
    || state.response_task?.status === "preparing"
    || state.response_task?.status === "running"
    || hostCoachResponseIsPending(state.response_task);
  const missingChoicePrompt = responseTaskInFlight
    ? null
    : await maybePromptForMissingChoiceConfirmation(rawLiveState);
  if (missingChoicePrompt) {
    return { ok: true, state, status: "missing_choice_confirmation_prompt", prompt: missingChoicePrompt, match_connection: state.match_connection };
  }
  recordRuntimeEvent("legacy_poll_cruise_advice_observe_only", {
    stage_round: stageRoundFromLiveState(rawLiveState),
    policy: "pollCruiseAdvice no longer starts background cruise host requests; automatic advice must pass observeRuntimeTick semantic event gates.",
    cruise_state_fingerprint: cruiseFactObservation?.hash || null,
  });
  await persistState();
  return {
    ok: true,
    state,
    status: cruiseFactObservation?.unchanged ? "unchanged_cruise_state_skipped" : "runtime_observed",
    match_connection: state.match_connection,
    cruise_state_fingerprint: state.cruise_state_fingerprint || null,
    observation_policy: {
      observe_only: true,
      host_model_invoked: false,
      automatic_advice_must_use: "observeRuntimeTick_semantic_event_gate",
    },
  };
}

async function deliverReadyResponse() {
  await reconcilePreparingHostCoachResponseTask("delivery_only");
  const runningReconciled = await reconcileRunningHostCoachResponseTask("delivery_only");
  if (runningReconciled.cleared && !responseTaskIsUndeliveredFailed()) {
    return automaticHostTimeoutAuditPayload(runningReconciled);
  }
  const pendingReconciled = await reconcilePendingHostCoachResponseTask("delivery_only");
  if (pendingReconciled.cleared && !responseTaskIsUndeliveredFailed()) {
    return automaticHostTimeoutAuditPayload(pendingReconciled);
  }
  if (state.response_task?.status === "completed" && state.response_task?.response && !state.response_task?.delivered_at) {
    const taskForDelivery = { ...state.response_task };
    const response = state.response_task.response;
    if (automaticHostResponseTask(state.response_task)) {
      const currentLiveState = await resolveActiveLiveStateForRuntime({ purpose: "delivery_only_expiry_check" });
      const currentStageRound = latestKnownStageRound(currentLiveState.live_state)
        || stageRoundFromLiveState(currentLiveState.live_state);
      const deliveryExpiry = automaticHostResponseDeliveryExpiry(state.response_task, currentLiveState.live_state);
      if (deliveryExpiry?.disposition === "defer") {
        return {
          ok: true,
          state,
          status: "response_pending",
          pending_reason: deliveryExpiry.reason,
          response_task: taskForDelivery,
          match_connection: state.match_connection,
        };
      }
      if (deliveryExpiry) {
        requeueStrategicRuntimeTask(
          state.response_task,
          `strategic_runtime_event_retry_after_${deliveryExpiry.reason || "stale_delivery"}`,
        );
        state.response_task = withCurrentMatchSessionIdForResponseTask({
          ...state.response_task,
          status: "stale_logged_only",
          delivered_at: new Date().toISOString(),
          current_stage_round: currentStageRound || null,
          response_task_id: null,
          previous_response_task_id: state.response_task?.response_task_id || null,
          stale_reason: deliveryExpiry.reason,
        });
        activeResponseTaskId = null;
        recordRuntimeEvent("delivery_only_completed_response_stale_logged_only", state.response_task);
        await persistStateAndCanonicalResponseTask();
        return {
          ok: true,
          state,
          status: "stale_logged_only",
          stale_reason: state.response_task.stale_reason,
          match_connection: state.match_connection,
        };
      }
    }
    return {
      ok: true,
      state,
      status: "completed",
      response,
      response_task: taskForDelivery,
      match_connection: state.match_connection,
    };
  }
  if (state.response_task?.status === "failed" && !state.response_task?.delivered_at) {
    return undeliveredFailedResponseTaskPayload("delivery_only_failed_response_ready");
  }
  return {
    ok: true,
    state,
    status: state.response_task?.status === "running" || state.response_task?.status === "preparing"
      ? "response_running"
      : hostCoachResponseIsPending(state.response_task)
        ? "response_pending"
        : "no_response_ready",
    response_task: state.response_task || null,
    match_connection: state.match_connection,
  };
}

async function observeRuntimeTick() {
  if (state.match_session?.ui_ready === false) {
    return { ok: true, state, status: "match_not_ready" };
  }
  const observeStartedAt = Date.now();
  const observeTiming = {};
  const markObserveTiming = (checkpoint) => {
    observeTiming[checkpoint] = Date.now() - observeStartedAt;
  };
  if (state.match_session.status !== "active") {
    return { ok: true, state, status: "inactive_match" };
  }
  await syncWatcherServiceState("observe_runtime_tick");
  await repairStaleWatcherProcess("observe_runtime_tick");
  await ensureActiveMatchWatcherRunning("observe_runtime_tick");
  markObserveTiming("watcher_health_ms");
  const earlyChoiceReservation = await reserveUpcomingChoiceBeforeAutomaticAdvice("observe_runtime_tick");
  if (earlyChoiceReservation) {
    await persistStateAndCanonicalResponseTask({
      source: "observe_runtime_tick_choice_window_reservation",
      event_type: "runtime_event_response_task_preempted",
      event_payload: {
        reason: "choice_window_reserved_for_user_report",
        target_stage_round: earlyChoiceReservation.quiet?.entry?.target_stage_round || null,
      },
    });
  }
  const preGateSelfStateRefresh = startBackgroundSelfStateRefresh("observe_runtime_tick_pre_response_task_self_state_refresh");
  if (preGateSelfStateRefresh?.ok && state.self_state_refresh?.status !== "running") {
    state.self_state_refresh = {
      ...(state.self_state_refresh || {}),
      status: "queued",
      last_started_at: new Date().toISOString(),
      reason: preGateSelfStateRefresh.reason,
    };
    await persistState();
  }
  const staleRuntimeEvents = reconcileRuntimeEventAdviceRunningTasks({
    reason: "observe_runtime_tick_timeout_reconcile",
    timeoutOnly: true,
  });
  if (staleRuntimeEvents.changed) await persistState();
  await reconcilePreparingHostCoachResponseTask("observe_runtime_tick");
  markObserveTiming("pre_gate_reconcile_ms");
  const liveState = path.join(currentWatchDir, "cruise-live-state.json");
  if (!existsSync(liveState)) {
    if (state.response_task?.status === "completed" && state.response_task?.response && !state.response_task?.delivered_at) {
      return { ok: true, state, status: "response_ready", response_task: state.response_task };
    }
    if (state.response_task?.status === "failed" && !state.response_task?.delivered_at) {
      return {
        ok: false,
        state,
        status: "response_failed_ready",
        error: state.response_task.error || "host_cli_agent_response_failed",
        response_task: state.response_task,
      };
    }
    const runningReconciled = await reconcileRunningHostCoachResponseTask("observe_runtime_tick_no_live_state");
    if (runningReconciled.completed) return { ok: true, state, status: "response_ready", response_task: state.response_task };
    if (runningReconciled.cleared) {
      return automaticHostTimeoutAuditPayload(runningReconciled);
    }
    const pendingReconciled = await reconcilePendingHostCoachResponseTask("observe_runtime_tick_no_live_state");
    if (pendingReconciled.completed) return { ok: true, state, status: "response_ready", response_task: state.response_task };
    if (pendingReconciled.cleared) {
      return automaticHostTimeoutAuditPayload(pendingReconciled);
    }
    if (runningReconciled.running || state.response_task?.status === "preparing") {
      return { ok: true, state, status: "response_running", response_task: state.response_task };
    }
    if (pendingReconciled.pending) {
      return { ok: true, state, status: "response_pending", response_task: state.response_task };
    }
    return {
      ok: true,
      state,
      status: "no_live_state",
      watcher: state.watcher || null,
      last_watcher_error: state.last_watcher_error || null,
      last_watcher_stdout: state.last_watcher_stdout || null,
      match_connection: state.match_connection,
    };
  }
  let activeLiveState = await resolveActiveLiveStateForRuntime({ purpose: "observe_runtime_tick" });
  markObserveTiming("resolve_live_state_ms");
  if (!activeLiveState.live_state) {
    if (state.response_task?.status === "completed" && state.response_task?.response && !state.response_task?.delivered_at) {
      return { ok: true, state, status: "response_ready", response_task: state.response_task };
    }
    if (state.response_task?.status === "failed" && !state.response_task?.delivered_at) {
      return {
        ok: false,
        state,
        status: "response_failed_ready",
        error: state.response_task.error || "host_cli_agent_response_failed",
        response_task: state.response_task,
      };
    }
    if (state.response_task?.status === "preparing" || state.response_task?.status === "running") {
      return { ok: true, state, status: "response_running", response_task: state.response_task };
    }
    if (hostCoachResponseIsPending(state.response_task)) {
      return { ok: true, state, status: "response_pending", response_task: state.response_task };
    }
    return {
      ok: true,
      state,
      status: "waiting_for_current_match_live_state",
      match_connection: state.match_connection,
      rejected_base_match_session_id: activeLiveState.rejected_base_match_session_id || null,
    };
  }
  if (!activeLiveStateStageKey(activeLiveState.live_state)) {
    const selfStateRoiStage = await refreshStageFromSelfStateRoiOcr("observe_runtime_tick_stage_self_state_roi_ocr");
    if (selfStateRoiStage?.ok) {
      activeLiveState = await resolveActiveLiveStateForRuntime({ purpose: "observe_runtime_tick_after_stage_self_state_roi_ocr" });
    }
  }
  activeLiveState = await materializeResolvedLiveStateForRuntime(activeLiveState, "observe_runtime_tick");
  markObserveTiming("materialize_live_state_ms");
  const rawLiveState = activeLiveState.live_state;
  const liveStateSummary = compactLiveStateForHost(rawLiveState);
  const matchConnectionChanged = updateMatchConnectionFromLiveState(liveStateSummary);
  if (matchConnectionChanged) await persistState();
  if (supersedeVisualRequestIfStageChanged(rawLiveState, "observe_runtime_tick_stage_changed_before_visual_continuation")) {
    await persistState();
  }
  if (suppressStaleChoiceVisualForCurrentMode(rawLiveState, "observe_runtime_tick_suppress_stale_choice_visual")) {
    await persistState();
  }
  await maybeStartChoicePretrigger(rawLiveState, "observe_runtime_tick_stage_pretrigger");
  const selfStateRefresh = startBackgroundSelfStateRefresh("observe_runtime_tick_background_self_state_refresh");
  if (selfStateRefresh?.ok && state.self_state_refresh?.status !== "running") {
    state.self_state_refresh = {
      ...(state.self_state_refresh || {}),
      status: "queued",
      last_started_at: new Date().toISOString(),
      reason: selfStateRefresh.reason,
    };
    await persistState();
  }
  const phaseTrigger = await maybeHandleRuntimePhaseTrigger(rawLiveState, "observe_runtime_tick_phase_trigger");
  markObserveTiming("phase_trigger_ms");
  const matchContextForEvents = await readMatchContextForActiveMatch();
  markObserveTiming("match_context_ms");
  if (matchContextForEvents) state.match_context = matchContextForEvents;
  const eventDecisionSnapshot = buildDecisionSnapshot({
    mode: state.active_mode || "cruise",
    liveStateSummary,
    matchContext: matchContextForEvents,
    matchFacts: buildHostMatchFacts(matchContextForEvents, {
      stageRound: latestKnownStageRound(liveStateSummary),
      effectiveTargetPlan: effectiveTargetPlanFromMatchContext(matchContextForEvents, liveStateSummary),
    }),
  });
  state.resolved_decision_snapshot = eventDecisionSnapshot;
  const semanticEvents = detectRuntimeSemanticEvents(rawLiveState, {
    source: "observe_runtime_tick",
    match_context: matchContextForEvents,
    decision_snapshot: eventDecisionSnapshot,
  });
  markObserveTiming("detect_semantic_events_ms");
  const retryAdviceEvents = retryableRuntimeEventAdviceEvents(rawLiveState);
  await persistState();
  markObserveTiming("semantic_events_ms");

  const adviceEventsByKey = new Map();
  for (const event of [
    ...retryAdviceEvents,
    ...semanticEvents.filter((entry) => entry.advice_eligible && entry.supporting_only !== true),
  ]) {
    const key = runtimeEventAdviceKey(event);
    if (key) adviceEventsByKey.set(key, event);
  }
  const adviceEligibleEvents = sortRuntimeEventsByAdvicePriority([...adviceEventsByKey.values()], rawLiveState);
  const staleRuntimeEventPreemption = preemptStaleRuntimeEventResponseTask(rawLiveState);
  if (staleRuntimeEventPreemption) {
    await persistStateAndCanonicalResponseTask({
      source: "observe_runtime_tick_stale_event_preemption",
      event_type: "runtime_event_response_task_preempted",
      event_payload: staleRuntimeEventPreemption,
    });
  }
  const semanticPreemption = preemptRuntimeEventForHigherPrioritySemanticEvents(adviceEligibleEvents, rawLiveState);
  if (semanticPreemption) {
    await persistStateAndCanonicalResponseTask({
      source: "observe_runtime_tick_higher_priority_event_preemption",
      event_type: "runtime_event_response_task_preempted",
      event_payload: semanticPreemption,
    });
  }

  const deferAdviceEventsForOccupiedResponseLane = async (reason) => {
    let changed = false;
    for (const event of adviceEligibleEvents) {
      changed = rememberRetryableRuntimeEventAdvice(event, { ok: false, reason }, runtimeEventAdviceKey(event), rawLiveState) || changed;
    }
    if (changed) await persistState();
  };

  if (state.response_task?.status === "completed" && state.response_task?.response && !state.response_task?.delivered_at) {
    await deferAdviceEventsForOccupiedResponseLane("response_task_active");
    return {
      ok: true,
      state,
      status: "response_ready",
      response_task: state.response_task,
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
    };
  }
  if (state.response_task?.status === "failed" && !state.response_task?.delivered_at) {
    await deferAdviceEventsForOccupiedResponseLane("response_task_active");
    return {
      ok: false,
      state,
      status: "response_failed_ready",
      error: state.response_task.error || "host_cli_agent_response_failed",
      response_task: state.response_task,
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
    };
  }

  const runningReconciled = await reconcileRunningHostCoachResponseTask("observe_runtime_tick");
  if (runningReconciled.completed) {
    await deferAdviceEventsForOccupiedResponseLane("response_task_active");
    return { ok: true, state, status: "response_ready", response_task: state.response_task, runtime_events: semanticEvents, advice_eligible_events: adviceEligibleEvents };
  }
  if (runningReconciled.cleared) {
    return automaticHostTimeoutAuditPayload(runningReconciled, {
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
    });
  }
  const pendingReconciled = await reconcilePendingHostCoachResponseTask("observe_runtime_tick");
  markObserveTiming("host_reconcile_ms");
  if (pendingReconciled.completed) {
    await deferAdviceEventsForOccupiedResponseLane("response_task_active");
    return { ok: true, state, status: "response_ready", response_task: state.response_task, runtime_events: semanticEvents, advice_eligible_events: adviceEligibleEvents };
  }
  if (pendingReconciled.cleared) {
    return automaticHostTimeoutAuditPayload(pendingReconciled, {
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
    });
  }

  const responseTaskInFlight = runningReconciled.running
    || pendingReconciled.pending
    || state.response_task?.status === "cancelling"
    || state.response_task?.status === "preparing"
    || state.response_task?.status === "running"
    || hostCoachResponseIsPending(state.response_task);
  if (!responseTaskInFlight) {
    const initialGreeting = await runInitialCruiseGreeting(rawLiveState);
    markObserveTiming("initial_greeting_ms");
    if (initialGreeting) {
      return {
        ...initialGreeting,
        runtime_events: semanticEvents,
        retry_advice_events: retryAdviceEvents,
        advice_eligible_events: adviceEligibleEvents,
        phase_trigger: phaseTrigger,
      };
    }
  }

  const missingChoicePrompt = responseTaskInFlight
    ? null
    : await maybePromptForMissingChoiceConfirmation(rawLiveState);
  if (missingChoicePrompt) {
    await persistState();
    return {
      ok: true,
      state,
      status: "missing_choice_confirmation_prompt",
      prompt: missingChoicePrompt,
      runtime_events: semanticEvents,
      retry_advice_events: retryAdviceEvents,
      advice_eligible_events: semanticEvents.filter((entry) => entry.advice_eligible),
      phase_trigger: phaseTrigger,
      match_connection: state.match_connection,
    };
  }
  for (const event of adviceEligibleEvents) {
    const adviceStart = await startRuntimeEventAdvice(event, rawLiveState, activeLiveState);
    if (adviceStart?.ok && !adviceStart.skipped && adviceStart.status === "response_preparing") {
      markObserveTiming("response_preparing_ms");
      return {
        ...adviceStart,
        observe_timing: observeTiming,
        runtime_events: semanticEvents,
        advice_eligible_events: adviceEligibleEvents,
        phase_trigger: phaseTrigger,
        match_connection: state.match_connection,
      };
    }
  }

  if (state.response_task?.status === "preparing" || state.response_task?.status === "running") {
    return {
      ok: true,
      state,
      status: "response_running",
      response_task: state.response_task,
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
      phase_trigger: phaseTrigger,
      match_connection: state.match_connection,
    };
  }
  if (hostCoachResponseIsPending(state.response_task)) {
    return {
      ok: true,
      state,
      status: "response_pending",
      response_task: state.response_task,
      runtime_events: semanticEvents,
      advice_eligible_events: adviceEligibleEvents,
      phase_trigger: phaseTrigger,
      match_connection: state.match_connection,
    };
  }
  return {
    ok: true,
    state,
    status: "runtime_observed",
    runtime_events: semanticEvents,
    retry_advice_events: retryAdviceEvents,
    advice_eligible_events: adviceEligibleEvents,
    phase_trigger: phaseTrigger,
    match_connection: state.match_connection,
    observation_policy: {
      observe_only: true,
      host_model_invoked: false,
      fact_events_do_not_call_host_model: true,
      advice_requires_event_gate: true,
    },
  };
}

async function stopResponse(payload = {}) {
  const requestedTaskId = typeof payload.response_task_id === "string" && payload.response_task_id.trim()
    ? payload.response_task_id.trim()
    : null;
  const requestedRevision = Number(payload.response_task_revision);
  const currentResponseTaskId = typeof state.response_task?.response_task_id === "string" && state.response_task.response_task_id.trim()
    ? state.response_task.response_task_id.trim()
    : null;
  const currentActiveTaskId = typeof activeResponseTaskId === "string" && activeResponseTaskId.trim()
    ? activeResponseTaskId.trim()
    : null;
  if (
    requestedTaskId
    && requestedTaskId !== currentResponseTaskId
    && requestedTaskId !== currentActiveTaskId
  ) {
    return {
      ok: false,
      status: "response_task_id_mismatch",
      state,
      stopped: false,
      message: "已忽略过期的停止请求，当前回答未被打断。",
      requested_response_task_id: requestedTaskId,
      current_response_task_id: currentResponseTaskId,
      active_response_task_id: currentActiveTaskId,
    };
  }
  if (requestedTaskId) {
    const currentRevision = Number(state.response_task?.revision);
    if (!Number.isInteger(requestedRevision) || requestedRevision < 0) {
      return {
        ok: false,
        status: "response_task_revision_required",
        state,
        stopped: false,
        message: "停止请求缺少当前回答版本；我没有打断正在生成的回答。",
        expected_response_task_revision: Number.isInteger(currentRevision) ? currentRevision : null,
      };
    }
    if (!Number.isInteger(currentRevision) || requestedRevision !== currentRevision) {
      return {
        ok: false,
        status: "response_task_revision_mismatch",
        state,
        stopped: false,
        message: "已忽略过期的停止请求，当前回答未被打断。",
        expected_response_task_revision: Number.isInteger(currentRevision) ? currentRevision : null,
        received_response_task_revision: requestedRevision,
      };
    }
  }
  const taskId = requestedTaskId || currentResponseTaskId || currentActiveTaskId || null;
  if (!taskId) {
    return {
      ok: true,
      status: "no_active_response_task",
      state,
      stopped: false,
      message: "当前没有正在生成的回答。",
    };
  }
  const preemptiveCancellation = payload.__daemon_preemptive_host_cancellation;
  const cancellation = preemptiveCancellation?.requested_task_id === taskId
    && Number(preemptiveCancellation?.response_task_revision) === requestedRevision
    ? preemptiveCancellation
    : cancelHostAgentRunDetailed(taskId);
  const hostProcessMustBeCancelled = hostCoachResponseIsPending(state.response_task)
    || hostCoachResponseRunningInfo(state.response_task).running
    || state.response_task?.status === "cancelling";
  const cancellationHandleRetained = cancellation.accepted
    && Number(cancellation.retained_count || 0) > 0;
  const retainedHandleAlreadySettled = state.response_task?.status === "cancelling"
    && Number(cancellation.matched_count || 0) === 0;
  if (hostProcessMustBeCancelled && !cancellation.accepted && !retainedHandleAlreadySettled) {
    return {
      ok: false,
      status: "response_cancellation_failed",
      state,
      stopped: false,
      response_task_cancelled: false,
      cancellation,
      message: "底层 CLI 没有确认停止；当前回答仍保持运行状态，请重试停止。",
    };
  }
  const cancelledTask = state.response_task && typeof state.response_task === "object"
    ? { ...state.response_task }
    : null;
  const cancelledHostRequestId = cancelledTask?.response?.request_id
    || cancelledTask?.host_request?.request_id
    || cancelledTask?.host_request?.host_cli_agent_request?.request_id
    || null;
  if (cancellationHandleRetained) {
    state.response_task = withCurrentMatchSessionIdForResponseTask({
      ...cancelledTask,
      status: "cancelling",
      response_task_id: taskId,
      cancellation_requested_at: new Date().toISOString(),
      cancellation_reason: "user_stop_response",
      cancellation,
    });
    await persistStateAndCanonicalResponseTask();
    return {
      ok: true,
      status: "response_cancellation_pending",
      state,
      stopped: false,
      response_task_cancelled: false,
      cancellation_scope: "provider_turn_cancellation_pending",
      cancellation,
      message: "底层 CLI 已收到停止请求，但还没有确认完成；当前任务仍可继续停止。",
    };
  }
  const stopped = cancellation.accepted;
  if (runtimeTaskIsStrategicLineup(cancelledTask)) {
    requeueStrategicRuntimeTask(cancelledTask, "user_stop_response");
    const eventKey = cancelledTask?.event_key || null;
    if (eventKey && state.runtime_event_advice?.handled?.[eventKey]) {
      state.runtime_event_advice.handled[eventKey] = {
        ...state.runtime_event_advice.handled[eventKey],
        status: "cancelled_retry_pending",
        cancelled_at: new Date().toISOString(),
        cancelled_reason: "user_stop_response",
      };
      releaseRuntimeEventAdviceCooldown(eventKey);
    }
    clearScheduledFixedCheckpointForEvent(
      cancelledTask?.runtime_event_context || cancelledTask,
      "user_stop_response",
    );
  }
  if (
    !requestedTaskId
    || requestedTaskId === currentActiveTaskId
    || requestedTaskId === currentResponseTaskId
    || (currentActiveTaskId && currentActiveTaskId.startsWith(`${requestedTaskId}:`))
  ) {
    activeResponseTaskId = null;
  }
  state.response_task = withCurrentMatchSessionIdForResponseTask({
    status: "cancelled",
    response_task_id: null,
    cancelled_response_task_id: taskId,
    cancelled_host_request_id: cancelledHostRequestId,
    cancelled_at: new Date().toISOString(),
    cancelled_reason: "user_stop_response",
    stopped_host_process: stopped,
  });
  await persistStateAndCanonicalResponseTask();
  return {
    ok: true,
    state,
    stopped,
    response_task_cancelled: true,
    cancellation_scope: stopped ? "host_process_and_task_ownership" : "pre_host_task_ownership",
    cancellation,
    message: "已停止当前回答；当前模式保持不变。",
  };
}

async function getResolvedLiveState(options = {}) {
  const purpose = typeof options.purpose === "string" && options.purpose.trim()
    ? options.purpose.trim()
    : "diagnostic";
  const activeLiveState = await materializeResolvedLiveStateForRuntime(
    await resolveActiveLiveStateForRuntime({ purpose }),
    purpose,
  );
  return {
    ok: Boolean(activeLiveState?.live_state),
    status: activeLiveState?.live_state ? "resolved_live_state_ready" : "resolved_live_state_missing",
    ...activeLiveState,
  };
}

function markRuntimeCleanShutdown(reason) {
  state.runtime_lifecycle = {
    ...(state.runtime_lifecycle || {}),
    clean_shutdown: true,
    runtime_instance_id: runtimeServiceInstanceId,
    last_shutdown_at: new Date().toISOString(),
    last_shutdown_reason: reason || "runtime_shutdown",
  };
}

async function closeWindow(window) {
  const previousMatchForLease = state.match_session?.status === "active"
    ? structuredClone(state.match_session)
    : null;
  const matchRetirement = stopMatchStateForCleanRuntimeShutdown("close_window");
  const watcherTermination = await killWatcher();
  const stoppedHostProcess = cancelHostAgentRun();
  const closedHostSessions = await closeAllHostAgentSessions();
  await resetAllRapidOcrWorkers("close_window");
  const shutdownConfirmed = watcherTermination.stopped && closedHostSessions.closed === true;
  if (!shutdownConfirmed) {
    if (!watcherTermination.stopped) {
      state.watcher = {
        ...(state.watcher || {}),
        status: "kill_failed",
        pid: watcherTermination.pid,
        error: watcherTermination.error,
      };
    }
    await persistStateAndCanonicalResponseTask({
      source: !watcherTermination.stopped
        ? "close_window_watcher_termination_failed"
        : "close_window_host_termination_failed",
      event_type: !watcherTermination.stopped
        ? "watcher_process_termination_failed"
        : "host_process_termination_failed",
    });
    await writeGameKnowledgeGenerationLeases([{
      core_profile_id: previousMatchForLease?.season_version_snapshot?.core_profile_id,
      ranking_overlay_id: previousMatchForLease?.season_version_snapshot?.ranking_overlay_id || null,
      recipe_generation_id: previousMatchForLease?.season_version_snapshot?.recipe_catalog_generation_id || null,
      match_session_id: previousMatchForLease?.match_session_id || null,
      status: "termination_failed",
      owner: "close_window",
      route_keys: closedHostSessions.failed_session_keys,
      reason: !watcherTermination.stopped ? "watcher_termination_failed" : "host_termination_failed",
    }]);
    await waitForRuntimeLegacyStateMirrors();
    return {
      ok: false,
      status: !watcherTermination.stopped ? "watcher_termination_failed" : "host_termination_failed",
      error: watcherTermination.error || "Host CLI transport process did not confirm exit.",
      watcher_termination: watcherTermination,
      stopped_host_process: stoppedHostProcess,
      closed_host_sessions: closedHostSessions,
      stopped_match_session_id: matchRetirement.stopped_match_session_id,
      retired_match_summary: matchRetirement.retired_match_summary,
      state,
    };
  }
  markRuntimeCleanShutdown("close_window");
  await writeGameKnowledgeGenerationLeases([], {
    release_match_session_ids: [previousMatchForLease?.match_session_id].filter(Boolean),
  });
  await persistState().catch(() => {});
  await waitForRuntimeLegacyStateMirrors();
  window.close();
  return {
    ok: true,
    state,
    stopped_match_session_id: matchRetirement.stopped_match_session_id,
    retired_match_summary: matchRetirement.retired_match_summary,
  };
}

async function shutdownRuntime(payload = {}, { deferCanonicalPersistence = false } = {}) {
  const previousMatchForLease = state.match_session?.status === "active"
    ? structuredClone(state.match_session)
    : null;
  const matchRetirement = stopMatchStateForCleanRuntimeShutdown(payload.reason || "daemon_shutdown");
  const watcherTermination = await killWatcher();
  const killedWatcher = watcherTermination.attempted && watcherTermination.stopped;
  const stoppedHostProcess = cancelHostAgentRun();
  const closedHostSessions = await closeAllHostAgentSessions();
  await resetAllRapidOcrWorkers("daemon_shutdown");
  await clearMatchScopedRuntimeFiles();
  const shutdownConfirmed = watcherTermination.stopped && closedHostSessions.closed === true;
  await writeGameKnowledgeGenerationLeases(shutdownConfirmed ? [] : [{
    core_profile_id: previousMatchForLease?.season_version_snapshot?.core_profile_id,
    ranking_overlay_id: previousMatchForLease?.season_version_snapshot?.ranking_overlay_id || null,
    recipe_generation_id: previousMatchForLease?.season_version_snapshot?.recipe_catalog_generation_id || null,
    match_session_id: previousMatchForLease?.match_session_id || null,
    status: "termination_failed",
    owner: "daemon_shutdown",
    route_keys: closedHostSessions.failed_session_keys,
    reason: !watcherTermination.stopped ? "watcher_termination_failed" : "host_termination_failed",
  }], {
    release_match_session_ids: shutdownConfirmed
      ? [previousMatchForLease?.match_session_id].filter(Boolean)
      : [],
  });
  recordRuntimeEvent("runtime_service_shutdown_cleanup", {
    reason: payload.reason || null,
    killed_watcher: killedWatcher,
    stopped_host_process: stoppedHostProcess,
    closed_host_sessions: closedHostSessions,
  });
  if (shutdownConfirmed) markRuntimeCleanShutdown(payload.reason || "daemon_shutdown");
  if (!deferCanonicalPersistence) await persistStateAndCanonicalResponseTask();
  await waitForRuntimeLegacyStateMirrors();
  return {
    ok: shutdownConfirmed,
    status: shutdownConfirmed
      ? "runtime_service_shutdown_cleaned"
      : !watcherTermination.stopped
        ? "watcher_termination_failed"
        : "host_termination_failed",
    killed_watcher: killedWatcher,
    watcher_termination: watcherTermination,
    stopped_host_process: stoppedHostProcess,
    stopped_match_session_id: matchRetirement.stopped_match_session_id,
    retired_match_summary: matchRetirement.retired_match_summary,
    state,
    ...(watcherTermination.error ? { error: watcherTermination.error } : {}),
  };
}

async function minimizeWindow(window) {
  await persistState().catch(() => {});
  if (window?.minimize) {
    window.minimize();
    return { ok: true, status: "minimized" };
  }
  return { ok: true, status: "preview_noop", state };
}

async function handleRuntimeAction(action, payload, window) {
  const body = assertPlainPayload(payload);
  switch (action) {
    case "bootstrap": return bootstrap(body);
    case "discoverHostCliAgents": return discoverHostCliAgents(body);
    case "detectHostCli": return detectHostCli(body);
    case "connectMumu": return connectMumu();
    case "startMatch": return startMatch();
    case "stopMatch": return stopMatch();
    case "setMode": return setMode(body);
    case "sendMessage": return sendMessage(body);
    case "sendCruiseHardDataQuery": return sendCruiseHardDataQuery(body);
    case "sendDailyCoreTheoryQuery": return sendDailyCoreTheoryQuery(body);
    case "sendCruisePopularRecipeQuery": return sendCruisePopularRecipeQuery(body);
    case "observeRuntimeTick": return observeRuntimeTick();
    case "deliverReadyResponse": return deliverReadyResponse();
    case "ackDeliveredResponse": return ackDeliveredResponse(body);
    case "pollCruiseAdvice": return pollCruiseAdvice();
    case "getResolvedLiveState": return getResolvedLiveState(body);
    case "stopResponse": return stopResponse(body);
    case "getDecisionInputOptions": return getDecisionInputOptions(body);
    case "captureDecisionInputOcrDraft": return captureDecisionInputOcrDraft(body);
    case "submitDecisionInput": return submitDecisionInput(body);
    case "confirmDecisionSelection": return confirmDecisionSelection(body);
    case "getManualVariableOptions": return getManualVariableOptions();
    case "saveManualVariables": return saveManualVariables(body);
    case "saveUserPreferences": return saveUserPreferences(body);
    case "saveRuntimeSettings": return saveRuntimeSettings(body);
    case "saveStrategyMemory": return saveStrategyMemory(body);
    case "buildWikiCurationRequest": return buildWikiCurationRequest(body);
    case "getStrategyWikiStatus": return readStrategyWikiStatus();
    case "updateRankings": return updateRankings();
    case "resetDailySession": return resetDailySession();
    case "getState": await refreshSelectedAdbConnection(); return { ok: true, state: getRuntimeServiceState() };
    case "shutdown": return shutdownRuntime(body);
    case "minimizeWindow": return minimizeWindow(window);
    case "closeWindow": return closeWindow(window);
    default:
      throw new Error(`Unknown runtime action: ${action}`);
  }
}

